    def reports_monthly(self, auth: dict[str, Any], month: str = "") -> dict[str, Any]:
        denied = self._require_reports_access(auth)
        if denied:
            return denied
        month_value = str(month or "").strip()
        if not re.fullmatch(r"20\d{2}-\d{2}", month_value):
            month_value = date.today().strftime("%Y-%m")
        if not self.settings.moyklass_enabled:
            return {"ok": False, "error": "МойКласс отключён в настройках агента."}
        try:
            result = self.moyklass.get_month_analytics(month_value)
            report = self._build_month_report_payload(result, month_value)
        except Exception as exc:
            log.exception("MoyKlass monthly report failed")
            return {"ok": False, "error": f"Не удалось получить отчёт МойКласс: {exc}"}
        return {"ok": True, "month": report.get("month") or month_value, "report": report}

    def reports_monthly_children(self, auth: dict[str, Any], month: str = "") -> dict[str, Any]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in CHILDREN_REPORT_ROLES:
            return {"ok": False, "error": "Отчёт по детям доступен owner, admin, director, client_manager и operations."}
        month_value = str(month or "").strip()
        if not re.fullmatch(r"20\d{2}-\d{2}", month_value):
            month_value = date.today().strftime("%Y-%m")
        if not self.settings.moyklass_enabled:
            return {"ok": False, "error": "МойКласс отключён в настройках агента."}
        import time as _t
        t0 = _t.monotonic()
        try:
            result = self.moyklass.get_monthly_children_report(month_value)
        except Exception as exc:
            log.exception("[monthly-children-report] failed user_id=%s month=%s", auth["user_id"], month_value)
            return {"ok": False, "error": f"Не удалось получить данные из МойКласс: {exc}"}
        elapsed_ms = int((_t.monotonic() - t0) * 1000)
        if not result.ok:
            return {"ok": False, "error": result.error or "Ошибка МойКласс"}
        data = result.data or {}
        log.info(
            "[monthly-children-report] role=%s user_id=%s month=%s "
            "records_total=%s records_attended=%s unique_children=%s elapsed_ms=%s",
            role, auth["user_id"], month_value,
            data.get("records_total", 0), data.get("records_attended", 0),
            data.get("total_unique_children", 0), elapsed_ms,
        )
        return data

    def _require_client_tasks_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in CLIENT_TASK_ROLES:
            return {"ok": False, "error": "Задачи клиент-менеджера доступны клиент-менеджеру, владельцу и операционному менеджеру."}
        return None

    def client_tasks(self, auth: dict[str, Any], status: str = "active", task_type: str = "all", sync: bool = True) -> dict[str, Any]:
        denied = self._require_client_tasks_access(auth)
        if denied:
            return denied
        sync_result: dict[str, Any] = {}
        if sync and (status or "active") in {"active", "all", "new", "in_work"}:
            try:
                sync_result = self.sync_client_tasks_from_moyklass(auth, force=False)
            except Exception as exc:
                log.exception("Client tasks auto sync failed")
                sync_result = {"ok": False, "error": str(exc)[:300]}
        items = self.storage.list_client_manager_tasks(status=status or "active", task_type=task_type or "all", limit=300)
        return {"ok": True, "items": items, "autoSync": sync_result}

    def save_client_task(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_client_tasks_access(auth)
        if denied:
            return denied
        user_id = int(auth["user_id"])
        task_type = str(payload.get("taskType") or payload.get("task_type") or "").strip().lower()
        if task_type not in {"makeup", "trial", "payment"}:
            return {"ok": False, "error": "Выберите тип задачи: отработка, пробное или оплата."}
        client_name = str(payload.get("clientName") or "").strip()
        child_name = str(payload.get("childName") or "").strip()
        if task_type in {"makeup", "trial"} and not (client_name or child_name):
            return {"ok": False, "error": "Укажите клиента или ученика."}
        if task_type == "payment" and not (client_name or child_name):
            return {"ok": False, "error": "Укажите клиента/ученика для задачи по оплате."}
        is_new = not str(payload.get("id") or "").strip()
        item = self.storage.upsert_client_manager_task(
            created_by=user_id,
            task_id=payload.get("id") or "",
            task_type=task_type,
            status=str(payload.get("status") or "new"),
            priority=str(payload.get("priority") or "normal"),
            client_name=client_name,
            child_name=child_name,
            contact=str(payload.get("contact") or ""),
            desired_date=str(payload.get("desiredDate") or ""),
            desired_time=str(payload.get("desiredTime") or ""),
            location=str(payload.get("location") or ""),
            amount=str(payload.get("amount") or ""),
            payment_for=str(payload.get("paymentFor") or ""),
            deadline=str(payload.get("deadline") or ""),
            comment=str(payload.get("comment") or ""),
            result_text=str(payload.get("resultText") or ""),
            source_type=str(payload.get("sourceType") or "manual"),
            source_key=str(payload.get("sourceKey") or ""),
            lesson_id=str(payload.get("lessonId") or ""),
            mk_student_id=str(payload.get("mkStudentId") or ""),
        )
        # Only write "created" event for genuinely new tasks. The upsert can also
        # return an existing task (found via source_key), in which case events
        # already exist — skip to avoid duplicates.
        if is_new and item.get("id"):
            existing_events = self.storage.list_client_task_events(item["id"], limit=1)
            if not existing_events:
                actor_n = str((auth.get("user") or {}).get("first_name") or "")
                ln = str((auth.get("user") or {}).get("last_name") or "").strip()
                if ln:
                    actor_n = (actor_n + " " + ln).strip()
                if not actor_n:
                    st = self.storage.get_staff_user(user_id) or {}
                    actor_n = str(st.get("full_name") or st.get("username") or "")
                self.storage.add_client_task_event(
                    task_id=item["id"],
                    event_type="created",
                    actor_user_id=user_id,
                    actor_name=actor_n,
                    new_status=str(item.get("status") or "new"),
                )
        return {"ok": True, "item": item, "items": self.storage.list_client_manager_tasks(status="active", limit=300)}

    def update_client_task_status(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_client_tasks_access(auth)
        if denied:
            return denied
        task_id = payload.get("id") or payload.get("taskId") or ""
        status = str(payload.get("status") or "").strip().lower()
        if status not in {"new", "in_work", "waiting_client", "waiting_confirm", "done", "cancelled"}:
            return {"ok": False, "error": "Некорректный статус задачи."}
        user_id = int(auth["user_id"])
        old_task = self.storage.get_client_manager_task(task_id) or {}
        old_status = str(old_task.get("status") or "")
        ok = self.storage.update_client_manager_task_status(task_id, status, user_id)
        if not ok:
            return {"ok": False, "error": "Не удалось обновить задачу."}
        # Only record an event if the status actually changed.
        if old_status != status:
            actor_name = str((auth.get("user") or {}).get("first_name") or "")
            last = str((auth.get("user") or {}).get("last_name") or "").strip()
            if last:
                actor_name = (actor_name + " " + last).strip()
            if not actor_name:
                staff = self.storage.get_staff_user(user_id) or {}
                actor_name = str(staff.get("full_name") or staff.get("username") or "")
            self.storage.add_client_task_event(
                task_id=task_id,
                event_type="status_change",
                actor_user_id=user_id,
                actor_name=actor_name,
                old_status=old_status,
                new_status=status,
            )
        return {"ok": True, "items": self.storage.list_client_manager_tasks(status="active", limit=300)}

    def client_tasks_kpi(self, auth: dict[str, Any], date_from: str = "", date_to: str = "") -> dict[str, Any]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in KPI_ROLES:
            return {"ok": False, "error": "KPI задач доступен клиент-менеджеру, владельцу, методисту и операционному менеджеру."}
        try:
            kpi = self.storage.get_client_tasks_kpi(date_from=date_from, date_to=date_to)
            return {"ok": True, "kpi": kpi}
        except Exception as exc:
            log.exception("client_tasks_kpi failed")
            return {"ok": False, "error": f"Не удалось получить KPI: {exc}"}

    def _work_week_start(self, week: str = "current") -> str:
        today = date.today()
        monday = today - timedelta(days=today.weekday())
        if str(week or "current").strip().lower() in {"next", "next_week", "следующая"}:
            monday = monday + timedelta(days=7)
        return monday.isoformat()

    def _work_week_label(self, week_start: str) -> str:
        try:
            start = date.fromisoformat(str(week_start)[:10])
        except Exception:
            start = date.today() - timedelta(days=date.today().weekday())
        end = start + timedelta(days=6)
        return f"{start.strftime('%d.%m')} - {end.strftime('%d.%m')}"

    def _require_work_schedule_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        user_id = int(auth["user_id"])
        role = self._role_for_user(user_id)
        if role not in SCHEDULE_ROLES:
            return {"ok": False, "error": "Для вашей роли расписание работы пока недоступно."}
        return None

    def work_schedule(self, auth: dict[str, Any], week: str = "current") -> dict[str, Any]:
        denied = self._require_work_schedule_access(auth)
        if denied:
            return denied
        user_id = int(auth["user_id"])
        week_start = self._work_week_start(week)
        items = self.storage.list_teacher_work_schedule(user_id=user_id, week_start=week_start, active_only=True, limit=100)
        return {"ok": True, "items": items, "meta": {"week": week, "weekStart": week_start, "weekLabel": self._work_week_label(week_start)}}

    def admin_work_schedule(self, auth: dict[str, Any], week: str = "current") -> dict[str, Any]:
        denied = self._require_admin_tab(auth, "work-schedule")
        if denied:
            return denied
        week_start = self._work_week_start(week)
        items = self.storage.list_teacher_work_schedule(user_id=None, week_start=week_start, active_only=True, limit=800)
        staff_by_user = {int(u.get("user_id")): u for u in self.storage.list_staff_users(limit=1000) if u.get("user_id") is not None}
        for item in items:
            staff = staff_by_user.get(int(item.get("user_id") or 0)) or {}
            item["username"] = staff.get("username") or ""
            item["full_name"] = staff.get("full_name") or ""
            item["role"] = staff.get("role") or ""
            item["mk_teacher_name"] = staff.get("mk_teacher_name") or ""
        return {"ok": True, "items": items, "meta": {"week": week, "weekStart": week_start, "weekLabel": self._work_week_label(week_start)}}

    @staticmethod
    def _time_to_minutes(value: str) -> int:
        m = re.match(r"^(\d{2}):(\d{2})$", str(value or "").strip())
        if not m:
            return -1
        return int(m.group(1)) * 60 + int(m.group(2))

    def _find_work_slot_overlap(self, user_id: int, week_start: str, day: int, start: str, end: str, slot_id: Any = "") -> dict[str, Any] | None:
        start_m = self._time_to_minutes(start)
        end_m = self._time_to_minutes(end)
        if start_m < 0 or end_m < 0:
            return None
        current_id = str(slot_id or "").strip()
        for item in self.storage.list_teacher_work_schedule(user_id=user_id, week_start=week_start, active_only=True, limit=200):
            if current_id and str(item.get("id") or "") == current_id:
                continue
            if int(item.get("day_of_week") or 0) != int(day):
                continue
            other_start = self._time_to_minutes(str(item.get("start_time") or ""))
            other_end = self._time_to_minutes(str(item.get("end_time") or ""))
            if other_start < 0 or other_end < 0:
                continue
            if start_m < other_end and end_m > other_start:
                return item
        return None

    def save_work_schedule_slot(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_work_schedule_access(auth)
        if denied:
            return denied
        user_id = int(auth["user_id"])
        day = _safe_int(payload.get("dayOfWeek"), -1)
        start = str(payload.get("startTime") or "").strip()[:5]
        end = str(payload.get("endTime") or "").strip()[:5]
        location = str(payload.get("location") or "").strip()
        # Преподаватели Yellow Club универсальные: тип занятия и курс не выбираем.
        # Окно означает свободную возможность для пробного, отработки, замены, регулярного или дополнительного занятия.
        work_type = "Любое"
        note = str(payload.get("note") or "").strip()
        slot_id = payload.get("id") or ""
        week = str(payload.get("week") or "current").strip()
        week_start = self._work_week_start(week)
        if day < 0 or day > 6:
            return {"ok": False, "error": "Выберите день недели."}
        if not re.match(r"^\d{2}:\d{2}$", start) or not re.match(r"^\d{2}:\d{2}$", end):
            return {"ok": False, "error": "Укажите время в формате HH:MM."}
        if start >= end:
            return {"ok": False, "error": "Время окончания должно быть позже времени начала."}
        overlap = self._find_work_slot_overlap(user_id=user_id, week_start=week_start, day=day, start=start, end=end, slot_id=slot_id)
        if overlap:
            return {"ok": False, "error": f"Это окно пересекается с уже добавленным временем: {str(overlap.get('start_time') or '')[:5]}-{str(overlap.get('end_time') or '')[:5]}."}
        row = self.storage.upsert_teacher_work_slot(
            user_id=user_id,
            mk_teacher_id=self._mk_teacher_id_for_user(user_id),
            day_of_week=day,
            start_time=start,
            end_time=end,
            location=location,
            work_type=work_type,
            note=note,
            week_start=week_start,
            slot_id=slot_id,
        )
        items = self.storage.list_teacher_work_schedule(user_id=user_id, week_start=week_start, active_only=True, limit=100)
        return {"ok": True, "item": row, "items": items, "meta": {"week": week, "weekStart": week_start, "weekLabel": self._work_week_label(week_start)}}

    def delete_work_schedule_slot(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_work_schedule_access(auth)
        if denied:
            return denied
        user_id = int(auth["user_id"])
        slot_id = payload.get("id") or ""
        week = str(payload.get("week") or "current").strip()
        week_start = self._work_week_start(week)
        ok = self.storage.delete_teacher_work_slot(user_id, slot_id)
        if not ok:
            return {"ok": False, "error": "Не удалось удалить интервал."}
        return {"ok": True, "items": self.storage.list_teacher_work_schedule(user_id=user_id, week_start=week_start, active_only=True, limit=100), "meta": {"week": week, "weekStart": week_start, "weekLabel": self._work_week_label(week_start)}}

    def _require_open_slots_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        user_id = int(auth["user_id"])
        role = self._role_for_user(user_id)
        if role not in OPEN_SLOTS_ROLES and role not in ADMIN_ROLES:
            return {"ok": False, "error": "Просмотр свободных окон доступен клиент-менеджеру, методисту и админу."}
        return None

    def open_slots(self, auth: dict[str, Any], week: str = "current", location: str = "all") -> dict[str, Any]:
        denied = self._require_open_slots_access(auth)
        if denied:
            return denied
        week_start = self._work_week_start(week)
        items = self.storage.list_teacher_work_schedule(user_id=None, week_start=week_start, active_only=True, limit=1000)
        staff_by_user = {int(u.get("user_id")): u for u in self.storage.list_staff_users(limit=1000) if u.get("user_id") is not None}
        try:
            start_date = date.fromisoformat(str(week_start)[:10])
        except Exception:
            start_date = date.today() - timedelta(days=date.today().weekday())
        location_filter = str(location or "all").strip().lower()
        filtered: list[dict[str, Any]] = []
        for item in items:
            loc = str(item.get("location") or "Любой формат").strip() or "Любой формат"
            if location_filter not in {"", "all", "все"} and loc.lower() != location_filter:
                continue
            staff = staff_by_user.get(int(item.get("user_id") or 0)) or {}
            teacher_name = staff.get("mk_teacher_name") or staff.get("full_name") or staff.get("username") or item.get("mk_teacher_id") or f"ID {item.get('user_id') or ''}".strip()
            try:
                day = max(0, min(6, int(item.get("day_of_week") or 0)))
            except Exception:
                day = 0
            slot_date = start_date + timedelta(days=day)
            row = dict(item)
            row["teacher_name"] = teacher_name
            row["teacher_full_name"] = staff.get("full_name") or ""
            row["teacher_username"] = staff.get("username") or ""
            row["role"] = staff.get("role") or ""
            row["location"] = loc
            row["date"] = slot_date.isoformat()
            row["date_label"] = slot_date.strftime("%d.%m")
            row["day_name"] = ["Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота", "Воскресенье"][day]
            row["day_short"] = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"][day]
            filtered.append(row)
        filtered.sort(key=lambda x: (str(x.get("date") or ""), str(x.get("start_time") or ""), str(x.get("teacher_name") or "")))
        unique_teachers = len({str(x.get("user_id") or x.get("mk_teacher_id") or x.get("teacher_name")) for x in filtered})
        return {
            "ok": True,
            "items": filtered,
            "meta": {
                "week": week,
                "weekStart": week_start,
                "weekLabel": self._work_week_label(week_start),
                "total": len(filtered),
                "teachers": unique_teachers,
            },
        }

    def upload_prep_result(self, auth: dict[str, Any], fields: dict[str, str], files: dict[str, dict[str, Any]]) -> dict[str, Any]:
        user_id = int(auth["user_id"])
        lesson_id = str(fields.get("lessonId") or "").strip()
        if not lesson_id:
            return {"ok": False, "error": "Не указан lessonId."}
        detail = self.lesson_detail(auth, lesson_id)
        if not detail.get("ok"):
            return detail
        file = files.get("file")
        if not file or not file.get("content"):
            return {"ok": False, "error": "Файл не прикреплён."}
        content = file.get("content") or b""
        if len(content) > 40 * 1024 * 1024:
            return {"ok": False, "error": "Файл слишком большой. Максимум 40 МБ."}
        original_name = _safe_filename(str(file.get("filename") or "result.bin"))
        lesson_dir = BASE_DIR / "data" / "prep_results" / re.sub(r"[^0-9A-Za-zА-Яа-яёЁ_.-]+", "_", lesson_id)
        lesson_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        stored_name = f"{stamp}_{user_id}_{original_name}"
        stored_path = lesson_dir / stored_name
        stored_path.write_bytes(content)
        result_row = self.storage.add_teacher_prep_result_file(
            lesson_id=lesson_id,
            teacher_user_id=user_id,
            file_name=original_name,
            stored_path=str(stored_path),
            mime_type=str(file.get("content_type") or "application/octet-stream"),
            size_bytes=len(content),
        )
        # Notify senior teacher/reviewers and attach the actual file.
        lesson = detail.get("lesson") or {}
        caption = "\n".join([
            "📤 Результат подготовки на проверку",
            f"Преподаватель: {lesson.get('teacher') or user_id}",
            f"Группа: {lesson.get('group') or '-'}",
            f"Дата: {lesson.get('date') or '-'}",
            f"Время: {lesson.get('time') or '-'}",
            f"Тема: {lesson.get('topic') or '-'}",
            f"Файл: {original_name}",
            "Проверка: Mini App -> Админ -> Проверка работ.",
        ])
        recipients = self._prep_result_reviewer_ids()
        sent_documents = 0
        for reviewer_id in recipients:
            ok, err = _telegram_send_document(
                self.settings.telegram_bot_token,
                int(reviewer_id),
                stored_path,
                original_name,
                caption,
                str(file.get("content_type") or "application/octet-stream"),
            )
            self.storage.add_notification_log("prep_result_document_sent", caption, int(reviewer_id), lesson_id, result_row.get("id"), ok, err)
            if ok:
                sent_documents += 1
            else:
                fallback_text = caption + "\n\n⚠️ Файл сохранён в Mini App, но Telegram не смог отправить документ. Откройте его через Админ -> Проверка работ -> Скачать файл."
                text_ok, text_err = _telegram_send(self.settings.telegram_bot_token, int(reviewer_id), fallback_text)
                self.storage.add_notification_log("prep_result_document_fallback", fallback_text, int(reviewer_id), lesson_id, result_row.get("id"), text_ok, text_err or err)

        if not recipients:
            response_message = "Файл сохранён, но не настроен получатель проверки. Добавьте SENIOR_TEACHER_IDS в .env или назначьте сотруднику роль methodist."
        elif sent_documents:
            response_message = "Результат отправлен старшему преподавателю в Telegram. Статус: ожидает проверки."
        else:
            response_message = "Файл сохранён и поставлен на проверку, но Telegram не смог отправить документ. Старший преподаватель сможет скачать его в Mini App."
        return {"ok": True, "file": result_row, "message": response_message, "sentDocuments": sent_documents, "reviewers": recipients}

    def review_prep_result(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_admin(auth)
        if denied:
            return denied
        file_id = payload.get("fileId") or payload.get("id")
        decision = str(payload.get("decision") or "").strip().lower()
        comment = str(payload.get("comment") or "").strip()
        if decision not in {"approved", "rejected"}:
            return {"ok": False, "error": "Решение должно быть approved или rejected."}
        row = self.storage.review_teacher_prep_result_file(file_id, int(auth["user_id"]), decision, comment)
        if not row:
            return {"ok": False, "error": "Файл не найден."}
        lesson_id = str(row.get("lesson_id") or "")
        teacher_id = row.get("teacher_user_id")
        status_text = "подтверждён" if decision == "approved" else "отклонён"
        icon = "✅" if decision == "approved" else "❌"
        lesson_label = ""
        control = self.storage.get_teacher_lesson_control(lesson_id) or {}
        if control:
            lesson_label = f"\nЗанятие: {control.get('group_name') or '-'} · {control.get('lesson_date') or '-'} {control.get('lesson_time') or ''}"
        msg = f"{icon} Результат подготовки {status_text} старшим преподавателем.{lesson_label}"
        if comment:
            msg += f"\nКомментарий: {comment}"
        msg += "\n\nОбратная связь также отображается в карточке занятия."
        ok, err = _telegram_send(self.settings.telegram_bot_token, int(teacher_id) if teacher_id else None, msg)
        self.storage.add_notification_log("prep_result_reviewed", msg, int(teacher_id) if teacher_id else None, lesson_id, None, ok, err)
        return {"ok": True, "item": row}

    def action(self, auth: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        user_id = int(auth["user_id"])
        lesson_id = str(payload.get("lessonId") or "").strip()
        action = str(payload.get("action") or "").strip()
        comment = str(payload.get("comment") or "").strip()
        if not lesson_id:
            return {"ok": False, "error": "Не указан lessonId."}
        # Re-read lesson to verify ownership and fill control fields.
        detail = self.lesson_detail(auth, lesson_id)
        if not detail.get("ok"):
            return detail
        if action == "prepare_ready":
            row = self.storage.mark_teacher_preparation(lesson_id, user_id, "ready")
        elif action == "prepare_help":
            row = self.storage.mark_teacher_preparation(lesson_id, user_id, "needs_help", comment=comment)
        elif action == "prep_material_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_material", "done", user_id=user_id)
        elif action == "prep_material_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_material", "not_checked", user_id=user_id)
        elif action == "prep_video_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_video", "done", user_id=user_id)
        elif action == "prep_video_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_video", "not_checked", user_id=user_id)
        elif action == "prep_practice_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_practice", "done", user_id=user_id)
        elif action == "prep_practice_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "prep_practice", "not_checked", user_id=user_id)
        elif action == "prep_result_sent":
            return {"ok": False, "error": "Теперь результат подготовки нужно отправлять файлом через кнопку “Отправить результат”."}
        elif action in {"prep_study_done", "prep_all_done"}:
            row = self.storage.upsert_teacher_lesson_control(
                lesson_id,
                teacher_user_id=user_id,
                prep_material_status="done",
                prep_video_status="done",
                prep_practice_status="done",
            )
        elif action == "parent_report_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "parent_report", "done", user_id=user_id)
        elif action == "parent_report_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "parent_report", "not_checked", user_id=user_id)
        elif action == "myclass_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "myclass", "done", user_id=user_id)
        elif action == "myclass_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "myclass", "not_checked", user_id=user_id)
        elif action == "works_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "works", "done", user_id=user_id)
        elif action == "works_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "works", "not_checked", user_id=user_id)
        elif action == "classroom_done":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "classroom", "done", user_id=user_id)
        elif action == "classroom_not_checked":
            row = self.storage.mark_teacher_lesson_step(lesson_id, "classroom", "not_checked", user_id=user_id)
        elif action == "lesson_comment":
            if not comment.strip():
                return {"ok": False, "error": "Комментарий пустой."}
            row = self.storage.set_teacher_lesson_comment(lesson_id, user_id, comment)
        elif action == "problem":
            row = self.storage.mark_teacher_lesson_problem(lesson_id, user_id, comment or "Проблема без комментария")
        elif action == "close":
            current = self.storage.get_teacher_lesson_control(lesson_id) or {}
            missing = _missing_close_steps(current)
            if missing and str(current.get("problem_status") or "") != "problem":
                return {"ok": False, "error": "Нельзя закрыть занятие. Не отмечено: " + ", ".join(missing)}
            row = self.storage.close_teacher_lesson(lesson_id, user_id)
        else:
            return {"ok": False, "error": "Неизвестное действие."}
        row = row or self.storage.get_teacher_lesson_control(lesson_id) or {}
        if action.startswith("prep_"):
            if _all_prep_steps_done(row):
                row = self.storage.mark_teacher_preparation(lesson_id, user_id, "ready")
            elif action.endswith("_not_checked"):
                row = self.storage.mark_teacher_preparation(lesson_id, user_id, "not_started")
        return {"ok": True, "control": row}

    # ── bePaid integration ─────────────────────────────────────────────────────

    _BEPAID_REPORT_URL = "https://merchant.bepaid.by/api/reports"

    def _bepaid_fetch_shop_transactions(
        self,
        shop_type: str,
        shop_id: str,
        secret_key: str,
        from_dt: str,
        to_dt: str,
        payment_method_types: list[str],
        time_zone: str = "Europe/Minsk",
        max_total: int = 5000,
    ) -> tuple[list[dict[str, Any]], str, bool, dict[str, Any]]:
        """Call bePaid /api/reports (X-Api-Version: 2) day-by-day for one shop.

        Per official bePaid reports docs: endpoint accepts a single date per
        request, not a date range. Iterates each calendar day in [from_dt, to_dt).
        Never logs or exposes secret_key or Authorization header.
        """
        import requests as _req
        from datetime import date as _date, timedelta as _td

        try:
            from_date = _date.fromisoformat(from_dt[:10])
            to_date = _date.fromisoformat(to_dt[:10])  # exclusive upper bound
        except Exception as exc:
            return [], f"date parse error: {exc}", False, {}

        days: list[str] = []
        _cur = from_date
        while _cur < to_date:
            days.append(_cur.isoformat())
            _cur += _td(days=1)

        diag: dict[str, Any] = {
            "shop_id_present": bool(shop_id),
            "secret_key_present": bool(secret_key),
            "shop_id_last4": shop_id[-4:] if len(shop_id) >= 4 else "****",
            "secret_key_length": len(secret_key),
            "endpoint_used": self._BEPAID_REPORT_URL,
            "api_version_header_used": "2",
            "date_type": "paid_at",
            "days_requested": len(days),
            "payment_method_types_requested": payment_method_types,
            "response_status": None,
            "response_reason": None,
            "response_body_preview": None,
            "request_body_sanitized": None,
            "auth_error": False,
            "versions_tried": ["2"],
            "exception_type": None,
            "exception_message": None,
            "per_day_error_statuses": {},
            "imported_per_day": {},
            "imported_per_method": {pmt: 0 for pmt in payment_method_types},
        }

        all_tx: list[dict[str, Any]] = []
        last_error = ""
        api_supported = False

        for pmt in payment_method_types:
            for day_str in days:
                base_body: dict[str, Any] = {
                    "report_params": {
                        "date_type": "paid_at",
                        "date": day_str,
                        "status": "all",
                        "payment_method_type": pmt,
                        "time_zone": time_zone,
                    }
                }
                diag["request_body_sanitized"] = base_body  # no credentials in body

                cursor = None
                for _page in range(10):  # pagination safety limit per day
                    req_body = dict(base_body)
                    if cursor:
                        req_body["starting_after"] = cursor

                    try:
                        resp = _req.post(
                            self._BEPAID_REPORT_URL,
                            json=req_body,
                            auth=(shop_id, secret_key),
                            headers={
                                "X-Api-Version": "2",
                                "Content-Type": "application/json",
                                "Accept": "application/json",
                            },
                            timeout=30,
                        )
                    except Exception as exc:
                        diag["exception_type"] = type(exc).__name__
                        diag["exception_message"] = str(exc)[:200]
                        last_error = f"network error: {exc}"
                        log.warning(
                            "bePaid import network error shop_type=%s endpoint=%s exc_type=%s exc=%s",
                            shop_type, self._BEPAID_REPORT_URL, type(exc).__name__, str(exc)[:200],
                        )
                        return all_tx, last_error, api_supported, diag

                    diag["response_status"] = resp.status_code
                    diag["response_reason"] = getattr(resp, "reason", None) or ""
                    try:
                        diag["response_body_preview"] = resp.text[:1000]
                    except Exception:
                        diag["response_body_preview"] = ""

                    if resp.status_code == 401:
                        diag["auth_error"] = True
                        last_error = (
                            "bePaid отклонил авторизацию на reports API v2. "
                            "Проверьте Shop ID и Secret Key именно этого магазина. "
                            "Возможно, доступ к Reporting API не активирован — "
                            "обратитесь в поддержку bePaid."
                        )
                        api_supported = True  # endpoint reachable, credentials rejected
                        log.warning(
                            "bePaid import auth failed shop_type=%s api_version=2 endpoint=%s "
                            "shop_id_last4=%s secret_key_length=%s body_preview=%s",
                            shop_type, self._BEPAID_REPORT_URL,
                            diag["shop_id_last4"], diag["secret_key_length"],
                            (diag.get("response_body_preview") or "")[:200],
                        )
                        return all_tx, last_error, api_supported, diag  # no point retrying days

                    if resp.status_code in (404, 501, 405):
                        last_error = f"HTTP {resp.status_code}: endpoint not supported"
                        log.warning(
                            "bePaid import endpoint not supported shop_type=%s status=%s endpoint=%s",
                            shop_type, resp.status_code, self._BEPAID_REPORT_URL,
                        )
                        return all_tx, last_error, api_supported, diag

                    api_supported = True

                    if not resp.ok:
                        try:
                            err_body = resp.json()
                            day_error = str(err_body.get("message") or err_body)[:300]
                        except Exception:
                            day_error = f"HTTP {resp.status_code}: {resp.text[:200]}"
                        last_error = day_error
                        diag["per_day_error_statuses"][f"{day_str}/{pmt}"] = resp.status_code
                        log.warning(
                            "bePaid import API error shop_type=%s day=%s pmt=%s status=%s body=%s",
                            shop_type, day_str, pmt, resp.status_code,
                            (diag.get("response_body_preview") or "")[:200],
                        )
                        break  # skip this day/pmt, continue with the rest

                    try:
                        data = resp.json()
                    except Exception:
                        last_error = "invalid JSON in API response"
                        break

                    items = data.get("transactions") or []
                    all_tx.extend(items)
                    day_key = f"{day_str}/{pmt}"
                    diag["imported_per_day"][day_key] = diag["imported_per_day"].get(day_key, 0) + len(items)
                    diag["imported_per_method"][pmt] = diag["imported_per_method"].get(pmt, 0) + len(items)

                    if not data.get("has_more") or not items:
                        break
                    cursor = data.get("last_object_id")
                    if not cursor:
                        break
                    if len(all_tx) >= max_total:
                        log.warning("bePaid import: reached max_total=%d for %s/%s/%s", max_total, shop_type, pmt, day_str)
                        break

        return all_tx, last_error, api_supported, diag

    def bepaid_import_history(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/integrations/bepaid/import-history — import bePaid txns via API."""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in BEPAID_RECONCILE_ROLES:
            return {"ok": False, "error": "access_denied"}

        month = str(body.get("month") or "").strip()
        shop_type_filter = str(body.get("shop_type") or "all").strip()

        if not month:
            from datetime import date as _d
            month = _d.today().strftime("%Y-%m")

        try:
            year, mnum = int(month[:4]), int(month[5:7])
        except Exception:
            return {"ok": False, "error": "invalid month format, expected YYYY-MM"}

        from_dt = f"{year}-{mnum:02d}-01 00:00:00"
        if mnum == 12:
            to_dt = f"{year + 1}-01-01 00:00:00"
        else:
            to_dt = f"{year}-{mnum + 1:02d}-01 00:00:00"

        cfg = self.settings
        shops: list[tuple[str, str, str, list[str]]] = []  # (shop_type, shop_id, secret, pmt_types)
        if shop_type_filter in ("all", "erip") and getattr(cfg, "bepaid_erip_enabled", False):
            shops.append(("erip", cfg.bepaid_erip_shop_id, cfg.bepaid_erip_secret_key, ["erip"]))
        if shop_type_filter in ("all", "acquiring") and getattr(cfg, "bepaid_acq_enabled", False):
            shops.append(("acquiring", cfg.bepaid_acq_shop_id, cfg.bepaid_acq_secret_key, ["credit_card", "alternative"]))

        if not shops:
            return {
                "ok": False,
                "api_supported": False,
                "message": (
                    "bePaid не настроен для выбранного типа магазина. "
                    "Задайте BEPAID_ERIP_SHOP_ID/SECRET_KEY и/или BEPAID_ACQ_SHOP_ID/SECRET_KEY."
                ),
            }

        total_inserted = 0
        total_updated = 0
        total_skipped = 0
        total_loaded = 0
        api_supported = False
        warnings: list[str] = []
        shop_results: dict[str, Any] = {}
        shop_diags: dict[str, Any] = {}
        import_at = now_iso()
        any_auth_error = False

        for st, sid, skey, pmt_types in shops:
            raw_txns, fetch_error, shop_api_ok, shop_diag = self._bepaid_fetch_shop_transactions(
                st, sid, skey, from_dt, to_dt, pmt_types
            )
            if shop_api_ok:
                api_supported = True
            if shop_diag.get("auth_error"):
                any_auth_error = True

            shop_diags[st] = shop_diag

            if not raw_txns and fetch_error:
                shop_results[st] = {
                    "api_supported": shop_api_ok,
                    "auth_error": shop_diag.get("auth_error", False),
                    "loaded": 0,
                    "inserted": 0,
                    "updated": 0,
                    "skipped": 0,
                    "error": fetch_error,
                    "shop_id_last4": shop_diag.get("shop_id_last4"),
                    "secret_key_length": shop_diag.get("secret_key_length"),
                    "versions_tried": shop_diag.get("versions_tried"),
                    "response_status": shop_diag.get("response_status"),
                }
                warnings.append(f"{st}: {fetch_error}")
                continue

            ins = upd = skp = 0
            seen_uids: set[str] = set()

            for raw_tx in raw_txns:
                uid_key = str(raw_tx.get("uid") or raw_tx.get("id") or "")
                if uid_key and uid_key in seen_uids:
                    skp += 1
                    continue
                if uid_key:
                    seen_uids.add(uid_key)

                try:
                    extracted = self._bepaid_extract_payload(raw_tx, st, sid)
                    _row, is_new = self.storage.upsert_bepaid_transaction(extracted)
                    if is_new:
                        ins += 1
                    else:
                        upd += 1
                except Exception as exc:
                    skp += 1
                    warnings.append(f"{st} save error: {exc}")

            total_loaded += len(raw_txns)
            total_inserted += ins
            total_updated += upd
            total_skipped += skp
            shop_results[st] = {
                "api_supported": True,
                "auth_error": False,
                "loaded": len(raw_txns),
                "inserted": ins,
                "updated": upd,
                "skipped": skp,
                "error": fetch_error,
                "versions_tried": shop_diag.get("versions_tried"),
                "api_version_used": shop_diag.get("api_version_header_used"),
            }
            if fetch_error:
                warnings.append(f"{st}: {fetch_error}")

        # All shops returned auth error → surface as explicit error, not silent zeros
        if any_auth_error and total_loaded == 0 and not any(
            not r.get("auth_error") for r in shop_results.values()
        ):
            auth_shops = [st for st, r in shop_results.items() if r.get("auth_error")]
            _auth_msg = (
                "bePaid отклонил авторизацию на reports API v2. "
                "Проверьте Shop ID и Secret Key именно этого магазина. "
                "Возможно, доступ к Reporting API не активирован — "
                "обратитесь в поддержку bePaid. "
                "Public Key не подходит для API-запросов."
            )
            return {
                "ok": False,
                "auth_error": True,
                "api_supported": True,
                "error": _auth_msg,
                "message": _auth_msg,
                "month": month,
                "shops_with_auth_error": auth_shops,
                "shops": shop_results,
                "warnings": warnings,
                "diagnostics": {
                    st: {
                        "shop_id_present": d.get("shop_id_present"),
                        "secret_key_present": d.get("secret_key_present"),
                        "shop_id_last4": d.get("shop_id_last4"),
                        "secret_key_length": d.get("secret_key_length"),
                        "endpoint_used": d.get("endpoint_used"),
                        "versions_tried": d.get("versions_tried"),
                        "response_status": d.get("response_status"),
                        "response_reason": d.get("response_reason"),
                        "response_body_preview": d.get("response_body_preview"),
                        "auth_error": d.get("auth_error"),
                    }
                    for st, d in shop_diags.items()
                },
            }

        if not api_supported:
            _no_ep_msg = (
                "В bePaid API не найден официальный endpoint списка транзакций по периоду. "
                "Попробуйте позже или импортируйте CSV/XLSX из кабинета bePaid."
            )
            return {
                "ok": False,
                "api_supported": False,
                "error": _no_ep_msg,
                "message": _no_ep_msg,
                "month": month,
                "shops": shop_results,
                "warnings": warnings,
                "diagnostics": {
                    st: {
                        "endpoint_used": d.get("endpoint_used"),
                        "versions_tried": d.get("versions_tried"),
                        "response_status": d.get("response_status"),
                        "response_reason": d.get("response_reason"),
                        "response_body_preview": d.get("response_body_preview"),
                    }
                    for st, d in shop_diags.items()
                },
            }

        return {
            "ok": True,
            "month": month,
            "shop_type": shop_type_filter,
            "api_supported": True,
            "from": from_dt,
            "to": to_dt,
            "imported": total_loaded,
            "inserted": total_inserted,
            "updated": total_updated,
            "skipped": total_skipped,
            "import_at": import_at,
            "shops": shop_results,
            "warnings": warnings,
            "diagnostics": {
                "bepaid_import_api_supported": True,
                "bepaid_import_last_run_at": import_at,
                "bepaid_import_month": month,
                "bepaid_import_shop_type": shop_type_filter,
                "bepaid_import_erip_loaded": shop_results.get("erip", {}).get("loaded", 0),
                "bepaid_import_acquiring_loaded": shop_results.get("acquiring", {}).get("loaded", 0),
                "bepaid_import_inserted": total_inserted,
                "bepaid_import_updated": total_updated,
                "bepaid_import_errors": len(warnings),
                "bepaid_import_endpoint_used": self._BEPAID_REPORT_URL,
                "bepaid_import_warning": warnings[0] if warnings else "",
                "per_shop": {
                    st: {
                        "shop_id_present": d.get("shop_id_present"),
                        "secret_key_present": d.get("secret_key_present"),
                        "shop_id_last4": d.get("shop_id_last4"),
                        "secret_key_length": d.get("secret_key_length"),
                        "endpoint_used": d.get("endpoint_used"),
                        "api_version_used": d.get("api_version_header_used"),
                        "date_type": d.get("date_type"),
                        "days_requested": d.get("days_requested"),
                        "payment_method_types_requested": d.get("payment_method_types_requested"),
                        "response_status": d.get("response_status"),
                        "response_reason": d.get("response_reason"),
                        "response_body_preview": d.get("response_body_preview"),
                        "per_day_error_statuses": d.get("per_day_error_statuses"),
                        "imported_per_method": d.get("imported_per_method"),
                    }
                    for st, d in shop_diags.items()
                },
            },
        }

    def _bepaid_verify_signature(self, body: bytes, signature_header: str, public_key_pem: str) -> tuple[bool, str]:
        """Verify bePaid Content-Signature header using RSA public key. Returns (ok, reason).

        bePaid signs raw request body bytes with RSA PKCS#1 v1.5 + SHA-256 and encodes
        the signature in Base64 (NOT hex). The header may optionally be prefixed with
        'sha256='. Both PEM (BEGIN PUBLIC KEY) and Base64-encoded DER public keys
        are supported.

        Security: signature value and public key are never logged.
        """
        if not public_key_pem:
            return True, "no_public_key_configured"
        if not signature_header:
            return False, "missing_signature_header"
        try:
            from cryptography.hazmat.primitives import hashes, serialization
            from cryptography.hazmat.primitives.asymmetric import padding as asym_padding
            from cryptography.hazmat.primitives.serialization import load_der_public_key
        except ImportError:
            log.warning("bePaid: cryptography package not installed; skipping RSA signature verification")
            return True, "crypto_unavailable"

        import base64 as _b64
        try:
            sig_str = signature_header.strip()
            # Strip optional "sha256=" or "sha1=" algorithm prefix
            for _prefix in ("sha256=", "sha1="):
                if sig_str.lower().startswith(_prefix):
                    sig_str = sig_str[len(_prefix):]
                    break

            # Decode signature from Base64 (bePaid uses Base64, NOT hex)
            try:
                sig_bytes = _b64.b64decode(sig_str, validate=True)
            except Exception:
                log.warning(
                    "bePaid signature: malformed_base64 shop_type=? signature_present=%s signature_encoding=base64",
                    bool(signature_header),
                )
                return False, "malformed_base64_signature"
            if not sig_bytes:
                return False, "empty_signature"

            # Load public key — supports PEM (contains "BEGIN") and Base64-encoded DER
            key_str = public_key_pem.strip()
            if "BEGIN" in key_str:
                pem_bytes = key_str.encode("utf-8") if isinstance(key_str, str) else key_str
                pub_key = serialization.load_pem_public_key(pem_bytes)
                _key_fmt = "pem"
            else:
                try:
                    der_bytes = _b64.b64decode(key_str)
                    pub_key = load_der_public_key(der_bytes)
                    _key_fmt = "der"
                except Exception as _ke:
                    log.warning("bePaid signature: invalid_public_key_format error_class=%s", type(_ke).__name__)
                    return False, f"invalid_public_key_format: {type(_ke).__name__}"

            # Verify raw body bytes against RSA PKCS#1 v1.5 + SHA-256
            pub_key.verify(sig_bytes, body, asym_padding.PKCS1v15(), hashes.SHA256())
            log.info(
                "bePaid signature verified: signature_encoding=base64 key_format=%s",
                _key_fmt,
            )
            return True, "verified"
        except Exception as _e:
            _cls = type(_e).__name__
            log.warning(
                "bePaid signature verify_failed: signature_present=%s signature_encoding=base64 error_class=%s",
                bool(signature_header), _cls,
            )
            return False, f"verify_failed: {_cls}"

    def _bepaid_extract_payload(self, raw_json: dict[str, Any], shop_type: str, shop_id: str) -> dict[str, Any]:
        """Extract normalised fields from bePaid webhook or API list payload."""
        # Webhook: {"transaction": {...}}; API list: item is the transaction itself
        if "transaction" in raw_json and isinstance(raw_json["transaction"], dict):
            tx = raw_json["transaction"]
        elif "uid" in raw_json or "status" in raw_json:
            tx = raw_json  # API list item
        else:
            tx = raw_json.get("transaction") or {}
        customer = tx.get("customer") or {}
        billing = tx.get("billing_address") or {}
        additional = tx.get("additional_data") or {}

        amount_raw = tx.get("amount")
        try:
            amount_minor = int(amount_raw) if amount_raw is not None else None
        except (TypeError, ValueError):
            amount_minor = None
        amount_byn = round(amount_minor / 100.0, 2) if amount_minor is not None else None

        tracking_id = str(tx.get("tracking_id") or "").strip() or None
        order_id_raw = (tx.get("order") or {}).get("id") or tx.get("order_id") or None
        order_id = str(order_id_raw or "").strip() or None

        customer_phone = (
            str(customer.get("phone") or "").strip() or
            str(billing.get("phone") or "").strip() or None
        )

        # Try to find mk_user_id in various fields; track which field it came from
        import re as _re
        _id_sources = [
            ("tracking_id", tracking_id),
            ("order_id", order_id),
            ("additional_data.contract_number", str(additional.get("contract_number") or "")),
            ("additional_data.user_id", str(additional.get("user_id") or "")),
            ("additional_data.mk_user_id", str(additional.get("mk_user_id") or "")),
            ("custom_fields.user_id", str((tx.get("custom_fields") or {}).get("user_id") or "")),
            ("custom_fields.mk_user_id", str((tx.get("custom_fields") or {}).get("mk_user_id") or "")),
        ]
        mk_user_id = None
        mk_user_id_source = None
        numeric_candidates: list[str] = []
        for _src_name, _src_val in _id_sources:
            if _src_val:
                for _m in _re.finditer(r'\b(\d{4,9})\b', _src_val):
                    _cand = _m.group(1)
                    if _cand not in numeric_candidates:
                        numeric_candidates.append(_cand)
                if mk_user_id is None:
                    _m2 = _re.search(r'\b(\d{4,9})\b', _src_val)
                    if _m2:
                        mk_user_id = _m2.group(1)
                        mk_user_id_source = _src_name

        erip_section = tx.get("erip") or {}
        if not isinstance(erip_section, dict):
            erip_section = {}
        erip_account_number = str(erip_section.get("account_number") or "").strip() or None

        return {
            "provider": "bepaid",
            "shop_type": shop_type,
            "shop_id": shop_id,
            "transaction_uid": str(tx.get("uid") or "").strip() or None,
            "transaction_id": str(tx.get("id") or "").strip() or None,
            "order_id": order_id,
            "tracking_id": tracking_id,
            "status": str(tx.get("status") or "").strip() or None,
            "payment_method_type": str(tx.get("payment_method_type") or "").strip() or None,
            "amount_minor": amount_minor,
            "amount_byn": amount_byn,
            "currency": str(tx.get("currency") or "").strip().upper() or None,
            "paid_at": str(tx.get("paid_at") or "").strip() or None,
            "created_at_provider": str(tx.get("created_at") or "").strip() or None,
            "test": bool(tx.get("test")),
            "customer_first_name": str(customer.get("first_name") or "").strip() or None,
            "customer_last_name": str(customer.get("last_name") or "").strip() or None,
            "customer_phone": customer_phone,
            "customer_email": str(customer.get("email") or "").strip() or None,
            "billing_phone": str(billing.get("phone") or "").strip() or None,
            "description": str(tx.get("description") or "").strip() or None,
            "mk_user_id": mk_user_id,
            "mk_user_id_source": mk_user_id_source,
            "erip_account_number": erip_account_number,
            "raw_json": raw_json,
        }

    def bepaid_handle_webhook(self, shop_type: str, raw_body: bytes,
                               content_signature: str, path_secret: str) -> tuple[dict[str, Any], int]:
        """Process an incoming bePaid webhook. Returns (response_dict, http_status)."""
        cfg = self.settings
        # Validate path secret if configured
        expected_secret = getattr(cfg, "bepaid_webhook_path_secret", "")
        if expected_secret and path_secret != expected_secret:
            log.warning("bePaid webhook: invalid path secret from %s", shop_type)
            return {"ok": False, "error": "invalid_secret"}, 403

        # Select shop config
        if shop_type == "erip":
            shop_id = getattr(cfg, "bepaid_erip_shop_id", "")
            public_key_pem = getattr(cfg, "bepaid_erip_public_key", "")
        elif shop_type in ("acquiring", "acq"):
            shop_type = "acquiring"
            shop_id = getattr(cfg, "bepaid_acq_shop_id", "")
            public_key_pem = getattr(cfg, "bepaid_acq_public_key", "")
        else:
            shop_id = ""
            public_key_pem = ""

        # Verify signature
        sig_ok, sig_reason = self._bepaid_verify_signature(raw_body, content_signature, public_key_pem)
        if not sig_ok:
            log.warning("bePaid webhook: signature verification failed (%s) for shop_type=%s", sig_reason, shop_type)
            return {"ok": False, "error": f"signature_failed: {sig_reason}"}, 401

        # Parse JSON
        try:
            payload = json.loads(raw_body.decode("utf-8", errors="replace"))
        except Exception as e:
            return {"ok": False, "error": f"invalid_json: {e}"}, 400

        # Extract and save
        try:
            extracted = self._bepaid_extract_payload(payload, shop_type, shop_id)
            saved, is_new = self.storage.upsert_bepaid_transaction(extracted)
            tx_id = saved.get("id")
            tx_uid = extracted.get("transaction_uid") or ""
            tx_status = extracted.get("status") or ""
            amount_minor = extracted.get("amount_minor")
            currency = str(extracted.get("currency") or "").strip()
            is_test = bool(extracted.get("test"))
            paid_at = extracted.get("paid_at") or ""
            sig_verified = sig_reason == "verified"

            log.info(
                "bePaid webhook %s: id=%s shop=%s status=%s amount_byn=%s sig=%s test=%s",
                "inserted" if is_new else "updated",
                tx_id, shop_type, tx_status,
                extracted.get("amount_byn"), sig_reason, is_test,
            )

            # Audit: received
            self.storage.log_payment_webhook_audit(
                "webhook_received",
                bepaid_tx_id=tx_id,
                transaction_uid=tx_uid or None,
                shop_type=shop_type,
                status=tx_status or None,
                amount_minor=amount_minor,
                currency=currency or None,
                reason=sig_reason,
            )

            if sig_verified:
                # Persist signature verification result BEFORE matching.
                # webhook_verified must reflect cryptographic outcome only —
                # not matching result, intent state, or reconciliation status.
                if tx_id:
                    from utils import now_iso as _now_iso_ver
                    self.storage.mark_bepaid_transaction_signature_verified(
                        tx_id,
                        verified_at=_now_iso_ver(),
                        verification_method="rsa_pkcs1v15_sha256",
                    )
                self.storage.log_payment_webhook_audit(
                    "webhook_signature_verified",
                    bepaid_tx_id=tx_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    status=tx_status or None,
                    reason="rsa_pkcs1v15_ok",
                )

            # Only process "successful" payments; flag refunds/chargebacks for review
            if tx_status != "successful":
                if tx_status in ("refund", "chargeback"):
                    refund_match = self.storage.match_bepaid_transaction_to_intent(extracted)
                    if refund_match.get("matched") and refund_match.get("confidence") == "strong":
                        r_pid = refund_match["intent_public_id"]
                        r_iid = refund_match["intent_id"]
                        self.storage.payment_intent_mark_requires_check(
                            r_pid,
                            reason=f"refund_webhook:status={tx_status}:tx_uid={tx_uid}",
                        )
                        self.storage.log_payment_webhook_audit(
                            "refund_requires_check",
                            bepaid_tx_id=tx_id,
                            payment_intent_id=r_iid,
                            intent_public_id=r_pid,
                            transaction_uid=tx_uid or None,
                            shop_type=shop_type,
                            status=tx_status,
                            amount_minor=amount_minor,
                            currency=currency or None,
                            reason=f"refund_received:status={tx_status}",
                        )
                # v7.0.99.0: mark option expired when bePaid sends expired webhook
                if tx_status == "expired":
                    try:
                        _exp_match = self.storage.match_bepaid_transaction_to_payment_target(
                            extracted, shop_type
                        )
                        if _exp_match.get("matched"):
                            _exp_pid = _exp_match.get("intent_public_id") or ""
                            _exp_ch = "erip" if shop_type == "erip" else "acquiring"
                            _exp_opt = self.storage.get_option_by_channel(_exp_pid, _exp_ch) if _exp_pid else None
                            if _exp_opt:
                                self.storage.mark_option_expired(_exp_opt["id"], now_iso())
                                log.info(
                                    "payment_event=payment_checkout_expired intent=%s channel=%s via_webhook",
                                    _exp_pid, _exp_ch,
                                )
                    except Exception:
                        log.warning("webhook expired handler error", exc_info=True)
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "skip_reason": f"status={tx_status}",
                }, 200

            # Option-aware match: searches payment_intent_options first, then legacy intents
            match = self.storage.match_bepaid_transaction_to_payment_target(extracted, shop_type)
            target_type = match.get("target_type") or "none"
            match_method = match.get("method") or ""
            match_confidence = match.get("confidence") or "none"
            match_reason = match.get("reason") or ""

            if match_confidence == "conflict":
                log.warning(
                    "bePaid webhook conflict: tx_id=%s uid=%s conflicts=%s",
                    tx_id, tx_uid, match.get("conflicts"),
                )
                self.storage.log_payment_webhook_audit(
                    "webhook_match_conflict",
                    bepaid_tx_id=tx_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_confidence="conflict",
                    reason=match_reason,
                    details={"conflicts": match.get("conflicts", [])},
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "skip_reason": "match_conflict",
                }, 200

            if not match.get("matched") or match_confidence != "strong":
                log.info(
                    "bePaid webhook no_match: tx_id=%s uid=%s tracking_id=%s",
                    tx_id, tx_uid, extracted.get("tracking_id"),
                )
                self.storage.log_payment_webhook_audit(
                    "webhook_no_match",
                    bepaid_tx_id=tx_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_confidence="none",
                    reason=match_reason,
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "skip_reason": "no_match",
                }, 200

            # Resolve intent_id and intent_public_id for both target types
            if target_type == "payment_option":
                option_id = match["option_id"]
                intent_id = match["payment_intent_id"]
                intent_public_id = match["parent_public_id"]
            else:
                option_id = None
                intent_id = match["intent_id"]
                intent_public_id = match["intent_public_id"]

            # Link the transaction record to the intent
            from utils import now_iso as _now_iso
            _now = _now_iso()
            self.storage.bepaid_transaction_link_intent(
                tx_id,
                intent_id=intent_id,
                intent_public_id=intent_public_id,
                match_method=match_method,
                confidence=match_confidence,
                reason=match_reason,
                now=_now,
            )

            self.storage.log_payment_webhook_audit(
                "payment_option_webhook_matched" if target_type == "payment_option" else "webhook_matched",
                bepaid_tx_id=tx_id,
                payment_intent_id=intent_id,
                intent_public_id=intent_public_id,
                transaction_uid=tx_uid or None,
                shop_type=shop_type,
                amount_minor=amount_minor,
                currency=currency or None,
                match_method=match_method,
                match_confidence=match_confidence,
                reason=match_reason,
            )

            # Skip test transactions
            if is_test:
                log.warning("bePaid webhook test_ignored: tx_id=%s intent=%s", tx_id, intent_public_id)
                self.storage.log_payment_webhook_audit(
                    "webhook_test_ignored",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_method=match_method,
                    reason="test_transaction",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "matched_intent": intent_public_id,
                    "skip_reason": "test_transaction",
                }, 200

            # Require explicit BYN; non-empty wrong currency → requires_check
            if currency and currency != "BYN":
                log.warning("bePaid webhook currency_mismatch: tx_id=%s currency=%s", tx_id, currency)
                self.storage.log_payment_webhook_audit(
                    "webhook_currency_mismatch",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_method=match_method,
                    reason=f"currency={currency!r} != BYN",
                )
                self.storage.payment_intent_mark_requires_check(
                    intent_public_id,
                    reason=f"currency_mismatch:{currency}",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "matched_intent": intent_public_id,
                    "skip_reason": f"currency={currency}",
                }, 200

            # Missing currency → skip
            if not currency:
                log.warning("bePaid webhook missing_currency: tx_id=%s", tx_id)
                self.storage.log_payment_webhook_audit(
                    "webhook_mark_paid_skipped",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    match_method=match_method,
                    reason="missing_currency",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "matched_intent": intent_public_id,
                    "skip_reason": "missing_currency",
                }, 200

            # Missing amount → skip
            if amount_minor is None:
                log.warning("bePaid webhook missing_amount: tx_id=%s", tx_id)
                self.storage.log_payment_webhook_audit(
                    "webhook_mark_paid_skipped",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    currency=currency or None,
                    match_method=match_method,
                    reason="missing_amount",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "matched_intent": intent_public_id,
                    "skip_reason": "missing_amount",
                }, 200

            # Verify webhook amount matches intent exactly
            pi_obj = self.storage.get_payment_intent(intent_public_id)
            expected_minor = int(pi_obj.get("amount_minor") or -1) if pi_obj else -1
            actual_minor = int(amount_minor)
            if actual_minor != expected_minor:
                log.warning(
                    "bePaid webhook amount_mismatch: tx_id=%s intent=%s expected=%s got=%s",
                    tx_id, intent_public_id, expected_minor, actual_minor,
                )
                self.storage.log_payment_webhook_audit(
                    "webhook_amount_mismatch",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_method=match_method,
                    match_confidence=match_confidence,
                    reason=f"expected={expected_minor} got={actual_minor}",
                )
                self.storage.payment_intent_mark_requires_check(
                    intent_public_id,
                    reason=f"amount_mismatch:expected={expected_minor}_got={actual_minor}",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": False,
                    "matched_intent": intent_public_id,
                    "skip_reason": "amount_mismatch",
                }, 200

            # Mark paid — option path or legacy intent path
            if target_type == "payment_option" and option_id is not None:
                mark_result = self.storage.payment_intent_mark_paid_via_option(
                    intent_public_id,
                    option_id=option_id,
                    channel=shop_type,
                    tx_uid=tx_uid,
                    amount_minor=actual_minor,
                    currency=currency,
                    paid_at=paid_at or _now,
                    tracking_id=extracted.get("tracking_id"),
                    order_id=extracted.get("order_id"),
                    account_number=extracted.get("erip_account_number"),
                    verified=sig_verified,
                    match_method=match_method,
                )
            else:
                mark_result = self.storage.payment_intent_mark_paid(
                    intent_public_id,
                    tx_uid=tx_uid,
                    amount_minor=actual_minor,
                    currency=currency,
                    paid_at=paid_at or _now,
                    channel=shop_type,
                    tracking_id=extracted.get("tracking_id"),
                    order_id=extracted.get("order_id"),
                    account_number=extracted.get("erip_account_number"),
                    verified=sig_verified,
                    match_method=match_method,
                )

            if mark_result.get("idempotent"):
                log.info(
                    "payment_event=webhook_duplicate intent=%s transaction_uid=%s "
                    "result=blocked reason=duplicate_tx_uid tx_id=%s",
                    intent_public_id, tx_uid, tx_id,
                )
                self.storage.log_payment_webhook_audit(
                    "duplicate_webhook_ignored",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    amount_minor=amount_minor,
                    match_method=match_method,
                    reason="duplicate_tx_uid",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": True, "idempotent": True,
                    "matched_intent": intent_public_id,
                }, 200

            if mark_result.get("ok") and mark_result.get("marked_paid"):
                log.info(
                    "payment_event=payment_marked_paid intent=%s mk_invoice_id=%s "
                    "transaction_uid=%s channel=%s status=paid result=success tx_id=%s amount=%s",
                    intent_public_id,
                    str((self.storage.get_payment_intent(intent_public_id) or {}).get("mk_invoice_id") or ""),
                    tx_uid, shop_type or "", tx_id, amount_minor,
                )
                self.storage.log_payment_webhook_audit(
                    "payment_option_marked_paid" if target_type == "payment_option" else "intent_marked_paid",
                    bepaid_tx_id=tx_id,
                    payment_intent_id=intent_id,
                    intent_public_id=intent_public_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    status="paid",
                    amount_minor=amount_minor,
                    currency=currency or None,
                    match_method=match_method,
                    match_confidence=match_confidence,
                    reason="payment_confirmed",
                )
                return {
                    "ok": True, "saved_id": tx_id, "is_new": is_new,
                    "signature": sig_reason, "processed": True,
                    "matched_intent": intent_public_id, "marked_paid": True,
                }, 200

            # mark_paid failed for another reason (conflict, wrong_state)
            log.warning(
                "bePaid webhook mark_paid_failed: tx_id=%s intent=%s result=%s",
                tx_id, intent_public_id, mark_result,
            )
            self.storage.log_payment_webhook_audit(
                "webhook_mark_paid_failed",
                bepaid_tx_id=tx_id,
                payment_intent_id=intent_id,
                intent_public_id=intent_public_id,
                transaction_uid=tx_uid or None,
                amount_minor=amount_minor,
                match_method=match_method,
                reason=str(mark_result.get("reason") or mark_result.get("error") or "unknown"),
            )
            return {
                "ok": True, "saved_id": tx_id, "is_new": is_new,
                "signature": sig_reason, "processed": False,
                "matched_intent": intent_public_id,
                "skip_reason": str(mark_result.get("reason") or "mark_paid_failed"),
            }, 200

        except Exception as e:
            log.exception("bePaid webhook: save error")
            return {"ok": False, "error": str(e)}, 500

    def bepaid_status(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/integrations/bepaid/status — configuration status."""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in BEPAID_RECONCILE_ROLES:
            return {"ok": False, "error": "access_denied"}
        cfg = self.settings
        last_webhook = self.storage.get_bepaid_last_webhook_at()
        return {
            "ok": True,
            "enabled": getattr(cfg, "bepaid_enabled", False),
            "erip_configured": getattr(cfg, "bepaid_erip_enabled", False),
            "acquiring_configured": getattr(cfg, "bepaid_acq_enabled", False),
            "auto_post_to_moyklass": getattr(cfg, "bepaid_auto_post_to_moyklass", False),
            "erip_shop_id": getattr(cfg, "bepaid_erip_shop_id", "") or None,
            "acq_shop_id": getattr(cfg, "bepaid_acq_shop_id", "") or None,
            "erip_sig_verification": bool(getattr(cfg, "bepaid_erip_public_key", "")),
            "acq_sig_verification": bool(getattr(cfg, "bepaid_acq_public_key", "")),
            "last_webhook_received_at": last_webhook,
        }

    def bepaid_list_transactions(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/integrations/bepaid/transactions — list with filters."""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in BEPAID_RECONCILE_ROLES:
            return {"ok": False, "error": "access_denied"}
        month = params.get("month", "")
        shop_type = params.get("shop_type", "all")
        match_status = params.get("match_status", "all")
        try:
            rows = self.storage.list_bepaid_transactions(month=month, shop_type=shop_type, match_status=match_status)
        except Exception as e:
            return {"ok": False, "error": str(e)}
        # Strip raw_json for list view (keep it light)
        for r in rows:
            r.pop("raw_json", None)
        return {"ok": True, "transactions": rows, "count": len(rows)}

    def bepaid_list_unmatched_transactions(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/payments/bepaid/unmatched — successful, verified, non-test transactions with no intent match."""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in {"owner", "admin"}:
            return {"ok": False, "error": "access_denied"}
        rows = self.storage.list_unmatched_bepaid_transactions(limit=50)
        safe = []
        for r in rows:
            safe.append({
                "id": r.get("id"),
                "shop_type": r.get("shop_type"),
                "channel": r.get("shop_type"),
                "transaction_uid": r.get("transaction_uid"),
                "tracking_id": r.get("tracking_id"),
                "order_id": r.get("order_id"),
                "status": r.get("status"),
                "amount_minor": r.get("amount_minor"),
                "amount_byn": r.get("amount_byn"),
                "currency": r.get("currency"),
                "paid_at": r.get("paid_at"),
                "received_at": r.get("received_at"),
                "signature_verified": bool(r.get("webhook_verified")),
                "provider_verified": bool(r.get("provider_verified")),
                "test": bool(r.get("test")),
                "match_status": r.get("match_status") or "no_match",
            })
        log.info("bePaid unmatched list count=%d", len(safe))
        return {"ok": True, "items": safe, "count": len(safe)}

    def bepaid_list_recovery_queue(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/payments/bepaid/recovery-queue

        Successful, verified, non-test transactions already matched to an intent
        but whose intent is still not paid. Owner/admin only.
        Added in v7.0.93.2.9.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role not in {"owner", "admin"}:
            return {"ok": False, "error": "access_denied"}
        rows = self.storage.list_bepaid_recovery_queue(limit=50)
        safe = []
        for r in rows:
            safe.append({
                "id": r.get("id"),
                "shop_type": r.get("shop_type"),
                "channel": r.get("shop_type"),
                "transaction_uid": r.get("transaction_uid"),
                "tracking_id": r.get("tracking_id"),
                "status": r.get("status"),
                "amount_minor": r.get("amount_minor"),
                "amount_byn": r.get("amount_byn"),
                "currency": r.get("currency"),
                "paid_at": r.get("paid_at"),
                "received_at": r.get("received_at"),
                "signature_verified": bool(r.get("webhook_verified")),
                "provider_verified": bool(r.get("provider_verified")),
                "test": bool(r.get("test")),
                "intent_public_id": r.get("intent_public_id"),
                "intent_status": r.get("intent_status"),
                "reason": "previous_mark_paid_failed",
            })
        log.info("bePaid recovery queue count=%d", len(safe))
        return {"ok": True, "items": safe, "count": len(safe)}

    def bepaid_reconcile_stored_transaction(
        self, auth: dict[str, Any], tx_id_str: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        """POST /api/payments/bepaid/transactions/{id}/reconcile

        Re-processes a stored verified-signature successful transaction. Handles
        both previously unmatched (no_match) and already-matched transactions
        whose intent was not yet marked paid. No external API calls. Owner/admin only.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role not in {"owner", "admin"}:
            return {"ok": False, "error": "access_denied"}

        try:
            tx_id = int(tx_id_str)
        except (ValueError, TypeError):
            return {"ok": False, "error": "invalid_transaction_id"}

        tx = self.storage.get_bepaid_transaction_by_id(tx_id)
        if not tx:
            return {"ok": False, "error": "transaction_not_found"}

        if not tx.get("webhook_verified") and not tx.get("provider_verified"):
            self.storage.log_payment_webhook_audit(
                "stored_transaction_reconcile_blocked",
                bepaid_tx_id=tx_id,
                transaction_uid=str(tx.get("transaction_uid") or "") or None,
                shop_type=str(tx.get("shop_type") or "") or None,
                reason="webhook_not_verified",
            )
            return {
                "ok": False,
                "error": "reconcile_blocked",
                "reason": "webhook_not_verified",
            }
        if tx.get("status") != "successful":
            return {"ok": False, "error": "not_successful",
                    "reason": f"status={tx.get('status')}"}
        if tx.get("test"):
            return {"ok": False, "error": "test_transaction_ignored"}

        shop_type = str(tx.get("shop_type") or "")
        tx_uid = str(tx.get("transaction_uid") or "").strip()
        amount_minor = tx.get("amount_minor")
        currency = str(tx.get("currency") or "").strip()
        tracking_id = str(tx.get("tracking_id") or "").strip() or None
        order_id = str(tx.get("order_id") or "").strip() or None
        paid_at = str(tx.get("paid_at") or "").strip() or None
        erip_account = str(tx.get("erip_account_number") or "").strip() or None

        from utils import now_iso as _now_iso
        now_str = _now_iso()

        self.storage.log_payment_webhook_audit(
            "stored_transaction_reconcile_started",
            bepaid_tx_id=tx_id,
            transaction_uid=tx_uid or None,
            shop_type=shop_type,
            amount_minor=amount_minor,
            currency=currency or None,
        )

        # Idempotency: already reconciled?
        existing_pub_id = str(tx.get("intent_public_id") or "").strip()
        if existing_pub_id:
            existing_pi = self.storage.get_payment_intent(existing_pub_id)
            if existing_pi and existing_pi.get("status") == "paid":
                existing_uid = str(existing_pi.get("paid_transaction_uid") or "").strip()
                if existing_uid == tx_uid:
                    self.storage.log_payment_webhook_audit(
                        "stored_transaction_reconciled",
                        bepaid_tx_id=tx_id,
                        intent_public_id=existing_pub_id,
                        transaction_uid=tx_uid or None,
                        reason="already_reconciled_idempotent",
                    )
                    return {
                        "ok": True, "idempotent": True,
                        "intent_public_id": existing_pub_id,
                        "intent": self._normalize_payment_intent(existing_pi),
                    }

        extracted = {
            "tracking_id": tracking_id,
            "order_id": order_id,
            "transaction_uid": tx_uid,
            "erip_account_number": erip_account,
        }
        match = self.storage.match_bepaid_transaction_to_payment_target(extracted, shop_type)

        if not match.get("matched") or match.get("confidence") != "strong":
            # Fallback for already-matched transactions: if the transaction already has
            # intent_public_id stored (e.g. tx_id=163 after webhook ran but mark_paid failed),
            # use that stored match directly rather than requiring the matcher to re-find it.
            if existing_pub_id:
                fallback_pi = self.storage.get_payment_intent(existing_pub_id)
                if fallback_pi and fallback_pi.get("status") not in ("paid", "posted_to_moyklass", "cancelled"):
                    match = {
                        "matched": True, "target_type": "legacy_intent",
                        "intent_public_id": existing_pub_id,
                        "intent_id": fallback_pi.get("id"),
                        "option_id": None, "payment_intent_id": fallback_pi.get("id"),
                        "confidence": "strong",
                        "method": "stored_intent_match",
                        "reason": "fallback_to_stored_intent_public_id",
                        "conflicts": [],
                    }
            if not match.get("matched") or match.get("confidence") != "strong":
                self.storage.log_payment_webhook_audit(
                    "stored_transaction_reconcile_blocked",
                    bepaid_tx_id=tx_id,
                    transaction_uid=tx_uid or None,
                    shop_type=shop_type,
                    amount_minor=amount_minor,
                    reason=f"no_match:{match.get('reason')}",
                )
                return {
                    "ok": False, "error": "no_match_found",
                    "reason": match.get("reason"),
                }

        target_type = match.get("target_type") or "none"
        if target_type == "payment_option":
            option_id = match["option_id"]
            intent_public_id = match["parent_public_id"]
            intent_id = match["payment_intent_id"]
        else:
            option_id = None
            intent_public_id = match.get("intent_public_id")
            intent_id = match.get("intent_id")

        if not currency or currency != "BYN":
            self.storage.log_payment_webhook_audit(
                "stored_transaction_reconcile_blocked",
                bepaid_tx_id=tx_id,
                intent_public_id=intent_public_id,
                transaction_uid=tx_uid or None,
                reason=f"currency_mismatch:{currency}",
            )
            return {"ok": False, "error": "currency_mismatch", "reason": f"currency={currency}"}
        if amount_minor is None:
            return {"ok": False, "error": "missing_amount"}

        pi_obj = self.storage.get_payment_intent(intent_public_id)
        if not pi_obj:
            return {"ok": False, "error": "parent_intent_not_found"}
        expected_minor = int(pi_obj.get("amount_minor") or -1)
        actual_minor = int(amount_minor)
        if actual_minor != expected_minor:
            self.storage.log_payment_webhook_audit(
                "stored_transaction_reconcile_blocked",
                bepaid_tx_id=tx_id,
                payment_intent_id=intent_id,
                intent_public_id=intent_public_id,
                transaction_uid=tx_uid or None,
                reason=f"amount_mismatch:expected={expected_minor}_got={actual_minor}",
            )
            return {"ok": False, "error": "amount_mismatch",
                    "expected": expected_minor, "actual": actual_minor}

        match_method = match.get("method") or "reconcile"

        if target_type == "payment_option" and option_id is not None:
            mark_result = self.storage.payment_intent_mark_paid_via_option(
                intent_public_id,
                option_id=option_id,
                channel=shop_type,
                tx_uid=tx_uid,
                amount_minor=actual_minor,
                currency=currency,
                paid_at=paid_at or now_str,
                tracking_id=tracking_id,
                order_id=order_id,
                account_number=erip_account,
                verified=True,
                match_method=match_method,
            )
        else:
            mark_result = self.storage.payment_intent_mark_paid(
                intent_public_id,
                tx_uid=tx_uid,
                amount_minor=actual_minor,
                currency=currency,
                paid_at=paid_at or now_str,
                channel=shop_type,
                tracking_id=tracking_id,
                order_id=order_id,
                account_number=erip_account,
                verified=True,
                match_method=match_method,
            )

        if mark_result.get("ok") and (mark_result.get("marked_paid") or mark_result.get("idempotent")):
            self.storage.bepaid_transaction_link_intent(
                tx_id,
                intent_id=intent_id,
                intent_public_id=intent_public_id,
                match_method=match_method,
                confidence="strong",
                reason=f"reconciled:{match.get('reason')}",
                now=now_str,
            )
            self.storage.log_payment_webhook_audit(
                "stored_transaction_reconciled",
                bepaid_tx_id=tx_id,
                payment_intent_id=intent_id,
                intent_public_id=intent_public_id,
                transaction_uid=tx_uid or None,
                shop_type=shop_type,
                amount_minor=actual_minor,
                currency=currency,
                match_method=match_method,
                reason="reconcile_successful",
            )
            updated_pi = self.storage.get_payment_intent(intent_public_id)
            return {
                "ok": True,
                "reconciled": True,
                "idempotent": bool(mark_result.get("idempotent")),
                "intent_public_id": intent_public_id,
                "intent": self._normalize_payment_intent(updated_pi) if updated_pi else {},
                "channel": shop_type,
                "match_method": match_method,
            }

        self.storage.log_payment_webhook_audit(
            "stored_transaction_reconcile_blocked",
            bepaid_tx_id=tx_id,
            payment_intent_id=intent_id,
            intent_public_id=intent_public_id,
            transaction_uid=tx_uid or None,
            reason=str(mark_result.get("reason") or mark_result.get("error") or "mark_paid_failed"),
        )
        return {
            "ok": False, "error": "mark_paid_failed",
            "reason": str(mark_result.get("reason") or mark_result.get("error") or "unknown"),
        }

    def bepaid_verify_acquiring_payment(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/verify-acquiring

        Verifies a stored acquiring transaction via the bePaid checkout status API and
        atomically reconciles it with the intent. Owner/admin only.

        Security properties:
        - checkout_token is always read from DB; never accepted from the frontend
        - Only ACQ credentials are used (never ERIP)
        - All checkout response fields are validated before any state change
        - Sets provider_verified=1 on the transaction (NOT webhook_verified)
        - MoyKlass posting is NOT triggered (BEPAID_AUTO_POST_TO_MOYKLASS=false)
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role not in {"owner", "admin"}:
            return {"ok": False, "error": "access_denied"}

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "intent_not_found"}

        # Token comes from DB only — never from frontend
        option = self.storage.get_option_by_channel(public_id, "acquiring")
        if not option:
            return {"ok": False, "error": "no_acquiring_option"}

        checkout_token = str(option.get("checkout_token") or "").strip()
        if not checkout_token:
            return {"ok": False, "error": "no_checkout_token_in_db"}

        tracking_id_expected = str(option.get("bepaid_tracking_id") or "").strip()
        amount_expected = int(pi.get("amount_minor") or -1)

        cfg = self.settings
        if not getattr(cfg, "bepaid_acq_shop_id", "") or not getattr(cfg, "bepaid_acq_secret_key", ""):
            return {"ok": False, "error": "acq_credentials_not_configured"}

        acq_shop_id = cfg.bepaid_acq_shop_id

        # Status query uses ACQ credentials only — never ERIP credentials
        client = BePaidClient(
            shop_id=acq_shop_id,
            secret_key=cfg.bepaid_acq_secret_key,
            timeout=getattr(cfg, "bepaid_request_timeout", 30),
        )
        result = client.get_checkout_status(checkout_token)

        if result.requires_check:
            return {"ok": False, "error": "provider_unavailable", "retry": True}
        if not result.ok or result.http_status != 200:
            return {"ok": False, "error": "provider_error", "detail": result.error}

        checkout = result.data.get("checkout") or {}
        shop = checkout.get("shop") or {}
        order = checkout.get("order") or {}
        gw = checkout.get("gateway_response") or {}
        payment = gw.get("payment") or {}

        if str(shop.get("id") or "") != str(acq_shop_id):
            return {"ok": False, "error": "shop_mismatch"}

        if not checkout.get("finished"):
            return {"ok": False, "error": "checkout_not_finished"}

        if checkout.get("test"):
            return {"ok": False, "error": "test_checkout_rejected"}

        if checkout.get("status") != "successful":
            return {"ok": False, "error": "checkout_not_successful",
                    "checkout_status": str(checkout.get("status") or "")}

        if int(order.get("amount") or -1) != amount_expected:
            return {"ok": False, "error": "order_amount_mismatch",
                    "expected": amount_expected, "got": order.get("amount")}

        if str(order.get("currency") or "") != "BYN":
            return {"ok": False, "error": "order_currency_mismatch",
                    "got": str(order.get("currency") or "")}

        if str(order.get("tracking_id") or "") != tracking_id_expected:
            return {"ok": False, "error": "tracking_id_mismatch",
                    "expected": tracking_id_expected,
                    "got": str(order.get("tracking_id") or "")}

        if not payment:
            return {"ok": False, "error": "missing_gateway_payment"}

        if str(payment.get("status") or "") != "successful":
            return {"ok": False, "error": "payment_not_successful",
                    "payment_status": str(payment.get("status") or "")}

        if int(payment.get("amount") or -1) != amount_expected:
            return {"ok": False, "error": "payment_amount_mismatch",
                    "expected": amount_expected, "got": payment.get("amount")}

        if str(payment.get("currency") or "") != "BYN":
            return {"ok": False, "error": "payment_currency_mismatch",
                    "got": str(payment.get("currency") or "")}

        tx_uid = str(payment.get("uid") or "").strip()
        if not tx_uid:
            return {"ok": False, "error": "missing_payment_uid"}

        # Find the stored transaction by UID returned from the provider
        stored_tx = self.storage.find_bepaid_transaction("bepaid", "acquiring", tx_uid, None, None, None)
        if not stored_tx:
            return {"ok": False, "error": "transaction_not_found_in_db",
                    "transaction_uid": tx_uid}

        tx_id = int(stored_tx["id"])

        from utils import now_iso as _now_iso_pv
        now_str = _now_iso_pv()

        # Mark provider_verified=1 — separate from webhook_verified (RSA), never conflated
        self.storage.mark_bepaid_transaction_provider_verified(
            tx_id,
            verified_at=now_str,
            verification_method="checkout_status_query",
        )
        self.storage.log_payment_webhook_audit(
            "acquiring_payment_provider_verified",
            bepaid_tx_id=tx_id,
            transaction_uid=tx_uid,
            shop_type="acquiring",
            amount_minor=amount_expected,
            currency="BYN",
            reason="checkout_status_query_success",
        )

        # Idempotency: already reconciled?
        existing_pub_id = str(stored_tx.get("intent_public_id") or "").strip()
        if existing_pub_id:
            existing_pi = self.storage.get_payment_intent(existing_pub_id)
            if existing_pi and existing_pi.get("status") == "paid":
                if str(existing_pi.get("paid_transaction_uid") or "").strip() == tx_uid:
                    return {
                        "ok": True, "idempotent": True,
                        "intent_public_id": existing_pub_id,
                        "intent": self._normalize_payment_intent(existing_pi),
                        "provider_verified": True,
                    }

        option_id = int(option["id"])
        intent_id = int(pi["id"])
        order_id_stored = str(stored_tx.get("order_id") or "").strip() or None
        erip_account = str(stored_tx.get("erip_account_number") or "").strip() or None
        paid_at = str(stored_tx.get("paid_at") or "").strip() or None

        mark_result = self.storage.payment_intent_mark_paid_via_option(
            public_id,
            option_id=option_id,
            channel="acquiring",
            tx_uid=tx_uid,
            amount_minor=amount_expected,
            currency="BYN",
            paid_at=paid_at or now_str,
            tracking_id=tracking_id_expected or None,
            order_id=order_id_stored,
            account_number=erip_account,
            verified=True,
            match_method="provider_verify_checkout_status",
        )

        if mark_result.get("ok") and (mark_result.get("marked_paid") or mark_result.get("idempotent")):
            self.storage.bepaid_transaction_link_intent(
                tx_id,
                intent_id=intent_id,
                intent_public_id=public_id,
                match_method="provider_verify_checkout_status",
                confidence="strong",
                reason="provider_verified_checkout_status_query",
                now=now_str,
            )
            self.storage.log_payment_webhook_audit(
                "acquiring_payment_provider_reconciled",
                bepaid_tx_id=tx_id,
                payment_intent_id=intent_id,
                intent_public_id=public_id,
                transaction_uid=tx_uid,
                shop_type="acquiring",
                amount_minor=amount_expected,
                currency="BYN",
                match_method="provider_verify_checkout_status",
                reason="provider_verify_success",
            )
            updated_pi = self.storage.get_payment_intent(public_id)
            return {
                "ok": True,
                "reconciled": True,
                "idempotent": bool(mark_result.get("idempotent")),
                "intent_public_id": public_id,
                "intent": self._normalize_payment_intent(updated_pi) if updated_pi else {},
                "channel": "acquiring",
                "provider_verified": True,
                "match_method": "provider_verify_checkout_status",
            }

        self.storage.log_payment_webhook_audit(
            "acquiring_payment_provider_verify_blocked",
            bepaid_tx_id=tx_id,
            intent_public_id=public_id,
            transaction_uid=tx_uid,
            reason=str(mark_result.get("reason") or mark_result.get("error") or "mark_paid_failed"),
        )
        return {
            "ok": False, "error": "mark_paid_failed",
            "reason": str(mark_result.get("reason") or mark_result.get("error") or "unknown"),
        }

    def bepaid_reconcile(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/integrations/bepaid/reconcile — match bePaid txns against MoyKlass payments."""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in BEPAID_RECONCILE_ROLES:
            return {"ok": False, "error": "access_denied"}

        month = params.get("month", "")
        shop_type = params.get("shop_type", "all")

        if not month:
            from datetime import date as _date
            month = _date.today().strftime("%Y-%m")

        # Load bePaid transactions for month
        try:
            bp_txns = self.storage.list_bepaid_transactions(month=month, shop_type=shop_type)
        except Exception as e:
            return {"ok": False, "error": f"storage error: {e}"}

        # Load MoyKlass payments for month
        mk_payments: list[dict[str, Any]] = []
        mk_error = ""
        mk_loaded = False
        if self.settings.moyklass_enabled:
            try:
                from datetime import date as _date2
                year, mnum = int(month[:4]), int(month[5:7])
                start_date = _date2(year, mnum, 1)
                if mnum == 12:
                    end_date = _date2(year + 1, 1, 1)
                else:
                    end_date = _date2(year, mnum + 1, 1)
                result = self.moyklass._scan_payments_for_month(start_date, end_date, limit=3000)
                if result.ok:
                    raw_items = extract_items(result.data)
                    mk_payments = [x for x in raw_items if isinstance(x, dict)]
                    mk_loaded = True
                else:
                    mk_error = str(result.error or "failed")
            except Exception as e:
                mk_error = str(e)

        # Build MK payment indexes
        _mk_pay_by_uid_amount: dict[str, list[dict[str, Any]]] = {}
        _mk_pay_by_uid: dict[str, list[dict[str, Any]]] = {}
        _mk_pay_by_amount: dict[int, list[dict[str, Any]]] = {}
        _mk_user_names: dict[str, str] = {}
        _mk_known_uids: set[str] = set()

        for _mp in mk_payments:
            _uid = str(_mp.get("userId") or _mp.get("user_id") or "")
            if not _uid:
                continue
            _mk_known_uids.add(_uid)
            _uname = str(_mp.get("userName") or _mp.get("user_name") or "")
            if _uname:
                _mk_user_names[_uid] = _uname
            _amt_raw = _mp.get("sum") or _mp.get("amount") or 0
            try:
                _amt_minor = int(round(float(_amt_raw) * 100))
            except Exception:
                _amt_minor = 0
            _mk_pay_by_uid_amount.setdefault(f"{_uid}:{_amt_minor}", []).append(_mp)
            _mk_pay_by_uid.setdefault(_uid, []).append(_mp)
            _mk_pay_by_amount.setdefault(_amt_minor, []).append(_mp)

        # Subscription lookup helpers (lazy, per-user, cached)
        _sub_cache: dict[str, list[dict[str, Any]]] = {}
        _sub_api_calls = 0
        _sub_api_calls_limit = 50
        _sub_high_conf = 0
        _sub_medium_conf = 0
        _sub_low_conf = 0
        _sub_example_matches: list[dict[str, Any]] = []
        _sub_example_misses: list[dict[str, Any]] = []
        _sub_example_hist: list[dict[str, Any]] = []

        def _get_user_subs(uid: str) -> list[dict[str, Any]]:
            nonlocal _sub_api_calls
            if uid in _sub_cache:
                return _sub_cache[uid]
            if not self.settings.moyklass_enabled or _sub_api_calls >= _sub_api_calls_limit:
                _sub_cache[uid] = []
                return []
            _sub_api_calls += 1
            try:
                _sr = self.moyklass.get_user_subscriptions(uid)
                items = [x for x in extract_items(_sr.data) if isinstance(x, dict)] if _sr.ok else []
            except Exception:
                items = []
            _sub_cache[uid] = items
            return items

        def _sub_amount_minor(sub: dict[str, Any]) -> int | None:
            raw = (sub.get("payed") or sub.get("paid") or sub.get("paidSum")
                   or sub.get("price") or sub.get("originalPrice"))
            if raw is None:
                return None
            try:
                return int(round(float(raw) * 100))
            except Exception:
                return None

        def _sub_info(sub: dict[str, Any]) -> dict[str, Any]:
            return {
                "subscription_id": str(sub.get("id") or sub.get("userSubscriptionId") or ""),
                "subscription_type_id": str(sub.get("subscriptionId") or ""),
                "subscription_name": str(sub.get("_ycSubscriptionName") or "").strip(),
                "subscription_amount_byn": round(float(
                    sub.get("payed") or sub.get("paid") or sub.get("paidSum")
                    or sub.get("price") or sub.get("originalPrice") or 0), 2),
                "subscription_sell_date": str(sub.get("sellDate") or "").strip()[:10],
                "subscription_begin_date": str(
                    sub.get("beginDate") or sub.get("startDate") or "").strip()[:10],
                "subscription_end_date": str(
                    sub.get("endDate") or sub.get("finishDate") or sub.get("overDate") or "").strip()[:10],
            }

        # Date parsing and confidence scoring for subscription matching
        from datetime import date as _ddate

        def _parse_ds(s: str | None) -> "_ddate | None":
            if not s:
                return None
            try:
                return _ddate.fromisoformat(str(s).strip()[:10])
            except Exception:
                return None

        # Parse month bounds for date relevance checks
        try:
            _my, _mm = int(month[:4]), int(month[5:7])
            _month_start = _ddate(_my, _mm, 1)
            _month_end = _ddate(_my + 1, 1, 1) if _mm == 12 else _ddate(_my, _mm + 1, 1)
        except Exception:
            _month_start = _month_end = None

        def _sub_confidence(
            sub: dict[str, Any],
            paid_at_str: str,
            is_exact: bool,
        ) -> tuple[str, str, int | None, bool]:
            """Return (confidence, date_relevance, delta_days, is_historical).

            confidence: "high" | "medium" | "low"
            date_relevance: human-readable label
            delta_days: days between paid_at and newest sub date (positive = sub is older)
            is_historical: sub is >180 days older than paid_at with no high-relevance
            """
            paid_dt = _parse_ds(paid_at_str[:10] if paid_at_str else None)
            sell_dt = _parse_ds(sub.get("sellDate"))
            begin_dt = _parse_ds(sub.get("beginDate") or sub.get("startDate"))
            end_dt = _parse_ds(sub.get("endDate") or sub.get("finishDate") or sub.get("overDate"))

            all_sub_dts = [d for d in [sell_dt, begin_dt, end_dt] if d is not None]
            delta_days: int | None = None
            if paid_dt and all_sub_dts:
                delta_days = (paid_dt - max(all_sub_dts)).days  # positive = sub older than paid

            is_historical = bool(delta_days is not None and delta_days > 180)

            # Collect high-relevance signals
            relevances: list[str] = []
            if sell_dt and _month_start and _month_start <= sell_dt < _month_end:
                relevances.append("sell_date_in_selected_month")
            if sell_dt and paid_dt and abs((paid_dt - sell_dt).days) <= 45:
                relevances.append("sell_date_near_paid_at")
            if begin_dt and end_dt and _month_start and _month_end:
                if begin_dt < _month_end and end_dt >= _month_start:
                    relevances.append("period_overlaps_selected_month")
            if paid_dt:
                for _d in [begin_dt, end_dt]:
                    if _d and abs((paid_dt - _d).days) <= 45:
                        if "period_near_paid_at" not in relevances:
                            relevances.append("period_near_paid_at")

            if not all_sub_dts:
                date_relevance = "unknown"
            elif relevances:
                date_relevance = relevances[0]
            elif is_historical:
                date_relevance = "historical"
            else:
                date_relevance = "not_recent"

            # Confidence rules
            # high: exact amount AND at least one high-relevance date condition
            if is_exact and relevances:
                confidence = "high"
            # low: exact amount AND clearly historical (>180 days) AND no high relevance
            elif is_exact and is_historical:
                confidence = "low"
            # medium: everything else (exact+no date info, close amount regardless of date)
            else:
                confidence = "medium"

            return confidence, date_relevance, delta_days, is_historical

        _CONF_ORDER = {"high": 0, "medium": 1, "low": 2}

        stats = {
            "total": len(bp_txns),
            "already_in_moyklass": 0,
            "found_in_subscription": 0,
            "possible_subscription_match": 0,
            "historical_subscription_match": 0,
            "user_found_no_payment_or_subscription": 0,
            "possible_payment_match": 0,
            "needs_review": 0,
            "ignored_not_successful": 0,
            "ignored_test": 0,
            "ignored_currency": 0,
        }

        results: list[dict[str, Any]] = []

        for _tx in bp_txns:
            _txid = int(_tx.get("id") or 0)
            _status = str(_tx.get("status") or "").lower()
            _test = bool(_tx.get("test"))
            _currency = str(_tx.get("currency") or "BYN").upper()
            _amount_minor = _tx.get("amount_minor")
            _mk_uid = str(_tx.get("mk_user_id") or "").strip()
            _mk_uid_source = str(_tx.get("mk_user_id_source") or "").strip()
            _paid_at_str = str(_tx.get("paid_at") or "").strip()

            new_match: dict[str, Any] = {}

            if _test:
                new_match = {"match_status": "ignored_test", "match_score": 0.0,
                             "match_reason": "тестовая транзакция"}
                stats["ignored_test"] += 1
            elif _status != "successful":
                new_match = {"match_status": "ignored_not_successful", "match_score": 0.0,
                             "match_reason": f"статус: {_status}"}
                stats["ignored_not_successful"] += 1
            elif _currency != "BYN":
                new_match = {"match_status": "ignored_currency", "match_score": 0.0,
                             "match_reason": f"валюта: {_currency}"}
                stats["ignored_currency"] += 1
            else:
                # Priority 1: exact uid + amount match in MK payments
                _exact_key = f"{_mk_uid}:{_amount_minor}" if (_mk_uid and _amount_minor is not None) else None
                _exact_candidates = _mk_pay_by_uid_amount.get(_exact_key, []) if _exact_key else []

                if _exact_candidates:
                    _found = _exact_candidates[0]
                    _uname = _mk_user_names.get(_mk_uid, "")
                    new_match = {
                        "match_status": "already_in_moyklass",
                        "match_score": 1.0,
                        "match_confidence": "high",
                        "match_reason": f"userId={_mk_uid} и сумма совпадают в платежах МК",
                        "mk_payment_id": str(_found.get("id") or ""),
                        "mk_user_id": _mk_uid,
                        "mk_user_name": _uname,
                        "mk_user_id_source": _mk_uid_source,
                    }
                    stats["already_in_moyklass"] += 1

                elif _mk_uid:
                    # Priority 2: uid known, no payment match → check subscriptions
                    _uname = _mk_user_names.get(_mk_uid, "")
                    _user_subs = _get_user_subs(_mk_uid)

                    # Build candidate list with confidence scores
                    # Each entry: (conf_order, kind_order, delta_days, conf, dr, delta_byn, hist, sub)
                    _cands: list[tuple[int, int, int, str, str, float, bool, dict[str, Any]]] = []
                    if _amount_minor is not None:
                        for _sub in _user_subs:
                            _sm = _sub_amount_minor(_sub)
                            if _sm is None:
                                continue
                            _diff = abs(_sm - _amount_minor)
                            _is_exact = (_diff == 0)
                            _is_close = (0 < _diff <= 100)
                            if not (_is_exact or _is_close):
                                continue
                            _conf, _dr, _dd, _hist = _sub_confidence(
                                _sub, _paid_at_str, _is_exact)
                            _delta_byn = round(_diff / 100, 2)
                            _cands.append((
                                _CONF_ORDER.get(_conf, 3),
                                0 if _is_exact else 1,
                                _dd if _dd is not None else 9999,
                                _conf, _dr, _delta_byn, _hist, _sub,
                            ))

                    # Best: highest confidence, then exact, then closest date
                    _cands.sort(key=lambda c: (c[0], c[1], c[2]))

                    if _cands:
                        _, _, _, _conf, _dr, _delta_byn, _hist, _best_sub = _cands[0]
                        _si = _sub_info(_best_sub)
                        if _delta_byn:
                            _si["subscription_amount_delta_byn"] = _delta_byn
                        _is_exact_best = (not _delta_byn)

                        # Status by confidence
                        _DR_TEXT = {
                            "sell_date_in_selected_month": "продажа абонемента в выбранном месяце",
                            "sell_date_near_paid_at": "дата продажи близко к платежу bePaid",
                            "period_overlaps_selected_month": "период абонемента перекрывается с месяцем",
                            "period_near_paid_at": "период абонемента близко к платежу bePaid",
                            "unknown": "дата абонемента неизвестна",
                            "not_recent": "дата абонемента не близко к платежу",
                            "historical": f"абонемент старше 6 месяцев ({_si.get('subscription_sell_date') or '?'})",
                        }
                        _dr_text = _DR_TEXT.get(_dr, _dr)

                        if _conf == "high":
                            _match_status = "found_in_subscription"
                            _match_score = 0.95
                            _reason = (f"Ученик userId={_mk_uid}, сумма совпала, "
                                       f"{_dr_text} (абонемент #{_si['subscription_id']})")
                            _sub_high_conf += 1
                            stats["found_in_subscription"] += 1
                            if len(_sub_example_matches) < 3:
                                _sub_example_matches.append({
                                    "bp_amount_byn": round((_amount_minor or 0) / 100, 2),
                                    "mk_user_id": _mk_uid,
                                    "subscription_id": _si["subscription_id"],
                                    "date_relevance": _dr,
                                })
                        elif _conf == "low":
                            _match_status = "historical_subscription_match"
                            _match_score = 0.40
                            _reason = (f"Ученик userId={_mk_uid}, сумма совпала, "
                                       f"но {_dr_text} (абонемент #{_si['subscription_id']})")
                            _sub_low_conf += 1
                            stats["historical_subscription_match"] += 1
                            if len(_sub_example_hist) < 5:
                                _sub_example_hist.append({
                                    "bp_amount_byn": round((_amount_minor or 0) / 100, 2),
                                    "mk_user_id": _mk_uid,
                                    "subscription_id": _si["subscription_id"],
                                    "subscription_sell_date": _si.get("subscription_sell_date", ""),
                                    "bp_paid_at": _paid_at_str[:10] if _paid_at_str else "",
                                })
                        else:
                            _match_status = "possible_subscription_match"
                            _match_score = 0.75
                            if _delta_byn:
                                _reason = (f"Ученик userId={_mk_uid}, похожая сумма"
                                           f" (Δ {_delta_byn} BYN), {_dr_text}"
                                           f" (абонемент #{_si['subscription_id']})")
                            else:
                                _reason = (f"Ученик userId={_mk_uid}, сумма совпала, "
                                           f"но {_dr_text} (абонемент #{_si['subscription_id']})")
                            _sub_medium_conf += 1
                            stats["possible_subscription_match"] += 1

                        # Retrieve delta_days from the best candidate for output
                        _dd_out: int | None = _cands[0][2] if _cands[0][2] != 9999 else None
                        new_match = {
                            "match_status": _match_status,
                            "match_score": _match_score,
                            "match_confidence": _conf,
                            "match_reason": _reason,
                            "mk_user_id": _mk_uid,
                            "mk_user_name": _uname,
                            "mk_user_id_source": _mk_uid_source,
                            "subscription_date_relevance": _dr,
                            "subscription_date_delta_days": _dd_out,
                            "subscription_is_historical": _hist,
                            **_si,
                        }

                    else:
                        # User uid known, but no payment or subscription match
                        _uid_payments = _mk_pay_by_uid.get(_mk_uid, [])
                        _possible_pay = [
                            {"mk_payment_id": str(p.get("id") or ""),
                             "amount_byn": round(float(p.get("sum") or p.get("amount") or 0), 2),
                             "date": str(p.get("date") or p.get("createdAt") or "")}
                            for p in _uid_payments[:3]
                        ]
                        _possible_subs = [_sub_info(s) for s in _user_subs[:3]]
                        new_match = {
                            "match_status": "user_found_no_payment_or_subscription",
                            "match_score": 0.2,
                            "match_confidence": "none",
                            "match_reason": (
                                f"userId={_mk_uid} найден, но ни оплата, ни абонемент"
                                f" на эту сумму не найдены"
                            ),
                            "mk_user_id": _mk_uid,
                            "mk_user_name": _uname,
                            "mk_user_id_source": _mk_uid_source,
                            "possible_matches": _possible_pay,
                            "possible_subscriptions": _possible_subs,
                        }
                        stats["user_found_no_payment_or_subscription"] += 1
                        if len(_sub_example_misses) < 3:
                            _sub_example_misses.append({
                                "bp_amount_byn": round((_amount_minor or 0) / 100, 2),
                                "mk_user_id": _mk_uid,
                                "subscriptions_count": len(_user_subs),
                            })

                else:
                    # No mk_user_id — try amount-only match in payments
                    _amt_candidates = (_mk_pay_by_amount.get(_amount_minor, [])
                                       if _amount_minor is not None else [])
                    if _amt_candidates:
                        _possible_by_amt = [
                            {"mk_payment_id": str(p.get("id") or ""),
                             "amount_byn": round(float(p.get("sum") or p.get("amount") or 0), 2),
                             "date": str(p.get("date") or p.get("createdAt") or ""),
                             "mk_user_id": str(p.get("userId") or ""),
                             "mk_user_name": _mk_user_names.get(str(p.get("userId") or ""), "")}
                            for p in _amt_candidates[:5]
                        ]
                        new_match = {
                            "match_status": "possible_payment_match",
                            "match_score": 0.5,
                            "match_confidence": "medium",
                            "match_reason": "userId не извлечён; найдены МК-платежи с той же суммой",
                            "possible_matches": _possible_by_amt,
                        }
                        stats["possible_payment_match"] += 1
                    else:
                        new_match = {
                            "match_status": "needs_review",
                            "match_score": 0.0,
                            "match_confidence": "none",
                            "match_reason": "userId не извлечён, совпадений по сумме нет",
                        }
                        stats["needs_review"] += 1

            # Persist match result
            if new_match and _txid:
                try:
                    self.storage.update_bepaid_match(_txid, {
                        "match_status": new_match.get("match_status"),
                        "match_score": new_match.get("match_score"),
                        "match_reason": new_match.get("match_reason"),
                        "mk_payment_id": new_match.get("mk_payment_id"),
                        "mk_user_id": new_match.get("mk_user_id") or _mk_uid or None,
                        "mk_user_name": new_match.get("mk_user_name"),
                    })
                except Exception:
                    pass

            row_out = dict(_tx)
            row_out.pop("raw_json", None)
            row_out.update(new_match)
            results.append(row_out)

        # Totals: historical matches are NOT counted as "found in MK"
        _ignored_statuses = {"ignored_test", "ignored_not_successful", "ignored_currency"}
        successful_byn = [r for r in results if r.get("match_status") not in _ignored_statuses]
        total_amount_byn = sum(float(r.get("amount_byn") or 0) for r in successful_byn)

        return {
            "ok": True,
            "month": month,
            "shop_type": shop_type,
            "mk_payments_loaded": mk_loaded,
            "mk_payments_count": len(mk_payments),
            "mk_error": mk_error,
            "stats": stats,
            "successful_byn_count": len(successful_byn),
            "successful_amount_byn": round(total_amount_byn, 2),
            "transactions": results,
            "diagnostics": {
                "bepaid_configured_erip": getattr(self.settings, "bepaid_erip_enabled", False),
                "bepaid_configured_acquiring": getattr(self.settings, "bepaid_acq_enabled", False),
                "signature_verification_enabled_erip": bool(getattr(self.settings, "bepaid_erip_public_key", "")),
                "signature_verification_enabled_acq": bool(getattr(self.settings, "bepaid_acq_public_key", "")),
                "transactions_loaded": len(bp_txns),
                "moyklass_payments_loaded": mk_loaded,
                "moyklass_payments_load_error": mk_error,
                "moyklass_payments_count": len(mk_payments),
                "mk_known_uids_count": len(_mk_known_uids),
                "subscriptions_checked_count": len(_sub_cache),
                "subscriptions_loaded_count": sum(len(v) for v in _sub_cache.values()),
                "subscriptions_api_calls": _sub_api_calls,
                "subscription_high_confidence_matches": _sub_high_conf,
                "subscription_medium_confidence_matches": _sub_medium_conf,
                "subscription_low_confidence_matches": _sub_low_conf,
                "historical_subscription_matches": stats["historical_subscription_match"],
                "successful_count": len(successful_byn),
                "successful_amount": round(total_amount_byn, 2),
                "matched_count": stats["already_in_moyklass"],
                "found_in_subscription_count": stats["found_in_subscription"],
                "possible_subscription_match_count": stats["possible_subscription_match"],
                "historical_subscription_match_count": stats["historical_subscription_match"],
                "user_found_no_payment_or_subscription_count": stats["user_found_no_payment_or_subscription"],
                "possible_payment_match_count": stats["possible_payment_match"],
                "needs_review_count": stats["needs_review"],
                "ignored_count": (stats["ignored_not_successful"]
                                  + stats["ignored_test"]
                                  + stats["ignored_currency"]),
                "examples_subscription_matches": _sub_example_matches,
                "examples_historical_subscription_matches": _sub_example_hist,
                "examples_subscription_misses": _sub_example_misses,
                "last_webhook_received_at": self.storage.get_bepaid_last_webhook_at(),
            },
        }


    # ── payment_intents ───────────────────────────────────────────────────────

    _PI_VALID_PURPOSES = {"current_month", "previous_month_debt", "old_debt", "advance", "city_program", "other"}
    _PI_VALID_METHODS = {"erip", "acquiring", "manual"}
    _PI_VALID_STATUSES_CANCEL = {"draft", "ready"}

    def _require_payment_intent_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        # Internal automation bypass — only used by process_new_moyklass_invoices pipeline
        if auth.get("_internal") is True and auth.get("role") in PAYMENT_INTENT_ROLES:
            return None
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_INTENT_ROLES:
            return {"ok": False, "error": "Доступ к платёжным черновикам ограничен: owner, admin, director, operations, client_manager."}
        return None

    # Valid technical status values — reject Russian labels or unknown strings
    _PI_VALID_STATUS_VALUES = {
        "all", "draft", "ready", "bepaid_created", "paid",
        "posted_to_moyklass", "cancelled", "error",
    }

    def payment_intents_list(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        raw_month = params.get("month") or ""
        raw_status = params.get("status") or "all"

        # Normalise month to YYYY-MM; reject anything else
        import re as _re
        month = raw_month.strip()
        if month and not _re.match(r"^\d{4}-\d{2}$", month):
            month = ""  # invalid format — ignore, return all months

        # Normalise status; ignore Russian labels or unknown values
        status = raw_status.strip()
        if status not in self._PI_VALID_STATUS_VALUES:
            status = "all"

        intents = self.storage.list_payment_intents(
            month=month or None,
            status=status if status != "all" else None,
            exclude_cancelled=(status == "all"),
        )
        intents = [self._normalize_payment_intent(pi) for pi in intents]
        # Attach payment options for dual-channel cards (payment_url safe to expose; token not exposed)
        for pi in intents:
            opts = self.storage.get_options_for_intent(pi["public_id"])
            pi["payment_options"] = [
                {
                    "channel": o.get("channel"),
                    "status": o.get("status"),
                    "account_number": o.get("bepaid_account_number"),
                    "uid": o.get("bepaid_uid"),
                    "payment_url": o.get("payment_url"),
                    "has_checkout": bool(o.get("checkout_token")),
                }
                for o in opts
            ]
        # Attach withdrawal details for withdrawn intents — one batch query, no N+1
        withdrawn_ids = [
            pi["public_id"] for pi in intents
            if pi.get("client_visibility") == "withdrawn"
        ]
        if withdrawn_ids:
            withdrawals = self.storage.get_withdrawals_for_intents(withdrawn_ids)
            for pi in intents:
                if pi.get("client_visibility") == "withdrawn":
                    wr = withdrawals.get(pi["public_id"])
                    if wr:
                        pi["withdrawal"] = {
                            "status": wr.get("status"),
                            "reason": wr.get("reason"),
                            "requested_by_telegram_id": wr.get("requested_by_telegram_id"),
                            "requested_by_name": wr.get("requested_by_name"),
                            "requested_at": wr.get("requested_at"),
                            "completed_at": wr.get("completed_at"),
                            "erip_cancel_status": wr.get("erip_cancel_status"),
                            "erip_cancel_error": wr.get("erip_cancel_error"),
                            "remote_cancel_status": wr.get("remote_cancel_status"),
                            "remote_cancel_method": wr.get("remote_cancel_method"),
                            "remote_cancel_error": wr.get("remote_cancel_error"),
                            "card_checkout_blocked_at": wr.get("card_checkout_blocked_at"),
                            "card_blocked": bool(wr.get("card_checkout_blocked_at")),
                            "telegram_update_status": wr.get("telegram_update_status"),
                            "telegram_updated_at": wr.get("telegram_updated_at"),
                            "requires_check_reason": wr.get("requires_check_reason"),
                        }
        pi_stats = self.storage.payment_intents_stats(month=month or None)
        return {
            "ok": True,
            "intents": intents,
            "items": intents,           # alias for forward-compat
            "total": len(intents),
            "stats": pi_stats,
            "month": month,
            "status_filter": status,
            "debug": {
                "raw_month": raw_month,
                "raw_status": raw_status,
                "applied_month": month or "(all)",
                "applied_status": status,
                "items_count": len(intents),
            },
        }

    def payment_intent_get(self, auth: dict[str, Any], public_id: str) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        intent = self.storage.get_payment_intent(public_id)
        if not intent:
            return {"ok": False, "error": "Черновик платежа не найден", "public_id": public_id}
        intent = self._normalize_payment_intent(intent)
        return {"ok": True, "intent": intent}

    # ── v7.1.0 — Payment terms and discounts endpoints ───────────────────────

    def _require_payment_terms_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_TERMS_ROLES:
            return {"ok": False, "error": "Доступ к условиям оплаты ограничен: owner, admin, operations."}
        return None

    def _pricing_actor_name(self, auth: dict[str, Any]) -> str:
        uid = auth.get("user_id")
        staff = {}
        try:
            staff = self.storage.get_staff_user(int(uid)) or {}
        except (TypeError, ValueError):
            staff = {}
        return (
            str(staff.get("full_name") or "").strip()
            or str(auth.get("full_name") or "").strip()
            or str((auth.get("user") or {}).get("first_name") or "").strip()
            or str(staff.get("username") or auth.get("username") or "").strip()
            or (f"Сотрудник #{uid}" if uid else "Сотрудник")
        )

    @staticmethod
    def _byn(minor: Any) -> str:
        try:
            return f"{int(minor) / 100:.2f} BYN"
        except (TypeError, ValueError):
            return "0.00 BYN"

    def _decorate_terms(self, terms_row: dict | None) -> dict[str, Any]:
        resolved = resolve_client_payment_terms(terms_row)
        resolved["base_price_byn"] = self._byn(resolved["base_price_minor"])
        if terms_row:
            for _src_field in (
                "terms_source", "source_subscription_id", "source_sync_status",
                "source_ambiguity_reason", "source_synced_at",
            ):
                resolved[_src_field] = terms_row.get(_src_field)
        return resolved

    def _decorate_discount(self, d: dict) -> dict[str, Any]:
        out = dict(d)
        out["fixed_price_byn"] = self._byn(d.get("fixed_price_minor"))
        return out

    def payment_client_terms_get(self, auth: dict[str, Any], mk_user_id: str) -> dict[str, Any]:
        denied = self._require_payment_terms_access(auth)
        if denied:
            return denied
        mk_user_id = str(mk_user_id or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        row = self.storage.get_payment_client_terms(mk_user_id)
        return {
            "ok": True,
            "mk_user_id": mk_user_id,
            "terms": self._decorate_terms(row),
            "raw": row,
            "auto_sync": self._payment_terms_auto_sync_status(mk_user_id, auth),
        }

    def _payment_terms_auto_sync_status(self, mk_user_id: str, auth: dict[str, Any]) -> dict[str, Any]:
        """v7.1.3: return pilot auto-sync status for owner/admin only."""
        if auth.get("role", "") not in {"owner", "admin"}:
            return {}
        sync_enabled = getattr(self.settings, "payment_mk_subscription_terms_sync_enabled", False)
        if not sync_enabled:
            return {"status": "disabled"}
        allowlist = getattr(self.settings, "payment_mk_subscription_terms_sync_user_ids", ())
        if not allowlist:
            return {"status": "disabled"}
        if mk_user_id in allowlist:
            return {"status": "pilot_match"}
        return {"status": "pilot_no_match"}

    def payment_client_terms_update(
        self, auth: dict[str, Any], mk_user_id: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        denied = self._require_payment_terms_access(auth)
        if denied:
            return denied
        mk_user_id = str(mk_user_id or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        try:
            row = self.storage.upsert_payment_client_terms(
                mk_user_id=mk_user_id,
                base_lessons_count=int(body.get("base_lessons_count") or DEFAULT_LESSONS_COUNT),
                base_price_minor=int(body.get("base_price_minor") or DEFAULT_BASE_PRICE_MINOR),
                currency=str(body.get("currency") or "BYN"),
                default_due_days=int(body.get("default_due_days") or DEFAULT_DUE_DAYS),
                automation_enabled=bool(body.get("automation_enabled")),
                automation_paused_reason=(body.get("automation_paused_reason") or None),
                base_subscription_type_id=(body.get("base_subscription_type_id") or None),
                actor_tg_id=int(auth["user_id"]),
                actor_name=self._pricing_actor_name(auth),
                now_str=now_iso(),
            )
        except (ValueError, TypeError) as exc:
            return {"ok": False, "error": str(exc)}
        return {"ok": True, "mk_user_id": mk_user_id, "terms": self._decorate_terms(row), "raw": row}

    def payment_client_terms_sync(
        self, auth: dict[str, Any], mk_user_id: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        denied = self._require_payment_terms_access(auth)
        if denied:
            return denied
        mk_user_id = str(mk_user_id or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        return self._sync_payment_terms_from_moyklass(mk_user_id, auth)

    def _sync_payment_terms_from_moyklass(
        self, mk_user_id: str, actor_auth: dict[str, Any],
        audit_reason: str = "newer_moyklass_subscription",
    ) -> dict[str, Any]:
        import json as _json
        now = now_iso()
        subs_result = self.moyklass.get_user_subscriptions(mk_user_id)
        if not subs_result.ok:
            return {
                "ok": False,
                "state": "api_error",
                "error": "Не удалось получить данные из МойКласс",
            }
        subscriptions = extract_items(subs_result.data) if subs_result.ok else []
        current_row = self.storage.get_payment_client_terms(mk_user_id)
        current_price_minor = int(current_row["base_price_minor"]) if current_row else None
        current_lessons_count = int(current_row["base_lessons_count"]) if current_row else None
        current_source_sub_id = str(current_row.get("source_subscription_id") or "") if current_row else None
        selection = select_moyklass_subscription_for_terms(
            subscriptions,
            current_price_minor=current_price_minor,
            current_lessons_count=current_lessons_count,
            current_source_sub_id=current_source_sub_id or None,
        )
        state = selection["state"]
        sub = selection.get("subscription")
        new_price_minor = selection.get("price_minor")
        new_lessons_count = selection.get("lessons_count")
        candidates_count = selection.get("candidates_count", 0)
        selection_field = selection.get("selection_field")

        sub_id = str(sub.get("id") or sub.get("userSubscriptionId") or "") if sub else ""
        sub_type_id = str(sub.get("subscriptionId") or "") if sub else ""
        is_internal = actor_auth.get("_internal") is True

        # Build safe snapshot for storage (no secrets)
        snapshot_data: dict[str, Any] = {}
        if sub:
            snapshot_data = {
                "id": sub.get("id"),
                "subscriptionId": sub.get("subscriptionId"),
                "statusId": sub.get("statusId"),
                "price": sub.get("price"),
                "visitCount": sub.get("visitCount"),
                "sellDate": sub.get("sellDate"),
                "beginDate": sub.get("beginDate"),
                "endDate": sub.get("endDate"),
                "_selection_field": selection_field,
                "_candidates_count": candidates_count,
            }
        snapshot_json = _json.dumps(snapshot_data, ensure_ascii=False)[:2000] if snapshot_data else None

        if state == "new_source":
            new_lessons = new_lessons_count if new_lessons_count is not None else (
                int(current_row["base_lessons_count"]) if current_row else DEFAULT_LESSONS_COUNT
            )
            try:
                self.storage.upsert_payment_client_terms_moyklass(
                    mk_user_id=mk_user_id,
                    base_lessons_count=new_lessons,
                    base_price_minor=new_price_minor,
                    currency="BYN",
                    default_due_days=int(current_row["default_due_days"]) if current_row else DEFAULT_DUE_DAYS,
                    automation_enabled=bool(current_row.get("automation_enabled")) if current_row else False,
                    automation_paused_reason=current_row.get("automation_paused_reason") if current_row else None,
                    base_subscription_type_id=sub_type_id or None,
                    terms_source="moyklass_subscription",
                    source_subscription_id=sub_id or None,
                    source_subscription_type_id=sub_type_id or None,
                    source_synced_at=now,
                    source_snapshot_json=snapshot_json,
                    source_sync_status=state,
                    source_ambiguity_reason=None,
                    actor_tg_id=None if is_internal else int(actor_auth.get("user_id", 0)),
                    actor_name="moyklass_sync" if is_internal else self._pricing_actor_name(actor_auth),
                    now_str=now,
                    audit_reason=audit_reason,
                )
            except Exception as exc:
                return {"ok": False, "state": state, "error": str(exc)}
            return {
                "ok": True,
                "state": state,
                "old_price_minor": current_price_minor,
                "new_price_minor": new_price_minor,
                "old_lessons_count": current_lessons_count,
                "new_lessons_count": new_lessons,
                "source_subscription_id": sub_id or None,
                "candidates_count": candidates_count,
                "selection_field": selection_field,
                "mk_user_id": mk_user_id,
            }

        # For non-updating states: update diagnostic source fields only (no price/lessons change)
        if current_row:
            src = current_row.get("terms_source") or "manual"
            if state == "unchanged":
                src = "moyklass_subscription"
            self.storage.update_payment_client_terms_source(
                mk_user_id=mk_user_id,
                terms_source=src,
                source_subscription_id=sub_id or None,
                source_subscription_type_id=sub_type_id or None,
                source_synced_at=now,
                source_snapshot_json=snapshot_json,
                source_sync_status=state,
                source_ambiguity_reason=selection.get("reason"),
                now_str=now,
            )

        return {
            "ok": True,
            "state": state,
            "old_price_minor": current_price_minor,
            "new_price_minor": new_price_minor,
            "candidates_count": candidates_count,
            "selection_field": selection_field,
            "reason": selection.get("reason"),
            "mk_user_id": mk_user_id,
        }

    def payment_client_pricing_preview(
        self, auth: dict[str, Any], mk_user_id: str, params: dict[str, str]
    ) -> dict[str, Any]:
        denied = self._require_payment_terms_access(auth)
        if denied:
            return denied
        mk_user_id = str(mk_user_id or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        pricing_date = str(params.get("pricing_date") or "").strip()
        if not pricing_date:
            pricing_date = datetime.now(timezone.utc).astimezone(
                timezone(timedelta(hours=3))
            ).strftime("%Y-%m-%d")
        terms_row = self.storage.get_payment_client_terms(mk_user_id)
        active = self.storage.get_active_payment_client_discounts(mk_user_id, pricing_date)
        preview = resolve_next_subscription_price(terms_row, active, pricing_date)
        preview["pricing_date"] = pricing_date
        if preview.get("ok"):
            preview["resolved_price_byn"] = self._byn(preview.get("resolved_price_minor"))
            preview["base_price_byn"] = self._byn(preview.get("base_price_minor"))
        return {"ok": True, "mk_user_id": mk_user_id, "preview": preview}

