    # ── v7.0.93 — parent client visibility ───────────────────────────────────

    def get_intent_publish_preview(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """GET …/{id}/publish-preview — 12-point pre-publication check (read-only)."""
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        import re as _re

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Черновик платежа не найден", "public_id": public_id}

        checks: list[dict] = []

        def _check(name: str, ok: bool, detail: str = "", blocker: bool = True) -> None:
            checks.append({"name": name, "ok": ok, "detail": detail, "blocker": blocker})

        _check("intent_exists", True, f"public_id={public_id}")
        _check("not_cancelled", pi.get("status") != "cancelled", f"status={pi.get('status')}")
        amount_minor = pi.get("amount_minor") or 0
        _check("has_amount", int(amount_minor) > 0, f"amount_minor={amount_minor}")
        _check("has_student_name", bool(pi.get("student_name")), f"student_name={'set' if pi.get('student_name') else 'missing'}")
        _check("has_mk_user_id", bool(pi.get("mk_user_id")), f"mk_user_id={pi.get('mk_user_id')}")
        _check("has_purpose", bool(pi.get("purpose")), f"purpose={pi.get('purpose')!r}")
        period = str(pi.get("period_month") or "")
        _check("has_period_month", bool(period and _re.match(r"^\d{4}-\d{2}$", period)), f"period_month={period!r}")
        pmethod = pi.get("payment_method") or ""
        _check("payment_method_valid", pmethod in ("erip", "acquiring"), f"payment_method={pmethod!r}")

        opts = self.storage.get_options_for_intent(public_id)
        # Only consider active options — ignore cancelled / superseded / expired rows.
        _inactive_opt_statuses = {"cancelled", "superseded", "expired"}
        erip_opt = next(
            (o for o in opts if o.get("channel") == "erip"
             and o.get("status") not in _inactive_opt_statuses),
            None,
        )
        acq_opt = next(
            (o for o in opts if o.get("channel") == "acquiring"
             and o.get("status") not in _inactive_opt_statuses),
            None,
        )
        if pmethod == "erip":
            # Check options table first.  For intents created via the legacy single-channel
            # path (before v7.0.92.2 dual-channel options), ERIP data is stored only on the
            # payment_intents row (bepaid_account_number + bepaid_uid) with no option row.
            # The admin card reads pi.bepaid_account_number — we use the same canonical source.
            erip_acct = str(erip_opt.get("bepaid_account_number") or "").strip() if erip_opt else ""
            if not erip_acct and pi.get("bepaid_uid"):
                erip_acct = str(pi.get("bepaid_account_number") or "").strip()
            _check("erip_option_ready", bool(erip_acct),
                   f"erip_account={'set' if erip_acct else 'missing'}")
        elif pmethod == "acquiring":
            acq_url = str(acq_opt.get("payment_url") or "").strip() if acq_opt else ""
            _check("acquiring_option_ready", bool(acq_url),
                   f"payment_url={'set' if acq_url else 'missing'}")

        mk_user_id = str(pi.get("mk_user_id") or "")
        parents = self.storage.get_parents_for_child(mk_user_id) if mk_user_id else []
        _check("has_parent_link", bool(parents), f"confirmed_parent_links={len(parents)}")

        _check("not_already_posted", pi.get("status") != "posted_to_moyklass",
               f"status={pi.get('status')}", blocker=False)
        _check("not_already_published", pi.get("client_visibility") != "published",
               f"client_visibility={pi.get('client_visibility')}", blocker=False)

        blockers = [c for c in checks if not c["ok"] and c["blocker"]]
        return {
            "ok": True,
            "public_id": public_id,
            "ready": len(blockers) == 0,
            "checks": checks,
            "blockers": len(blockers),
            "intent_status": pi.get("status"),
            "client_visibility": pi.get("client_visibility") or "hidden",
            "parents": [{"parent_telegram_user_id": p.get("parent_telegram_user_id")} for p in parents],
        }

    def publish_intent_to_parent(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST …/{id}/publish-to-parent — mark intent visible to parent."""
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        published_by = str(auth.get("user_id") or "")
        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
        result = self.storage.publish_payment_intent_to_client(public_id, published_by, now)
        if not result.get("ok"):
            return result
        # Notify parent if eligible (manual publish path)
        if not result.get("idempotent"):
            pi = result.get("intent") or {}
            mk_invoice_id = str(pi.get("mk_invoice_id") or "")
            mk_user_id = str(pi.get("mk_user_id") or "")
            if mk_invoice_id:
                automation_item = self.storage.get_automation_item_by_invoice(mk_invoice_id)
                if automation_item and automation_item.get("parent_notify_eligible", 0):
                    self._enqueue_and_send_parent_notification(
                        automation_item, public_id, mk_invoice_id, mk_user_id, now,
                        intent=pi,
                    )
        return {"ok": True, "idempotent": result.get("idempotent", False), "intent": self._normalize_payment_intent(result["intent"])}

    def withdraw_intent_from_parent(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST …/{id}/withdraw-from-parent — hide intent from parent."""
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        withdrawn_by = str(auth.get("user_id") or "")
        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
        result = self.storage.withdraw_payment_intent_from_client(public_id, withdrawn_by, now)
        if not result.get("ok"):
            return result
        return {"ok": True, "idempotent": result.get("idempotent", False), "intent": self._normalize_payment_intent(result["intent"])}

    # ── v7.0.98.0 — Safe Invoice Withdrawal ──────────────────────────────────

    @staticmethod
    def _format_withdrawal_notification_text(
        student_name: str,
        amount_byn: float,
        currency: str,
    ) -> str:
        """Format the 'invoice withdrawn' edit text for parent notification."""
        import html as _html
        name_esc = _html.escape(str(student_name or "").strip() or "Ученик")
        curr = str(currency or "BYN").strip().upper()
        amount_str = f"{amount_byn:.2f}".replace(".", ",")
        lines = [
            "⚠️ <b>Yellow Club — счёт отозван</b>",
            "",
            f"Ученик: {name_esc}",
            f"Сумма: {amount_str}\xa0{curr}",
            "",
            "Этот счёт больше не актуален.",
            "Оплачивать его не нужно.",
        ]
        return "\n".join(lines)

    def _try_edit_parent_notification_for_withdrawal(
        self,
        withdrawal_id: int,
        public_id: str,
        student_name: str,
        amount_byn: float,
        currency: str,
        now: str,
    ) -> None:
        """Try to edit the parent Telegram notification to 'invoice withdrawn' text."""
        notif = self.storage.get_parent_notification(public_id, "new_invoice")
        if not notif:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "skipped_no_notification", None, None, now,
            )
            return

        status = str(notif.get("status") or "")
        if status not in ("sent",):
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "skipped_not_sent", None, None, now,
            )
            return

        already_updated = str(notif.get("notification_type") or "") == "invoice_withdrawn"
        if already_updated:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "skipped_already_updated", now, None, now,
            )
            return

        telegram_user_id = str(notif.get("telegram_user_id") or "").strip()
        message_id = notif.get("telegram_message_id")
        if not telegram_user_id or not message_id:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "skipped_missing_ids", None, None, now,
            )
            return

        bot_token = getattr(self.settings, "telegram_bot_token", "") or ""
        if not bot_token:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "skipped_no_token", None, None, now,
            )
            return

        text = self._format_withdrawal_notification_text(student_name, amount_byn, currency)
        ok, err = _telegram_edit_parent_notification_msg(
            bot_token, int(telegram_user_id), int(message_id), text,
        )
        if ok:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "edited", now, None, now,
            )
            log.info(
                "payment_event=withdrawal_telegram_edited intent=%s tg_user=%s msg_id=%s",
                public_id, telegram_user_id, message_id,
            )
        elif err.startswith("AMBIGUOUS:"):
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "requires_check", None, err[:500], now,
            )
            log.warning(
                "payment_event=withdrawal_telegram_ambiguous intent=%s err=%s",
                public_id, err,
            )
        else:
            self.storage.update_withdrawal_telegram(
                withdrawal_id, "failed", None, err[:500], now,
            )
            log.warning(
                "payment_event=withdrawal_telegram_failed intent=%s err=%s",
                public_id, err,
            )

    def _bepaid_erip_client(self) -> "BePaidClient | None":
        """Return a configured BePaidClient for ERIP operations, or None if credentials are missing."""
        shop_id = str(getattr(self.settings, "bepaid_erip_shop_id", "") or "").strip()
        secret = str(getattr(self.settings, "bepaid_erip_secret_key", "") or "").strip()
        if not shop_id or not secret:
            return None
        timeout = int(getattr(self.settings, "bepaid_request_timeout", 30) or 30)
        return BePaidClient(shop_id=shop_id, secret_key=secret, timeout=timeout)

    def _attempt_remote_cancel_for_withdrawal(
        self, withdrawal_id: int, erip_uid: str, now: str, public_id: str = ""
    ) -> None:
        """Call BePaid DELETE API and update withdrawal record with the result.

        Shared by withdraw_payment_intent (first withdrawal) and retry_remote_cancel.
        """
        if not erip_uid:
            self.storage.update_withdrawal_erip(
                withdrawal_id, "unsupported", None, "no_erip_uid", now,
            )
            self.storage.update_withdrawal_remote_cancel(
                withdrawal_id,
                remote_cancel_status="no_erip_uid",
                remote_cancel_method=None,
                remote_cancel_requested_at=None,
                remote_cancel_confirmed_at=None,
                remote_cancel_error="no_erip_uid",
                remote_status_before=None,
                remote_status_after=None,
                remote_response_reference=None,
                now=now,
            )
            return

        erip_client = self._bepaid_erip_client()
        if erip_client is None:
            log.warning(
                "payment_event=payment_remote_cancel_client_unavailable intent=%s uid_present=1",
                public_id,
            )
            self.storage.update_withdrawal_erip(
                withdrawal_id, "unsupported", None, "client_unavailable", now,
            )
            self.storage.update_withdrawal_remote_cancel(
                withdrawal_id,
                remote_cancel_status="client_unavailable",
                remote_cancel_method=None,
                remote_cancel_requested_at=None,
                remote_cancel_confirmed_at=None,
                remote_cancel_error="client_unavailable",
                remote_status_before=None,
                remote_status_after=None,
                remote_response_reference=None,
                now=now,
            )
            return

        log.info(
            "payment_event=payment_remote_cancel_client_resolved intent=%s client_available=1 uid_present=1",
            public_id,
        )
        remote_requested_at = now
        try:
            void_result = erip_client.void_erip_payment(erip_uid)
            err_txt = str(void_result.error or "")
            resp_data = void_result.data or {}
            if void_result.ok:
                remote_status_after = str(resp_data.get("status") or "deleted")
                remote_ref = str(resp_data.get("uid") or erip_uid)
                self.storage.update_withdrawal_erip(
                    withdrawal_id, "cancelled", now, None, now,
                )
                self.storage.update_withdrawal_remote_cancel(
                    withdrawal_id,
                    remote_cancel_status="cancelled",
                    remote_cancel_method="api_delete",
                    remote_cancel_requested_at=remote_requested_at,
                    remote_cancel_confirmed_at=now,
                    remote_cancel_error=None,
                    remote_status_before="pending",
                    remote_status_after=remote_status_after,
                    remote_response_reference=remote_ref,
                    now=now,
                )
            else:
                r_cancel_status = "requires_check" if void_result.requires_check else "failed"
                self.storage.update_withdrawal_erip(
                    withdrawal_id, "failed", None, err_txt[:300], now,
                )
                self.storage.update_withdrawal_remote_cancel(
                    withdrawal_id,
                    remote_cancel_status=r_cancel_status,
                    remote_cancel_method="api_delete",
                    remote_cancel_requested_at=remote_requested_at,
                    remote_cancel_confirmed_at=None,
                    remote_cancel_error=err_txt[:300],
                    remote_status_before="pending",
                    remote_status_after=None,
                    remote_response_reference=None,
                    now=now,
                )
        except Exception as exc:
            exc_txt = str(exc)[:300]
            self.storage.update_withdrawal_erip(
                withdrawal_id, "failed", None, exc_txt, now,
            )
            self.storage.update_withdrawal_remote_cancel(
                withdrawal_id,
                remote_cancel_status="failed",
                remote_cancel_method="api_delete",
                remote_cancel_requested_at=remote_requested_at,
                remote_cancel_confirmed_at=None,
                remote_cancel_error=exc_txt,
                remote_status_before=None,
                remote_status_after=None,
                remote_response_reference=None,
                now=now,
            )

    def withdraw_payment_intent(
        self,
        auth: dict[str, Any],
        public_id: str,
        body: dict[str, Any],
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/withdraw — safe withdrawal of an unpaid invoice.

        Blocks payment, hides from parent, saves audit trail.
        Does NOT delete payment_intent, automation item, or webhook history.
        """
        # ── Auth ──────────────────────────────────────────────────────────────
        if auth.get("_internal") is True and auth.get("role") in WITHDRAW_INVOICE_ROLES:
            role = auth["role"]
        else:
            role = self._role_for_user(int(auth.get("user_id") or 0))
        if role not in WITHDRAW_INVOICE_ROLES:
            return {"ok": False, "error": "Доступ запрещён. Требуется роль: owner, admin или operations."}

        reason = str(body.get("reason") or "").strip()
        if len(reason) < 5:
            return {"ok": False, "error": "Укажите причину отзыва (минимум 5 символов)."}

        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")

        # ── Load fresh intent ─────────────────────────────────────────────────
        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Счёт не найден.", "public_id": public_id}

        # ── Idempotency: already withdrawn ────────────────────────────────────
        if pi.get("client_visibility") == "withdrawn":
            existing = self.storage.get_withdrawal_by_intent(public_id)
            return {
                "ok": True,
                "idempotent": True,
                "status": (existing or {}).get("status", "withdrawn"),
                "withdrawal": existing,
            }

        # ── Pre-checks: block if payment already received or ambiguous ────────
        payment_status = str(pi.get("status") or "")
        mk_payment_id = pi.get("mk_payment_id")
        mk_posting_status = str(pi.get("mk_posting_status") or "")

        confirmed_txs = self.storage.get_confirmed_bepaid_transactions_for_intent(public_id)

        paid_or_ambiguous = (
            payment_status in ("paid", "posted_to_moyklass")
            or bool(mk_payment_id)
            or mk_posting_status in ("posted", "claiming", "ambiguous")
            or bool(confirmed_txs)
        )

        if paid_or_ambiguous:
            wr = self.storage.create_withdrawal_record(
                public_id=public_id,
                mk_invoice_id=str(pi.get("mk_invoice_id") or ""),
                reason=reason,
                requested_by_telegram_id=str(auth.get("user_id") or ""),
                requested_by_name=(
                    str(auth.get("full_name") or "").strip()
                    or str((auth.get("user") or {}).get("first_name") or "").strip()
                    or str(auth.get("username") or (auth.get("user") or {}).get("username") or "").strip()
                    or (f"Сотрудник #{str(auth.get('user_id') or '')}" if auth.get("user_id") else "Сотрудник")
                ),
                payment_status_at_request=payment_status,
                now=now,
            )
            if wr and wr.get("id"):
                self.storage.set_withdrawal_requires_check(
                    wr["id"], "payment_already_received_or_ambiguous", now,
                )
            log.warning(
                "payment_event=payment_withdrawal_requires_check intent=%s status=%s "
                "mk_payment_id=%s mk_posting_status=%s confirmed_txs=%d",
                public_id, payment_status, mk_payment_id, mk_posting_status, len(confirmed_txs),
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "По счёту уже получена оплата или её результат требует проверки. "
                    "Нужен ручной разбор: возврат или зачёт."
                ),
            }

        if payment_status in ("cancelled", "error"):
            return {"ok": False, "error": f"Счёт в статусе '{payment_status}' — отзыв невозможен."}

        # ── Create withdrawal audit record (INSERT OR IGNORE) ─────────────────
        wr = self.storage.create_withdrawal_record(
            public_id=public_id,
            mk_invoice_id=str(pi.get("mk_invoice_id") or ""),
            reason=reason,
            requested_by_telegram_id=str(auth.get("user_id") or ""),
            requested_by_name=(
                str(auth.get("full_name") or "").strip()
                or str((auth.get("user") or {}).get("first_name") or "").strip()
                or str(auth.get("username") or (auth.get("user") or {}).get("username") or "").strip()
                or (f"Сотрудник #{str(auth.get('user_id') or '')}" if auth.get("user_id") else "Сотрудник")
            ),
            payment_status_at_request=payment_status,
            now=now,
        )
        if not wr or not wr.get("id"):
            return {"ok": False, "error": "Не удалось создать запись отзыва."}
        withdrawal_id = wr["id"]

        log.info(
            "payment_event=payment_withdrawal_started intent=%s reason=%s by=%s",
            public_id, reason[:80], auth.get("user_id"),
        )

        # ── Atomic claim: set client_visibility='withdrawn' ───────────────────
        withdrawn_by = str(auth.get("user_id") or "")
        claim_result = self.storage.withdraw_payment_intent_from_client(
            public_id, withdrawn_by, now,
        )
        if not claim_result.get("ok"):
            self.storage.set_withdrawal_failed(withdrawal_id, "claim_failed", now)
            return {"ok": False, "error": "Не удалось атомарно отозвать счёт (конкурентное изменение)."}

        # ── Re-check after claim (race: payment arrived during withdrawal) ─────
        pi_after = self.storage.get_payment_intent(public_id)
        if pi_after and pi_after.get("status") in ("paid", "posted_to_moyklass"):
            self.storage.set_withdrawal_requires_check(
                withdrawal_id, "payment_arrived_during_withdrawal", now,
            )
            log.warning(
                "payment_event=payment_arrived_during_withdrawal intent=%s",
                public_id,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "Оплата поступила в процессе отзыва. "
                    "Требуется ручная проверка. Счёт уже скрыт у родителя."
                ),
            }

        mk_invoice_id = str(pi.get("mk_invoice_id") or "")

        # ── Reset automation item flags ────────────────────────────────────────
        if mk_invoice_id:
            self.storage.reset_automation_item_for_withdrawal(mk_invoice_id, now)

        # ── ERIP: remote cancel via DELETE API (v7.1.4 / v7.1.4.1) ─────────────
        erip_uid = str(pi.get("bepaid_uid") or "").strip()
        erip_option = self.storage.get_option_by_channel(public_id, "erip") if hasattr(self.storage, "get_option_by_channel") else None
        if not erip_uid and erip_option:
            erip_uid = str(erip_option.get("bepaid_uid") or "").strip()
        self._attempt_remote_cancel_for_withdrawal(withdrawal_id, erip_uid, now, public_id)

        # ── Card: block checkout (record blocked timestamp) ────────────────────
        self.storage.update_withdrawal_card(withdrawal_id, now, now)

        # ── Telegram: edit parent notification ────────────────────────────────
        amount_minor = pi.get("amount_minor") or 0
        amount_byn = round(int(amount_minor) / 100.0, 2) if amount_minor else 0.0
        currency = str(pi.get("currency") or "BYN")
        student_name = str(pi.get("student_name") or "")
        self._try_edit_parent_notification_for_withdrawal(
            withdrawal_id, public_id, student_name, amount_byn, currency, now,
        )

        # ── Complete withdrawal ────────────────────────────────────────────────
        self.storage.complete_withdrawal(withdrawal_id, now, now)

        final_wr = self.storage.get_withdrawal_by_intent(public_id) or {}
        log.info(
            "payment_event=payment_withdrawal_succeeded intent=%s erip=%s telegram=%s",
            public_id,
            final_wr.get("erip_cancel_status"),
            final_wr.get("telegram_update_status"),
        )
        return {
            "ok": True,
            "status": "withdrawn",
            "local_withdrawal_status": "withdrawn",
            "remote_cancel_status": (
                final_wr.get("remote_cancel_status") or final_wr.get("erip_cancel_status")
            ),
            "telegram_status": final_wr.get("telegram_update_status"),
            "erip_cancel_status": final_wr.get("erip_cancel_status"),
            "card_blocked": bool(final_wr.get("card_checkout_blocked_at")),
            "telegram_update_status": final_wr.get("telegram_update_status"),
            "requires_check_reason": final_wr.get("requires_check_reason"),
            "intent": self._normalize_payment_intent(
                self.storage.get_payment_intent(public_id) or {}
            ),
        }

    def get_intent_withdrawal_info(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """GET /api/payments/intents/{id}/withdrawal-status — admin read-only."""
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "not_found"}
        wr = self.storage.get_withdrawal_by_intent(public_id)
        can_withdraw = (
            pi.get("client_visibility") not in ("withdrawn",)
            and str(pi.get("status") or "") not in ("paid", "posted_to_moyklass", "cancelled", "error")
            and not pi.get("mk_payment_id")
            and str(pi.get("mk_posting_status") or "") not in ("posted", "claiming", "ambiguous")
        )
        result: dict[str, Any] = {
            "ok": True,
            "public_id": public_id,
            "client_visibility": pi.get("client_visibility"),
            "can_withdraw": can_withdraw,
        }
        if wr:
            result["withdrawal"] = {
                "status": wr.get("status"),
                "reason": wr.get("reason"),
                "requested_at": wr.get("requested_at"),
                "requested_by_telegram_id": wr.get("requested_by_telegram_id"),
                "requested_by_name": wr.get("requested_by_name"),
                "completed_at": wr.get("completed_at"),
                "erip_cancel_status": wr.get("erip_cancel_status"),
                "remote_cancel_status": wr.get("remote_cancel_status"),
                "remote_cancel_method": wr.get("remote_cancel_method"),
                "remote_cancel_error": wr.get("remote_cancel_error"),
                "remote_status_after": wr.get("remote_status_after"),
                "card_blocked": bool(wr.get("card_checkout_blocked_at")),
                "card_checkout_blocked_at": wr.get("card_checkout_blocked_at"),
                "telegram_update_status": wr.get("telegram_update_status"),
                "requires_check_reason": wr.get("requires_check_reason"),
            }
        return result

    def retry_remote_cancel(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/remote-cancel — v7.1.4.1.

        Retry BePaid DELETE for an already locally-withdrawn intent (legacy or failed).
        Does NOT create a new withdrawal record, does NOT edit Telegram again,
        does NOT touch MoyKlass.
        """
        if auth.get("_internal") is True and auth.get("role") in WITHDRAW_INVOICE_ROLES:
            role = auth["role"]
        else:
            role = self._role_for_user(int(auth.get("user_id") or 0))
        if role not in WITHDRAW_INVOICE_ROLES:
            return {"ok": False, "error": "Доступ запрещён. Требуется роль: owner, admin или operations."}

        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Счёт не найден.", "public_id": public_id}

        if pi.get("client_visibility") != "withdrawn":
            return {"ok": False, "error": "Счёт не отозван. Операция доступна только для отозванных счетов."}

        wr = self.storage.get_withdrawal_by_intent(public_id)
        if not wr:
            return {"ok": False, "error": "Запись отзыва не найдена."}

        withdrawal_id = wr["id"]

        # Idempotency: already successfully cancelled — do not re-call DELETE
        current_remote = str(wr.get("remote_cancel_status") or "")
        if current_remote in ("cancelled", "already_cancelled"):
            return {
                "ok": True,
                "idempotent": True,
                "local_withdrawal_status": "withdrawn",
                "remote_cancel_status": current_remote,
                "telegram_status": wr.get("telegram_update_status"),
            }

        # Re-verify payment not received (paid/ambiguous guard)
        payment_status = str(pi.get("status") or "")
        mk_payment_id = pi.get("mk_payment_id")
        mk_posting_status = str(pi.get("mk_posting_status") or "")
        confirmed_txs = self.storage.get_confirmed_bepaid_transactions_for_intent(public_id)
        already_paid = (
            payment_status in ("paid", "posted_to_moyklass")
            or bool(mk_payment_id)
            or mk_posting_status in ("posted", "claiming", "ambiguous")
            or bool(confirmed_txs)
        )
        if already_paid:
            log.warning(
                "payment_event=payment_remote_cancel_retry_blocked_paid intent=%s",
                public_id,
            )
            return {
                "ok": False,
                "remote_cancel_status": "already_paid",
                "error": "Платёж уже оплачен. Требуется возврат, а не отмена.",
            }

        # Resolve ERIP UID
        erip_uid = str(pi.get("bepaid_uid") or "").strip()
        erip_option = self.storage.get_option_by_channel(public_id, "erip") if hasattr(self.storage, "get_option_by_channel") else None
        if not erip_uid and erip_option:
            erip_uid = str(erip_option.get("bepaid_uid") or "").strip()

        if not erip_uid:
            return {
                "ok": False,
                "remote_cancel_status": "no_erip_uid",
                "error": "UID платежа в bePaid не найден. Отмена невозможна.",
            }

        log.info(
            "payment_event=payment_remote_cancel_retry_started intent=%s withdrawal_id=%d uid_present=1",
            public_id, withdrawal_id,
        )

        self._attempt_remote_cancel_for_withdrawal(withdrawal_id, erip_uid, now, public_id)

        final_wr = self.storage.get_withdrawal_by_intent(public_id) or {}
        remote_cancel_status = str(final_wr.get("remote_cancel_status") or "")

        if remote_cancel_status == "cancelled":
            log.info(
                "payment_event=payment_remote_cancel_retry_succeeded intent=%s withdrawal_id=%d"
                " remote_cancel_status=cancelled method=api_delete",
                public_id, withdrawal_id,
            )
        elif remote_cancel_status == "requires_check":
            log.warning(
                "payment_event=payment_remote_cancel_retry_requires_check intent=%s reason_code=%s",
                public_id, final_wr.get("remote_cancel_error") or "unknown",
            )

        return {
            "ok": remote_cancel_status == "cancelled",
            "local_withdrawal_status": "withdrawn",
            "remote_cancel_status": remote_cancel_status,
            "telegram_status": final_wr.get("telegram_update_status"),
        }

    def client_payments_list(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/client/payments — parent-only, returns published intents for own children."""
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        parent_telegram_id = self._effective_client_identity(auth)
        intents = self.storage.list_client_visible_payment_intents(parent_telegram_id)
        result = []
        _inactive_opt = {"cancelled", "superseded", "expired"}
        for pi in intents:
            opts = self.storage.get_options_for_intent(pi["public_id"])
            erip_opt = next(
                (o for o in opts if o.get("channel") == "erip"
                 and o.get("status") not in _inactive_opt),
                None,
            )
            acq_opt = next(
                (o for o in opts if o.get("channel") == "acquiring"
                 and o.get("status") not in _inactive_opt),
                None,
            )
            # ERIP account: options table first; fallback to legacy payment_intents field
            # for intents created before the dual-channel option system (same logic as publish-preview).
            erip_acct = str(erip_opt.get("bepaid_account_number") or "").strip() if erip_opt else ""
            if not erip_acct and pi.get("bepaid_uid"):
                erip_acct = str(pi.get("bepaid_account_number") or "").strip()
            amount_minor = pi.get("amount_minor") or 0
            amount_byn = round(int(amount_minor) / 100.0, 2) if amount_minor else None
            paid_minor = pi.get("paid_amount_minor")
            paid_byn = round(int(paid_minor) / 100.0, 2) if paid_minor is not None else None
            result.append({
                "public_id": pi["public_id"],
                # v7.1.13 — additive passthrough only (field already existed on
                # the row, just wasn't copied into the trimmed client response)
                # so the new home-dashboard payment card can filter by the
                # currently-selected child. Does not change any existing
                # consumer's behavior — they simply ignore the extra field.
                "mk_user_id": pi.get("mk_user_id"),
                "student_name": pi.get("student_name"),
                "amount_byn": amount_byn,
                "purpose": pi.get("purpose"),
                "period_month": pi.get("period_month"),
                "payment_method": pi.get("payment_method"),
                "status": pi.get("status"),
                "comment": pi.get("comment"),
                "published_at": pi.get("published_at"),
                "paid_at": pi.get("paid_at"),
                "paid_amount_byn": paid_byn,
                "erip_account_number": erip_acct or None,
                "acquiring_payment_url": (
                    str(acq_opt.get("payment_url") or "").strip() or None
                ) if acq_opt else None,
                # v7.0.99.0 — deadline fields
                "due_at": pi.get("due_at"),
                "due_at_source": pi.get("due_at_source"),
                "due_status": pi.get("due_status") or "upcoming",
            })
        return {"ok": True, "payments": result, "total": len(result)}

    def client_payment_card_token(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """GET /api/client/payments/{public_id}/card-token — return fresh card checkout URL.

        Self-healing: if the existing token is expired or missing, creates a new one.
        Guards: intent must be published, unpaid, not withdrawn, no confirmed transaction.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        if self._owner_test_client_mode_active(auth):
            # v7.1.13.1 — this "GET" self-heals by creating a real bePaid
            # acquiring checkout token/URL; that is a genuine payment action
            # and must never run against a real client's payment intent
            # just because the owner is previewing their cabinet.
            return {"ok": False, "error": "owner_test_mode_payment_blocked"}

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Счёт не найден."}
        if pi.get("client_visibility") != "published":
            return {"ok": False, "error": "Счёт недоступен."}
        if pi.get("client_visibility") == "withdrawn":
            return {"ok": False, "error": "Счёт отозван."}
        if str(pi.get("status") or "") in ("paid", "posted_to_moyklass"):
            return {"ok": False, "error": "Счёт уже оплачен."}
        if pi.get("webhook_verified") or str(pi.get("paid_transaction_uid") or "").strip():
            return {"ok": False, "error": "Счёт уже подтверждён."}

        # Check existing acquiring option
        import datetime as _dtnow
        _now_str = _dtnow.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        acq_opt = self.storage.get_option_by_channel(public_id, "acquiring")
        if acq_opt and acq_opt.get("payment_url") and acq_opt.get("checkout_token"):
            _exp = str(acq_opt.get("expires_at") or "").strip()
            _st = str(acq_opt.get("status") or "").strip()
            if _st != "expired" and (not _exp or _exp > _now_str):
                return {
                    "ok": True,
                    "payment_url": acq_opt["payment_url"],
                    "checkout_token": acq_opt["checkout_token"],
                    "renewed": False,
                }

        # Token expired or missing — create a new one via internal auth
        _int_auth = {"role": "owner", "user_id": 0, "_internal": True}
        result = self.payment_intent_create_acquiring_option(_int_auth, public_id)
        if not result.get("ok"):
            return {"ok": False, "error": result.get("error", "Не удалось создать ссылку оплаты.")}
        return {
            "ok": True,
            "payment_url": result.get("payment_url"),
            "checkout_token": result.get("checkout_token"),
            "renewed": True,
        }

    # ── v7.0.93.1/93.2 — separate client parent-child link system ───────────

    def _require_client_link_admin_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in CLIENT_LINK_ADMIN_ROLES:
            return {"ok": False, "error": "Доступ ограничен: owner, admin, operations."}
        return None

    def client_children_list(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/client/children — unified read-only list for parents.

        Returns both client children (source=client, available_modules=[payments])
        and food children (source=food, available_modules=[food]).
        Food parent_child_links are read-only here; food module is not modified.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        parent_tid = self._effective_client_identity(auth)

        client_links = self.storage.list_client_children_for_parent(parent_tid)
        client_children = [
            {
                "source": "client",
                "mk_user_id": l["mk_user_id"],
                "display_name": l.get("child_display_name") or "Ученик",
                "linked_at": l.get("linked_at"),
                "available_modules": ["payments"],
            }
            for l in client_links
        ]

        # Food children — read-only from the food system
        food_children_raw = self.storage.list_children_for_parent(parent_tid)
        food_children = [
            {
                "source": "food",
                "mk_student_id": c.get("mk_student_id"),
                "display_name": c.get("full_name") or c.get("first_name") or "Ребёнок",
                "group_name": c.get("group_name"),
                "classroom": c.get("classroom"),
                "confirmed_at": c.get("confirmed_at"),
                "available_modules": ["food"],
            }
            for c in food_children_raw
        ]

        return {
            "ok": True,
            "children": client_children + food_children,
            "client_count": len(client_children),
            "food_count": len(food_children),
        }

    # ── v7.1.13 — client notification center (parent-facing) ─────────────────
    # Not a chat: a flat, paginated, read/unread list of discrete messages.
    # Ownership/scope/category filtering all happens in storage.py's query —
    # these handlers only resolve identity (auth["user_id"], never a
    # frontend-supplied telegram_id) and the food-only category restriction.

    def client_notifications_list(self, auth: dict[str, Any], params: dict[str, Any]) -> dict[str, Any]:
        """GET /api/client/notifications?limit=&before_id= — parent-only."""
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        if not self._client_notifications_enabled(int(auth["user_id"])):
            # v7.1.13 round 2 — safe disabled state: no data leaked, no
            # error surfaced to the client, table itself untouched.
            return {"ok": True, "notifications": [], "has_more": False, "disabled": True}
        user_id = self._effective_client_identity(auth)
        client_kind = self.storage.get_client_kind_for_parent(user_id)
        allowed = self._notification_allowed_categories(client_kind)
        try:
            limit = int(params.get("limit")) if params.get("limit") else 20
        except (TypeError, ValueError):
            limit = 20
        before_id: Optional[int] = None
        raw_before = params.get("before_id")
        if raw_before:
            try:
                before_id = int(raw_before)
            except (TypeError, ValueError):
                before_id = None
        items, has_more = self.storage.list_client_notifications_for_recipient(
            user_id, allowed_categories=allowed, limit=limit, before_id=before_id,
        )
        for it in items:
            if it.get("action_key") not in NOTIFICATION_ACTION_KEYS:
                it["action_key"] = "none"
            it["unread"] = it.get("read_at") is None
        return {"ok": True, "notifications": items, "has_more": has_more}

    def client_notification_get(self, auth: dict[str, Any], notification_id_str: str) -> dict[str, Any]:
        """GET /api/client/notifications/{id} — parent-only, own notifications only."""
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        if not self._client_notifications_enabled(int(auth["user_id"])):
            return {"ok": False, "error": "notifications_disabled"}
        try:
            notification_id = int(notification_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid notification id"}
        user_id = self._effective_client_identity(auth)
        client_kind = self.storage.get_client_kind_for_parent(user_id)
        allowed = self._notification_allowed_categories(client_kind)
        item = self.storage.get_client_notification_for_recipient(notification_id, user_id, allowed_categories=allowed)
        if not item:
            return {"ok": False, "error": "Уведомление не найдено."}
        if item.get("action_key") not in NOTIFICATION_ACTION_KEYS:
            item["action_key"] = "none"
        item["unread"] = item.get("read_at") is None
        return {"ok": True, "notification": item}

    def client_notification_mark_read(self, auth: dict[str, Any], notification_id_str: str) -> dict[str, Any]:
        """POST /api/client/notifications/{id}/read — idempotent."""
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        if not self._client_notifications_enabled(int(auth["user_id"])):
            return {"ok": False, "error": "notifications_disabled"}
        try:
            notification_id = int(notification_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid notification id"}
        user_id = self._effective_client_identity(auth)
        # Re-verify current visibility (same query as GET) before marking —
        # an unlinked child's notification can't be touched even by its
        # original recipient row.
        client_kind = self.storage.get_client_kind_for_parent(user_id)
        allowed = self._notification_allowed_categories(client_kind)
        item = self.storage.get_client_notification_for_recipient(notification_id, user_id, allowed_categories=allowed)
        if not item:
            return {"ok": False, "error": "Уведомление не найдено."}
        self.storage.mark_client_notification_read(notification_id, user_id)
        return {"ok": True}

    # ── v7.1.13 §12 — TEMPORARY owner-only smoke-test sender ──────────────────
    # Explicitly NOT the staff communications center (v7.1.13.1, separate
    # design). Can only target ONE already-linked test client at a time —
    # there is no audience/segment/broadcast parameter anywhere in this
    # function, so a mass send is structurally impossible here, not just
    # policy-denied. Never touches Telegram delivery.
    def owner_test_notification_create(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/owner/test-notifications"""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in {"owner", "admin"}:
            return {"ok": False, "error": "access_denied"}

        mk_user_id = str(body.get("mk_user_id") or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "Укажите mk_user_id тестового клиента."}
        scope = str(body.get("scope") or "").strip()
        if scope not in NOTIFICATION_SCOPES:
            return {"ok": False, "error": f"scope должен быть одним из: {', '.join(NOTIFICATION_SCOPES)}"}
        category = str(body.get("category") or "general").strip()
        if category not in NOTIFICATION_CATEGORIES:
            return {"ok": False, "error": f"category должна быть одной из: {', '.join(NOTIFICATION_CATEGORIES)}"}
        priority = str(body.get("priority") or "normal").strip()
        if priority not in NOTIFICATION_PRIORITIES:
            return {"ok": False, "error": f"priority должен быть одним из: {', '.join(NOTIFICATION_PRIORITIES)}"}
        action_key = str(body.get("action_key") or "none").strip()
        if action_key not in NOTIFICATION_ACTION_KEYS:
            return {"ok": False, "error": f"action_key должен быть одним из: {', '.join(NOTIFICATION_ACTION_KEYS)}"}
        title = str(body.get("title") or "").strip()
        text = str(body.get("body") or "").strip()
        if not title or not text:
            return {"ok": False, "error": "Заполните заголовок и текст."}

        recipient_ids = self.storage.get_active_parent_telegram_ids_for_mk_user(mk_user_id)
        if not recipient_ids:
            return {"ok": False, "error": "Этот mk_user_id не привязан ни к одному родителю (нет активной связи)."}

        return self.storage.create_client_notification(
            title=title, body=text, category=category, priority=priority, scope=scope,
            mk_user_id=mk_user_id if scope == "child" else None,
            action_key=action_key,
            created_by_telegram_id=str(auth["user_id"]),
            recipient_telegram_ids=recipient_ids,
        )

    # v7.1.7 — maps storage-layer reason_code → audit event_type for failed
    # code-use attempts. Several distinct reason_codes intentionally collapse
    # into the same (required-minimum) event_type bucket; reason_code itself
    # (stored separately in the audit row) keeps the precise detail.
    _CLIENT_LINK_FAILURE_EVENT_BY_REASON = {
        "code_not_found": "code_use_failed_invalid",
        "invalid_code_format": "code_use_failed_invalid",
        "code_invalidated": "code_use_failed_invalid",
        "telegram_already_linked": "code_use_failed_conflict",
        "code_expired": "code_use_failed_expired",
        "code_already_used": "code_use_failed_used",
    }

    # v7.1.7 (security correction) — retention cutoff for client_link_rate_limit_attempts,
    # applied opportunistically (see _maybe_cleanup_client_link_rate_limit below)
    # rather than on every request, so it never adds latency to the hot path.
    _CLIENT_LINK_RATE_LIMIT_RETENTION_HOURS = 24
    _CLIENT_LINK_RATE_LIMIT_CLEANUP_PROBABILITY = 0.01

    def _safe_client_link_audit(self, **kwargs: Any) -> None:
        """Call log_client_link_audit_event, swallowing any exception.

        log_client_link_audit_event already catches its own errors internally;
        this is a second, defensive layer specifically so that nothing audit-
        related can ever reach the security-critical rate-limit path in
        client_link_child, even if that internal handling were ever changed.
        """
        try:
            self.storage.log_client_link_audit_event(**kwargs)
        except Exception as exc:
            log.warning("client_link_audit_call_failed error=%s", exc)

    def _maybe_cleanup_client_link_rate_limit(self, now_dt: datetime) -> None:
        if random.random() >= self._CLIENT_LINK_RATE_LIMIT_CLEANUP_PROBABILITY:
            return
        cutoff = (now_dt - timedelta(hours=self._CLIENT_LINK_RATE_LIMIT_RETENTION_HOURS)).strftime("%Y-%m-%dT%H:%M:%S")
        self.storage.cleanup_old_client_link_rate_limit_attempts(cutoff)

    def client_link_child(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/children/link — parent enters CL- code to link a child.

        v7.1.7 (security correction): the rate limiter reads/writes
        client_link_rate_limit_attempts, never client_link_audit_log. Reads and
        writes to that table are allowed to raise; if they do, this method
        fails closed (HTTP 503, reason_code=rate_limit_unavailable) instead of
        letting code-guessing continue unlimited and uncounted. Audit logging
        (_safe_client_link_audit) remains fail-open by design and never
        affects this decision either way.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role != "parent":
            return {"ok": False, "error": "Доступ только для родителей."}
        if self._owner_test_client_mode_active(auth):
            # v7.1.13.1 — never allowed: creating a new client_parent_child_
            # links row "just to test" is explicitly forbidden, and this
            # would otherwise link the code to the OWNER's own real
            # Telegram id, not the previewed client's.
            return {"ok": False, "error": "owner_test_mode_link_blocked"}
        parent_tid = str(auth["user_id"])
        now_dt = datetime.utcnow()
        unavailable = {
            "ok": False,
            "error": "Сервис временно недоступен. Попробуйте позже.",
            "reason_code": "rate_limit_unavailable",
        }

        # Step 1: check the current limit. A read failure must NOT be treated
        # as "no recent failures" — that would fail open — so it is fatal here.
        window_start = (now_dt - timedelta(minutes=CLIENT_LINK_RATE_LIMIT_WINDOW_MINUTES)).strftime("%Y-%m-%dT%H:%M:%S")
        try:
            fail_count, oldest_failure = self.storage.count_recent_client_link_rate_limit_failures(parent_tid, window_start)
        except Exception as exc:
            log.warning("client_link_rate_limit_read_failed actor=%s error=%s", parent_tid, exc)
            return unavailable

        if fail_count >= CLIENT_LINK_MAX_FAILED_ATTEMPTS:
            retry_after = CLIENT_LINK_RATE_LIMIT_WINDOW_MINUTES * 60
            if oldest_failure:
                try:
                    oldest_dt = datetime.strptime(oldest_failure, "%Y-%m-%dT%H:%M:%S")
                    retry_after = max(1, int(CLIENT_LINK_RATE_LIMIT_WINDOW_MINUTES * 60 - (now_dt - oldest_dt).total_seconds()))
                except ValueError:
                    pass
            # Best-effort marker row + audit event; neither affects the count
            # (only 'failed' rows are counted), so failures here are non-fatal.
            try:
                self.storage.record_client_link_rate_limit_attempt(parent_tid, "rate_limited", "rate_limited")
            except Exception as exc:
                log.warning("client_link_rate_limit_marker_write_failed actor=%s error=%s", parent_tid, exc)
            self._safe_client_link_audit(
                event_type="code_use_rate_limited",
                parent_telegram_user_id=parent_tid, actor_telegram_user_id=parent_tid,
                actor_role=role, result="blocked", reason_code="rate_limited",
            )
            return {
                "ok": False,
                "error": "Слишком много неудачных попыток. Попробуйте позже.",
                "reason_code": "rate_limited",
                "retry_after_seconds": retry_after,
            }

        code = str(body.get("code") or "").strip().upper()
        if not code or not code.startswith("CL-") or len(code) != 11:
            # Step 3: record the failed attempt. A write failure here IS fatal —
            # if it silently didn't count, this guess (and every subsequent one
            # until the storage recovers) would bypass the limiter entirely.
            try:
                self.storage.record_client_link_rate_limit_attempt(parent_tid, "failed", "invalid_code_format")
            except Exception as exc:
                log.warning("client_link_rate_limit_write_failed actor=%s error=%s", parent_tid, exc)
                return unavailable
            self._safe_client_link_audit(
                event_type="code_use_failed_invalid",
                parent_telegram_user_id=parent_tid, actor_telegram_user_id=parent_tid,
                actor_role=role, result="failed", reason_code="invalid_code_format",
            )
            self.storage.log_onboarding_event(
                "code_invalid", "cl_code", "failed",
                parent_telegram_id=parent_tid, reason_code="invalid_code_format",
            )
            self._maybe_cleanup_client_link_rate_limit(now_dt)
            msg = "Введите код привязки." if not code else "Неверный формат кода. Ожидается CL-XXXXXXXX."
            return {"ok": False, "error": msg, "reason_code": "invalid_code_format"}

        # v7.1.15 — launch-readiness "started" marker, logged once the code
        # has passed basic format validation (garbage input already counted
        # as code_invalid above, not as a started attempt).
        self.storage.log_onboarding_event("code_submitted", "cl_code", "started", parent_telegram_id=parent_tid)

        # Step 2: check/consume the code (unrelated storage — client_child_link_codes).
        now = now_dt.strftime("%Y-%m-%dT%H:%M:%S")
        result = self.storage.link_client_child(parent_tid, code, now)

        # Strip internal fields (mk_user_id/code_id) before they ever reach the
        # parent-facing response — mk_user_id must not be exposed to the client
        # before/without a fully successful link.
        mk_user_id = result.pop("mk_user_id", None)
        code_id = result.pop("code_id", None)

        if result.get("ok"):
            # Step 4: clear failures on success. Best-effort: the link itself is
            # already committed and real, so a bookkeeping failure here must not
            # undo it — worst case the user's prior failure count isn't reset,
            # which fails toward MORE restrictive (safe), never toward bypass.
            try:
                self.storage.record_client_link_rate_limit_attempt(parent_tid, "success")
            except Exception as exc:
                log.warning("client_link_rate_limit_success_write_failed actor=%s error=%s", parent_tid, exc)
            # Step 5: audit, separately, still fail-open.
            self._safe_client_link_audit(
                event_type="code_used", mk_user_id=mk_user_id, code_id=code_id,
                parent_telegram_user_id=parent_tid, actor_telegram_user_id=parent_tid,
                actor_role=role, result="success",
                note="already_linked" if result.get("already_linked") else None,
            )
            result["mk_user_id"] = mk_user_id  # restore: legitimate post-success field, unchanged existing contract
            # v7.1.11 correction: this endpoint is role=parent only (see top of
            # this method) — it is the SAME generic self-service link a parent
            # uses for ordinary CL-code linking, not a staff Payments flow.
            # Payment automation pilot enrollment must NEVER trigger from here;
            # it only happens from the staff-gated
            # client_admin_link_and_enroll() below (owner/admin/client_manager).
            # v7.1.15 — launch-readiness event log (separate from the audit
            # log above; see storage.log_onboarding_event). Called after
            # storage.link_client_child has already returned/committed, never
            # from inside its own transaction. "already_linked" (idempotent
            # replay of an already-used code by the same parent) is reported
            # as link_already_exists, distinct from a genuinely new link.
            self.storage.log_onboarding_event(
                "link_already_exists" if result.get("already_linked") else "link_created",
                "cl_code", "succeeded",
                parent_telegram_id=parent_tid, mk_user_id=mk_user_id,
            )
        else:
            reason_code = result.get("reason_code") or "code_not_found"
            # Step 3: record the failed attempt — fatal on write failure (see above).
            try:
                self.storage.record_client_link_rate_limit_attempt(parent_tid, "failed", reason_code)
            except Exception as exc:
                log.warning("client_link_rate_limit_write_failed actor=%s error=%s", parent_tid, exc)
                return unavailable
            event_type = self._CLIENT_LINK_FAILURE_EVENT_BY_REASON.get(reason_code, "code_use_failed_invalid")
            self._safe_client_link_audit(
                event_type=event_type, mk_user_id=mk_user_id, code_id=code_id,
                parent_telegram_user_id=parent_tid, actor_telegram_user_id=parent_tid,
                actor_role=role, result="failed", reason_code=reason_code,
            )
            self.storage.log_onboarding_event(
                "code_invalid" if reason_code in ("code_not_found", "invalid_code_format") else "onboarding_failed",
                "cl_code", "failed",
                parent_telegram_id=parent_tid, mk_user_id=mk_user_id, reason_code=reason_code,
            )

        self._maybe_cleanup_client_link_rate_limit(now_dt)
        return result

    def client_admin_link_and_enroll(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/admin/link-and-enroll — v7.1.11 staff-only Payments onboarding.

        This is the ONLY place that ensures a payment automation pilot record.
        It is gated to PAYMENT_ONBOARDING_STAFF_ROLES (owner/admin/client_manager
        — deliberately NOT operations, per spec) and never derives that gate
        from anything client-supplied (no trusting a "source=payments" body
        flag) — the role check below, resolved server-side from auth, is the
        only thing that decides whether pilot enrollment happens.

        Reuses storage.link_client_child — the exact same code-validation and
        parent-link logic the self-service parent flow uses — rather than a
        second parallel client-link mechanism. Staff supplies which parent
        Telegram account to link (parent_telegram_user_id), same as they would
        relay over a support channel.

        Fail-safe, not fail-open: if the link itself succeeds but pilot
        enrollment fails, the link is NOT rolled back (it is already real and
        committed) but the response is a transparent partial result
        (automation_status="failed") — never a false "connected" success.
        Calling again (including on an already_linked code) retries pilot
        enrollment and stays idempotent once it succeeds.
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_ONBOARDING_STAFF_ROLES:
            return {"ok": False, "error": "Доступно только owner, admin и client_manager."}

        actor_tid = str(auth.get("user_id") or "")
        parent_tid = str(body.get("parent_telegram_user_id") or "").strip()
        code = str(body.get("code") or "").strip().upper()
        if not parent_tid:
            return {"ok": False, "error": "parent_telegram_user_id обязателен"}
        if not code or not code.startswith("CL-") or len(code) != 11:
            return {"ok": False, "error": "Неверный формат кода. Ожидается CL-XXXXXXXX.", "reason_code": "invalid_code_format"}

        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
        result = self.storage.link_client_child(parent_tid, code, now)
        mk_user_id = result.pop("mk_user_id", None)
        code_id = result.pop("code_id", None)

        if not result.get("ok"):
            # Never leak the plaintext code or which mk_user_id a wrong/used
            # code belongs to — same discipline as the parent-facing endpoint.
            self.storage.log_onboarding_event(
                "onboarding_failed", "cl_code", "failed",
                parent_telegram_id=parent_tid, reason_code=result.get("reason_code"),
            )
            return result

        result["mk_user_id"] = mk_user_id
        self._safe_client_link_audit(
            event_type="code_used", mk_user_id=mk_user_id, code_id=code_id,
            parent_telegram_user_id=parent_tid, actor_telegram_user_id=actor_tid,
            actor_role=role, result="success",
            note="staff_onboarding" + ("_already_linked" if result.get("already_linked") else ""),
        )
        self.storage.log_onboarding_event(
            "link_already_exists" if result.get("already_linked") else "link_created",
            "cl_code", "succeeded",
            parent_telegram_id=parent_tid, mk_user_id=mk_user_id,
        )

        automation: dict[str, Any] = {
            "link_status": "already_linked" if result.get("already_linked") else "linked",
            "automation_status": "failed",
            "pilot_created": False,
            "mode": None,
            "enabled": None,
        }
        try:
            pilot_outcome = self.storage.ensure_payment_pilot_from_client_link(mk_user_id, actor_tid, now)
            automation["automation_status"] = "connected"
            automation["pilot_created"] = bool(pilot_outcome.get("created"))
            automation["mode"] = pilot_outcome.get("mode")
            automation["enabled"] = pilot_outcome.get("enabled")
        except Exception as exc:
            # Fail-safe: the link above is already committed and real and is
            # NOT undone. Log contains only mk_user_id — no CL code, no
            # parent_tid, no secrets.
            log.warning("payments_onboarding_pilot_ensure_failed mk_user_id=%s error=%s", mk_user_id, exc)

        result["payment_automation"] = automation
        return result

    def admin_client_generate_code(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/admin/link-codes — admin creates a CL- code for a student.

        expires_at defaults to CLIENT_LINK_CODE_TTL_HOURS from now if the caller
        doesn't pass one (enforced in storage.create_client_link_code).
        """
        denied = self._require_client_link_admin_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        mk_user_id = str(body.get("mk_user_id") or "").strip()
        child_display_name = str(body.get("child_display_name") or "").strip()
        expires_at = str(body.get("expires_at") or "").strip() or None
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        if not child_display_name:
            return {"ok": False, "error": "child_display_name обязателен"}
        created_by = str(auth.get("user_id") or "")
        result = self.storage.create_client_link_code(mk_user_id, child_display_name, created_by, expires_at)
        if result.get("ok"):
            self._safe_client_link_audit(
                event_type="code_created", mk_user_id=mk_user_id, code_id=result.get("code_id"),
                actor_telegram_user_id=created_by, actor_role=role, result="success",
            )
        elif result.get("reason_code") == "client_already_linked":
            self._safe_client_link_audit(
                event_type="code_create_blocked_already_linked", mk_user_id=mk_user_id,
                actor_telegram_user_id=created_by, actor_role=role,
                result="blocked", reason_code="client_already_linked",
            )
        return result

    def admin_client_invalidate_code(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/admin/link-codes/invalidate — admin invalidates a code by id."""
        denied = self._require_client_link_admin_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        try:
            code_id = int(body.get("code_id") or 0)
        except (TypeError, ValueError):
            return {"ok": False, "error": "code_id must be an integer"}
        if not code_id:
            return {"ok": False, "error": "code_id обязателен"}
        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
        invalidated_by = str(auth.get("user_id") or "")
        result = self.storage.invalidate_client_link_code(code_id, invalidated_by, now)
        mk_user_id = result.pop("mk_user_id", None)  # internal-only, for the audit call below
        if result.get("ok"):
            self._safe_client_link_audit(
                event_type="code_invalidated", code_id=code_id, mk_user_id=mk_user_id,
                actor_telegram_user_id=invalidated_by, actor_role=role, result="success",
            )
        return result

    def admin_client_unlink_child(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/admin/unlink — admin unlinks a parent from a student."""
        denied = self._require_client_link_admin_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        parent_telegram_user_id = str(body.get("parent_telegram_user_id") or "").strip()
        mk_user_id = str(body.get("mk_user_id") or "").strip()
        if not parent_telegram_user_id or not mk_user_id:
            return {"ok": False, "error": "parent_telegram_user_id и mk_user_id обязательны"}
        now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
        unlinked_by = str(auth.get("user_id") or "")
        result = self.storage.unlink_client_child(parent_telegram_user_id, mk_user_id, unlinked_by, now)
        if result.get("ok"):
            self._safe_client_link_audit(
                event_type="client_unlinked", mk_user_id=mk_user_id,
                parent_telegram_user_id=parent_telegram_user_id,
                actor_telegram_user_id=unlinked_by, actor_role=role, result="success",
            )
        return result

    def admin_client_link_status(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/admin/link-status?mk_user_id=... — admin views link status for a student."""
        denied = self._require_client_link_admin_access(auth)
        if denied:
            return denied
        mk_user_id = str(params.get("mk_user_id") or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен"}
        data = self.storage.get_client_link_status_for_student(mk_user_id)
        links = data.get("links") or []
        codes = data.get("codes") or []
        active_link = next((l for l in links if l.get("status") == "active"), None)
        active_code = next((c for c in codes if c.get("status") == "active"), None)
        # v7.1.7 — safe derived summary fields for future UI; never includes
        # code_hash or the plaintext of a used code (get_client_link_status_for_student
        # already excludes code_hash from its SELECT).
        return {
            "ok": True,
            **data,
            "linked": bool(active_link),
            "linked_at": active_link.get("linked_at") if active_link else None,
            "active_code_exists": bool(active_code),
            "code_expires_at": active_code.get("expires_at") if active_code else None,
            "code_created_at": active_code.get("created_at") if active_code else None,
        }

    def admin_client_search_students(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/admin/search-students?q=... — search MoyKlass students for link management.

        Returns limited fields: mk_user_id, name, active client link, active code status.
        Never returns YC food codes or food links.
        """
        denied = self._require_client_link_admin_access(auth)
        if denied:
            return denied
        q = str(params.get("q") or "").strip()
        if not q:
            return {"ok": False, "error": "Введите имя ученика или userId МойКласс"}
        if len(q) > 200:
            return {"ok": False, "error": "Запрос слишком длинный"}

        mk_results: list[dict] = []
        q_is_numeric = q.isdigit()

        if q_is_numeric:
            # Direct lookup by userId
            try:
                res = self.moyklass.request("GET", f"/v1/company/users/{q}")
                if res.ok:
                    u = res.data if isinstance(res.data, dict) else {}
                    if u.get("id"):
                        mk_results = [u]
                    elif isinstance(res.data, list) and res.data:
                        mk_results = res.data[:10]
            except Exception:
                pass
        else:
            # Name search via query param
            try:
                res = self.moyklass.request("GET", "/v1/company/users", params={"q": q, "limit": "15"})
                if res.ok:
                    raw = res.data
                    if isinstance(raw, list):
                        mk_results = raw[:15]
                    elif isinstance(raw, dict) and isinstance(raw.get("items"), list):
                        mk_results = raw["items"][:15]
            except Exception:
                pass

        students = []
        for u in mk_results:
            mk_user_id = str(u.get("id") or u.get("userId") or u.get("mk_user_id") or "").strip()
            if not mk_user_id:
                continue
            first = str(u.get("name") or u.get("firstName") or "").strip()
            last = str(u.get("lastName") or "").strip()
            full_name = f"{first} {last}".strip() if last else first
            status_data = self.storage.get_client_link_status_for_student(mk_user_id)
            students.append({
                "mk_user_id": mk_user_id,
                "full_name": full_name or f"Ученик #{mk_user_id}",
                "codes": status_data.get("codes", []),
                "links": status_data.get("links", []),
            })

        return {"ok": True, "students": students, "total": len(students), "query": q}

    # ── v7.1.14 — staff "Рассылки" (communications center) ─────────────────
    # MVP scope: real in-app client notifications only (see storage's
    # staff_communication_campaigns/staff_communication_recipients). Every
    # mutation below re-checks _require_communications_access itself —
    # never assume a caller already checked it.

    def _communications_load_campaign(self, campaign_id_str: str) -> Optional[dict[str, Any]]:
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return None
        return self.storage.get_staff_communication_campaign(campaign_id)

    def _communications_format_minsk_label(self, scheduled_at_utc: Optional[str]) -> Optional[str]:
        if not scheduled_at_utc:
            return None
        import zoneinfo
        try:
            dt_utc = datetime.strptime(scheduled_at_utc, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        except ValueError:
            return None
        minsk = dt_utc.astimezone(zoneinfo.ZoneInfo("Europe/Minsk"))
        months = ["января", "февраля", "марта", "апреля", "мая", "июня",
                  "июля", "августа", "сентября", "октября", "ноября", "декабря"]
        return f"{minsk.day} {months[minsk.month - 1]} {minsk.year} в {minsk.strftime('%H:%M')} по времени Минска"

    def _communications_minsk_to_utc(self, date_str: str, time_str: str) -> tuple[Optional[str], Optional[str]]:
        import zoneinfo
        date_str = str(date_str or "").strip()
        time_str = str(time_str or "").strip()
        if not date_str:
            return None, "Укажите дату отправки."
        if not time_str:
            return None, "Укажите время отправки."
        try:
            naive = datetime.strptime(f"{date_str} {time_str}", "%Y-%m-%d %H:%M")
        except ValueError:
            return None, "Некорректная дата или время."
        minsk_dt = naive.replace(tzinfo=zoneinfo.ZoneInfo("Europe/Minsk"))
        utc_dt = minsk_dt.astimezone(timezone.utc)
        if utc_dt <= datetime.now(timezone.utc):
            return None, "Нельзя запланировать отправку на прошедшее время."
        return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ"), None

    def _communications_campaign_public(self, campaign: dict[str, Any]) -> dict[str, Any]:
        return {
            "id": campaign["id"],
            "name": campaign.get("name") or "",
            "status": campaign.get("status"),
            "audienceType": campaign.get("audience_type") or "",
            "audienceConfig": (lambda: (lambda s: s if isinstance(s, dict) else {})(
                self._safe_json_loads(campaign.get("audience_config_json"))))(),
            "eligibleCount": campaign.get("eligible_count"),
            "excludedCount": campaign.get("excluded_count"),
            "snapshotHash": campaign.get("audience_snapshot_hash"),
            "snapshotCreatedAt": campaign.get("audience_snapshot_created_at"),
            "category": campaign.get("category"),
            "priority": campaign.get("priority"),
            "scope": campaign.get("scope"),
            "title": campaign.get("title") or "",
            "body": campaign.get("body") or "",
            "actionKey": campaign.get("action_key"),
            "scheduleMode": campaign.get("schedule_mode"),
            "scheduledAtUtc": campaign.get("scheduled_at_utc"),
            "scheduledLabel": self._communications_format_minsk_label(campaign.get("scheduled_at_utc")),
            "timezone": campaign.get("timezone"),
            "createdAt": campaign.get("created_at"),
            "updatedAt": campaign.get("updated_at"),
            "sentAt": campaign.get("sent_at"),
            "cancelledAt": campaign.get("cancelled_at"),
            "lastError": campaign.get("last_error"),
        }

    @staticmethod
    def _safe_json_loads(raw: Any) -> Any:
        if not raw:
            return {}
        try:
            return json.loads(raw)
        except (TypeError, ValueError):
            return {}

    def _communications_split_by_notification_gate(
        self, pairs: list[tuple[str, Optional[str]]],
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """pairs: [(parent_telegram_id, mk_user_id_or_None), ...], already
        deduped by caller. Splits into eligible/excluded based on the
        EXISTING CLIENT_NOTIFICATIONS_ENABLED/pilot gate — a parent whose
        notification center isn't open yet is excluded, never silently
        counted as reachable."""
        eligible: list[dict[str, Any]] = []
        excluded: list[dict[str, Any]] = []
        for pid, mk in pairs:
            entry = {"parent_telegram_id": pid, "mk_user_id": mk, "recipient_key": pid}
            try:
                user_id = int(pid)
            except (TypeError, ValueError):
                gate_open = False
            else:
                gate_open = self._client_notifications_enabled(user_id)
            if gate_open:
                eligible.append(entry)
            else:
                excluded.append({**entry, "exclusion_reason": "Уведомления в приложении пока не включены для этого родителя."})
        return eligible, excluded

    def _resolve_audience_single_client(self, config: dict[str, Any]) -> dict[str, Any]:
        parent_telegram_id = str(config.get("parent_telegram_id") or "").strip()
        if not parent_telegram_id:
            return {"ok": False, "error": "Не выбран клиент."}
        candidates = self.storage.find_trusted_client_context_candidates(parent_telegram_id)
        match = next((c for c in candidates if c["parent_telegram_id"] == parent_telegram_id), None)
        if not match:
            return {"ok": False, "error": "Клиент не найден среди активных связей."}
        scope_mk_user_id = str(config.get("scope_mk_user_id") or "").strip() or None
        if scope_mk_user_id and not any(str(ch["mk_user_id"]) == scope_mk_user_id for ch in match["children"]):
            return {"ok": False, "error": "Указанный ребёнок не связан с этим родителем."}
        eligible, excluded = self._communications_split_by_notification_gate([(parent_telegram_id, scope_mk_user_id)])
        label = f"Родитель Telegram ID {parent_telegram_id}"
        label += f" · ребёнок {scope_mk_user_id}" if scope_mk_user_id else " · вся семья"
        return {
            "ok": True, "eligible": eligible, "excluded": excluded,
            "distinct_parents": 1, "matched_children": 1 if scope_mk_user_id else max(1, len(match["children"])),
            "resolved_audience_label": label, "diagnostics": {"client_kind": match["client_kind"]},
        }

    def _resolve_audience_all_parents(self) -> dict[str, Any]:
        links = self.storage.list_active_client_parent_child_links()
        parents: dict[str, str] = {}
        for row in links:
            pid = str(row["parent_telegram_user_id"])
            parents.setdefault(pid, str(row["mk_user_id"]))
        pairs = list(parents.items())
        eligible, excluded = self._communications_split_by_notification_gate(pairs)
        return {
            "ok": True, "eligible": eligible, "excluded": excluded,
            "distinct_parents": len(parents), "matched_children": len(links),
            "resolved_audience_label": "Все родители с активным кабинетом Yellow Club",
            "diagnostics": {"matched_children": len(links), "distinct_parents": len(parents)},
        }

    def _resolve_audience_connection_campaign(self, config: dict[str, Any]) -> dict[str, Any]:
        try:
            campaign_id = int(config.get("campaign_id"))
        except (TypeError, ValueError):
            return {"ok": False, "error": "Не выбрана кампания подключения."}
        campaign = self.storage.get_onboarding_campaign(campaign_id)
        if not campaign:
            return {"ok": False, "error": "Кампания не найдена."}
        if campaign.get("is_system"):
            return {"ok": False, "error": "Системные кампании нельзя выбрать для рассылки."}
        mk_ids = sorted(self.storage.get_onboarding_campaign_recipient_mk_ids(campaign_id))
        parents: dict[str, str] = {}
        not_connected: list[dict[str, Any]] = []
        for mk in mk_ids:
            active_parents = self.storage.get_active_parent_telegram_ids_for_mk_user(mk)
            if not active_parents:
                not_connected.append({
                    "parent_telegram_id": f"unconnected:{mk}", "mk_user_id": mk,
                    "recipient_key": f"unconnected:{mk}", "exclusion_reason": "Кабинет ещё не подключён.",
                })
                continue
            for pid in active_parents:
                parents.setdefault(pid, mk)
        eligible, excl_gate = self._communications_split_by_notification_gate(list(parents.items()))
        return {
            "ok": True, "eligible": eligible, "excluded": excl_gate + not_connected,
            "distinct_parents": len(parents), "matched_children": len(mk_ids),
            "resolved_audience_label": f"Родители из кампании «{campaign.get('name')}»",
            "diagnostics": {"campaign_name": campaign.get("name"), "not_connected_count": len(not_connected)},
        }

    def _resolve_audience_availability(self, want_filled: bool) -> dict[str, Any]:
        links = self.storage.list_active_client_parent_child_links()
        by_parent: dict[str, list[str]] = {}
        for row in links:
            by_parent.setdefault(str(row["parent_telegram_user_id"]), []).append(str(row["mk_user_id"]))
        all_mk_ids = [mk for mks in by_parent.values() for mk in mks]
        flags = self.storage.get_availability_filled_flags_for_mk_users(all_mk_ids)
        selected_pairs: list[tuple[str, Optional[str]]] = []
        for pid, mks in by_parent.items():
            any_filled = any(flags.get(mk, False) for mk in mks)
            if any_filled == want_filled:
                selected_pairs.append((pid, mks[0]))
        eligible, excluded = self._communications_split_by_notification_gate(selected_pairs)
        label = (
            "Родители, заполнившие возможности для расписания" if want_filled
            else "Родители, не заполнившие возможности для расписания"
        )
        return {
            "ok": True, "eligible": eligible, "excluded": excluded,
            "distinct_parents": len(selected_pairs),
            "matched_children": sum(len(by_parent[p]) for p, _ in selected_pairs),
            "resolved_audience_label": label,
            "diagnostics": {
                "total_active_parents": len(by_parent), "total_active_children": len(all_mk_ids),
            },
        }

    _COMMUNICATIONS_DISABLED_AUDIENCE_REASONS = {
        "branch": (
            "Сегмент «Филиал» пока недоступен: в локальных данных нет единого "
            "надёжного признака филиала для всех подключённых клиентов без "
            "дополнительных обращений к МойКласс по каждому клиенту."
        ),
        "payment_status": (
            "Сегмент «Статус оплаты» пока недоступен: массовая классификация "
            "потребовала бы либо новой независимой логики статусов оплаты, "
            "либо обращения к МойКласс по каждому клиенту — в этом релизе "
            "решили не делать ни то, ни другое."
        ),
    }

    def _resolve_audience_disabled(self, audience_type: str) -> dict[str, Any]:
        reason = self._COMMUNICATIONS_DISABLED_AUDIENCE_REASONS.get(
            audience_type, "Этот сегмент пока недоступен."
        )
        return {"ok": False, "disabled": True, "error": reason, "disabled_reason": reason}

    def _resolve_communications_audience(self, audience_type: str, audience_config: dict[str, Any]) -> dict[str, Any]:
        audience_type = str(audience_type or "")
        if audience_type == "single_client":
            return self._resolve_audience_single_client(audience_config)
        if audience_type == "all_parents":
            return self._resolve_audience_all_parents()
        if audience_type == "connection_campaign":
            return self._resolve_audience_connection_campaign(audience_config)
        if audience_type == "availability_filled":
            return self._resolve_audience_availability(True)
        if audience_type == "availability_missing":
            return self._resolve_audience_availability(False)
        if audience_type in self._COMMUNICATIONS_DISABLED_AUDIENCE_REASONS:
            return self._resolve_audience_disabled(audience_type)
        return {"ok": False, "error": "Не выбраны получатели."}

    @staticmethod
    def _communications_snapshot_hash(
        audience_type: str, audience_config: dict[str, Any], scope: str, recipient_keys: list[str],
    ) -> str:
        payload = json.dumps(
            {
                "audience_type": str(audience_type or ""),
                "audience_config": audience_config or {},
                "scope": str(scope or ""),
                "recipients": sorted(str(k) for k in recipient_keys),
            },
            sort_keys=True, ensure_ascii=False,
        )
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:24]

    @staticmethod
    def _communications_summarize_exclusions(excluded: list[dict[str, Any]]) -> list[dict[str, Any]]:
        counts: dict[str, int] = {}
        for item in excluded:
            reason = str(item.get("exclusion_reason") or "Не указана причина.")
            counts[reason] = counts.get(reason, 0) + 1
        return [{"reason": reason, "count": count} for reason, count in sorted(counts.items(), key=lambda x: -x[1])]

    def communications_campaigns_list(self, auth: dict[str, Any], params: dict[str, Any]) -> dict[str, Any]:
        """GET /api/staff/communications/campaigns?status=draft,scheduled"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        raw_status = str(params.get("status") or "").strip()
        statuses = None
        if raw_status:
            statuses = tuple(s for s in raw_status.split(",") if s in STAFF_COMMUNICATION_STATUSES)
        campaigns = self.storage.list_staff_communication_campaigns(statuses)
        return {"ok": True, "campaigns": [self._communications_campaign_public(c) for c in campaigns]}

    def communications_connection_campaigns_list(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/staff/communications/connection-campaigns — non-system
        onboarding campaigns only, for the audience picker."""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaigns = self.storage.list_onboarding_campaigns()
        return {"ok": True, "campaigns": [{"id": c["id"], "name": c.get("name")} for c in campaigns]}

    def communications_client_lookup(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/client-lookup — read-only, reuses
        the same trusted-candidate search as the owner test-client tool,
        under the communications access gate instead. Never creates,
        modifies, or unlinks anything."""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        query = str(body.get("query") or "").strip()
        if not query:
            return {"ok": False, "error": "Укажите ID ученика или Telegram ID родителя."}
        candidates = self.storage.find_trusted_client_context_candidates(query)
        return {"ok": True, "candidates": candidates}

    def communications_campaign_create(self, auth: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        actor = str(auth.get("user_id") or "")
        campaign = self.storage.create_staff_communication_draft(actor)
        return {"ok": True, "campaign": self._communications_campaign_public(campaign)}

    def communications_campaign_get(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """GET /api/staff/communications/campaigns/{id}"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        result = self._communications_campaign_public(campaign)
        result["deliveryCounts"] = self.storage.count_staff_communication_recipients_by_delivery(campaign["id"])
        return {"ok": True, "campaign": result}

    _COMMUNICATIONS_DRAFT_FIELD_MAP = {
        "name": "name", "audienceType": "audience_type", "category": "category",
        "priority": "priority", "scope": "scope", "title": "title", "body": "body",
        "actionKey": "action_key",
    }
    _COMMUNICATIONS_TITLE_MAX_LEN = 200
    _COMMUNICATIONS_BODY_MAX_LEN = 4000

    def _communications_validate_draft_fields(self, body: dict[str, Any]) -> tuple[dict[str, Any], Optional[dict[str, Any]]]:
        fields: dict[str, Any] = {}
        for js_key, col in self._COMMUNICATIONS_DRAFT_FIELD_MAP.items():
            if js_key not in body:
                continue
            value = body.get(js_key)
            if col == "title":
                value = str(value or "").strip()
                if len(value) > self._COMMUNICATIONS_TITLE_MAX_LEN:
                    return {}, {"ok": False, "error": f"Заголовок не должен превышать {self._COMMUNICATIONS_TITLE_MAX_LEN} символов."}
            elif col == "body":
                value = str(value or "").strip()
                if len(value) > self._COMMUNICATIONS_BODY_MAX_LEN:
                    return {}, {"ok": False, "error": f"Текст не должен превышать {self._COMMUNICATIONS_BODY_MAX_LEN} символов."}
            elif col == "category":
                value = str(value or "").strip()
                if value and value not in NOTIFICATION_CATEGORIES:
                    return {}, {"ok": False, "error": "Недопустимая категория."}
            elif col == "priority":
                value = str(value or "").strip()
                if value and value not in NOTIFICATION_PRIORITIES:
                    return {}, {"ok": False, "error": "Недопустимая важность."}
            elif col == "scope":
                value = str(value or "").strip()
                if value and value not in NOTIFICATION_SCOPES:
                    return {}, {"ok": False, "error": "Недопустимый охват."}
            elif col == "action_key":
                value = str(value or "").strip()
                if value and value not in NOTIFICATION_ACTION_KEYS:
                    return {}, {"ok": False, "error": "Недопустимая кнопка действия."}
            else:
                value = str(value or "").strip()
            fields[col] = value
        if "audienceConfig" in body:
            cfg = body.get("audienceConfig")
            if not isinstance(cfg, dict):
                cfg = {}
            fields["audience_config_json"] = json.dumps(cfg, ensure_ascii=False)
        return fields, None

    def communications_campaign_update(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        if campaign["status"] != "draft":
            return {"ok": False, "error": "Редактировать можно только черновик."}
        fields, err = self._communications_validate_draft_fields(body)
        if err:
            return err
        invalidate = bool({"audience_type", "audience_config_json", "scope"} & set(fields.keys()))
        actor = str(auth.get("user_id") or "")
        result = self.storage.update_staff_communication_draft(
            campaign["id"], actor, fields, invalidate_snapshot=invalidate,
        )
        if not result.get("ok"):
            return result
        return {"ok": True, "campaign": self._communications_campaign_public(result["campaign"])}

    def communications_campaign_delete(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/delete"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        return self.storage.delete_staff_communication_draft(campaign["id"])

    def communications_campaign_preview(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/preview — dry run,
        never writes recipient rows or touches the campaign's own snapshot
        fields. Frontend calls this on every Step 1 change; only "freeze"
        below actually commits a snapshot."""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        audience_type = str(body.get("audienceType") or campaign.get("audience_type") or "")
        audience_config = body.get("audienceConfig")
        if not isinstance(audience_config, dict):
            audience_config = self._safe_json_loads(campaign.get("audience_config_json"))
        calculated_at = now_iso()
        result = self._resolve_communications_audience(audience_type, audience_config)
        if not result.get("ok"):
            return {
                "ok": True, "state": "disabled" if result.get("disabled") else "error",
                "eligibleCount": 0, "excludedCount": 0, "error": result.get("error"),
                "disabled": bool(result.get("disabled")), "calculatedAt": calculated_at,
                "source": "trusted_local_db",
            }
        eligible_keys = [e["recipient_key"] for e in result["eligible"]]
        scope = str(body.get("scope") or campaign.get("scope") or "family")
        snapshot_hash = self._communications_snapshot_hash(audience_type, audience_config, scope, eligible_keys)
        state = "zero" if len(result["eligible"]) == 0 else "calculated"
        return {
            "ok": True, "state": state,
            "eligibleCount": len(result["eligible"]), "excludedCount": len(result["excluded"]),
            "exclusionReasons": self._communications_summarize_exclusions(result["excluded"]),
            "distinctParents": result.get("distinct_parents"), "matchedChildren": result.get("matched_children"),
            "calculatedAt": calculated_at, "snapshotHash": snapshot_hash,
            "diagnostics": result.get("diagnostics") or {}, "resolvedAudience": result.get("resolved_audience_label"),
            "source": "trusted_local_db", "stoppedReason": None,
        }

    def communications_campaign_freeze(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/freeze — commits
        the audience snapshot (materializes staff_communication_recipients)
        from whatever audience_type/audience_config/scope is CURRENTLY
        saved on the draft. Required before send-now/schedule."""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        if campaign["status"] != "draft":
            return {"ok": False, "error": "Снимок аудитории можно создать только для черновика."}
        if not str(campaign.get("title") or "").strip() or not str(campaign.get("body") or "").strip():
            return {"ok": False, "error": "Заполните заголовок и текст уведомления перед расчётом получателей."}
        audience_type = str(campaign.get("audience_type") or "")
        if not audience_type:
            return {"ok": False, "error": "Не выбраны получатели."}
        if str(campaign.get("scope") or "family") == "child" and audience_type != "single_client":
            return {"ok": False, "error": "Отправка конкретному ребёнку доступна только для одного клиента."}
        audience_config = self._safe_json_loads(campaign.get("audience_config_json"))
        result = self._resolve_communications_audience(audience_type, audience_config)
        if not result.get("ok"):
            return {"ok": False, "error": result.get("error") or "Не удалось рассчитать аудиторию.", "disabled": bool(result.get("disabled"))}
        eligible_keys = [e["recipient_key"] for e in result["eligible"]]
        scope = str(campaign.get("scope") or "family")
        snapshot_hash = self._communications_snapshot_hash(audience_type, audience_config, scope, eligible_keys)
        freeze_result = self.storage.freeze_staff_communication_snapshot(
            campaign["id"], snapshot_hash=snapshot_hash, eligible=result["eligible"], excluded=result["excluded"],
        )
        if not freeze_result.get("ok"):
            return freeze_result
        return {
            "ok": True, "campaign": self._communications_campaign_public(freeze_result["campaign"]),
            "eligibleCount": len(result["eligible"]), "excludedCount": len(result["excluded"]),
            "snapshotHash": snapshot_hash, "resolvedAudience": result.get("resolved_audience_label"),
        }

    def _communications_send_precheck(self, auth: dict[str, Any], campaign: dict[str, Any], body: dict[str, Any]) -> Optional[dict[str, Any]]:
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        if not self._communications_send_enabled():
            return {"ok": False, "error_code": "send_disabled", "error": "Отправка отключена безопасным режимом."}
        if not campaign.get("audience_snapshot_hash"):
            return {"ok": False, "error_code": "stale_snapshot", "error": "Сначала рассчитайте получателей."}
        if str(body.get("snapshot_hash") or body.get("snapshotHash") or "") != campaign.get("audience_snapshot_hash"):
            return {"ok": False, "error_code": "stale_snapshot", "error": "Аудитория изменилась — пересчитайте получателей."}
        try:
            provided_count = int(body.get("recipient_count", body.get("recipientCount")))
        except (TypeError, ValueError):
            return {"ok": False, "error_code": "count_mismatch", "error": "Не указано количество получателей для подтверждения."}
        if provided_count != int(campaign.get("eligible_count") or 0):
            return {"ok": False, "error_code": "count_mismatch", "error": "Количество получателей изменилось — пересчитайте."}
        if not bool(body.get("confirm")):
            return {"ok": False, "error_code": "confirm_required", "error": "Требуется подтверждение."}
        return None

    def _communications_execute_send(self, campaign_id: int) -> dict[str, Any]:
        """The one idempotent send step — used by send-now, and reused
        unchanged by the scheduler worker (both for the initial run and any
        crash-resume). Only ever touches recipients still delivery_status=
        'pending'; the client_notification row is created once and reused
        on every subsequent call for the same campaign."""
        campaign = self.storage.get_staff_communication_campaign(campaign_id)
        notification_id = campaign.get("client_notification_id")
        if not notification_id:
            notification_id = self.storage.create_client_notification_message(
                title=campaign["title"], body=campaign["body"], category=campaign["category"],
                priority=campaign["priority"], scope=campaign["scope"],
                mk_user_id=None,  # family-wide fan-out for every MVP audience; single-client/child-scope still fans out by parent id below
                action_key=campaign["action_key"], created_by_telegram_id=campaign["created_by_telegram_id"],
            )
            self.storage.set_staff_communication_client_notification_id(campaign_id, notification_id)
        pending = self.storage.list_staff_communication_recipients(campaign_id, delivery_status="pending")
        created = 0
        failed = 0
        for recipient in pending:
            try:
                recipient_row_id = self.storage.add_client_notification_recipient(
                    notification_id, recipient["parent_telegram_id"],
                )
                self.storage.mark_staff_communication_recipient_delivery(
                    recipient["id"], "created", client_notification_recipient_id=recipient_row_id,
                )
                created += 1
            except Exception as exc:
                log.exception("communications_send_recipient_error campaign_id=%s recipient_id=%s", campaign_id, recipient["id"])
                self.storage.mark_staff_communication_recipient_delivery(
                    recipient["id"], "failed", error_code="write_error",
                )
                failed += 1
        counts = self.storage.count_staff_communication_recipients_by_delivery(campaign_id)
        total_eligible = counts.get("pending", 0) + counts.get("created", 0) + counts.get("failed", 0)
        failed_total = counts.get("failed", 0)
        if failed_total == 0:
            final_status = "sent"
        elif counts.get("created", 0) > 0:
            final_status = "partial"
        else:
            final_status = "failed"
        self.storage.finalize_staff_communication_campaign(
            campaign_id, final_status,
            last_error=(f"{failed_total} получателей не удалось обработать" if failed_total else None),
        )
        log.info(
            "communications_campaign_send campaign_id=%s created=%d skipped=%s failed=%d status=%s",
            campaign_id, created, counts.get("skipped", 0), failed, final_status,
        )
        return {
            "campaign": self.storage.get_staff_communication_campaign(campaign_id),
            "counts": {
                "createdCount": counts.get("created", 0), "skippedCount": counts.get("skipped", 0),
                "failedCount": failed_total, "totalEligible": total_eligible,
            },
        }

    def communications_campaign_send_now(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/send"""
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        denied = self._communications_send_precheck(auth, campaign, body)
        if denied:
            return denied
        if campaign["status"] != "draft":
            return {"ok": False, "error": "Отправить можно только черновик с рассчитанными получателями."}
        claimed = self.storage.claim_staff_communication_campaign(campaign["id"], ("draft",), "sending", now_iso())
        if not claimed:
            current = self.storage.get_staff_communication_campaign(campaign["id"])
            return {"ok": True, "campaign": self._communications_campaign_public(current), "alreadyInProgress": True}
        outcome = self._communications_execute_send(campaign["id"])
        return {"ok": True, "campaign": self._communications_campaign_public(outcome["campaign"]), **outcome["counts"]}

    def communications_campaign_schedule(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/schedule"""
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        if not self._communications_scheduler_enabled():
            denied_role = self._require_communications_access(auth)
            if denied_role:
                return denied_role
            return {"ok": False, "error_code": "scheduler_disabled", "error": "Планирование отправки отключено безопасным режимом."}
        denied = self._communications_send_precheck(auth, campaign, body)
        if denied:
            return denied
        if campaign["status"] != "draft":
            return {"ok": False, "error": "Запланировать можно только черновик с рассчитанными получателями."}
        scheduled_at_utc, err = self._communications_minsk_to_utc(str(body.get("date") or ""), str(body.get("time") or ""))
        if err:
            return {"ok": False, "error": err}
        actor = str(auth.get("user_id") or "")
        self.storage.update_staff_communication_draft(
            campaign["id"], actor,
            {"schedule_mode": "scheduled", "scheduled_at_utc": scheduled_at_utc, "timezone": "Europe/Minsk"},
        )
        claimed = self.storage.claim_staff_communication_campaign(campaign["id"], ("draft",), "scheduled", now_iso())
        if not claimed:
            return {"ok": False, "error": "Не удалось запланировать — рассылка уже не в статусе черновика."}
        return {"ok": True, "campaign": self._communications_campaign_public(self.storage.get_staff_communication_campaign(campaign["id"]))}

    def communications_campaign_cancel(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/staff/communications/campaigns/{id}/cancel"""
        denied = self._require_communications_access(auth)
        if denied:
            return denied
        campaign = self._communications_load_campaign(campaign_id_str)
        if not campaign:
            return {"ok": False, "error": "Рассылка не найдена."}
        actor = str(auth.get("user_id") or "")
        result = self.storage.cancel_staff_communication_schedule(campaign["id"], actor)
        if not result.get("ok"):
            return result
        return {"ok": True, "campaign": self._communications_campaign_public(result["campaign"])}

    # ── v7.1.12 — mass client-onboarding campaigns (staff endpoints) ─────────
    # Second, parallel path alongside the point-in-time CL-code flow above —
    # never replaces it. The parent-facing token preview/confirm/activate/
    # survey flow is NOT exposed over HTTP: it runs entirely inside the bot
    # conversation (handlers.py), which already talks to the same Storage
    # instance directly (see e.g. self.storage.get_staff_test_mode elsewhere
    # in handlers.py) — adding a second, parallel HTTP auth model for a flow
    # that only ever runs inside a Telegram chat would add risk without
    # adding capability. See storage.activate_onboarding_invite /
    # get_onboarding_invite_preview / submit_continuation_response.

    def _require_onboarding_campaign_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in CLIENT_ONBOARDING_CAMPAIGN_ROLES:
            return {"ok": False, "error": "Доступно только owner, admin и client_manager."}
        return None

    # ── v7.1.16 — minimal frontend (browser/JS) incident diagnostics ──
    # Open to any authenticated session (client or staff) — errors can
    # happen to anyone, and the write itself never stores anything role- or
    # identity-sensitive beyond the coarse role tag. Viewing is restricted:
    # owner/admin get the raw recent list + aggregates, client_manager gets
    # aggregates only (no per-incident rows), matching the spec's "no
    # technical secrets" requirement — moot here since rows never held any,
    # but the split is kept anyway so this stays true if the schema grows.
    FRONTEND_INCIDENT_VIEW_ROLES = {"owner", "admin", "client_manager"}
    FRONTEND_INCIDENT_RAW_ROLES = {"owner", "admin"}

    def frontend_incident_report(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/frontend-incident"""
        role = self._role_for_user(int(auth["user_id"]))
        written = self.storage.log_frontend_incident(
            screen=str(body.get("screen") or ""),
            action=str(body.get("action") or ""),
            error_code=str(body.get("error_code") or ""),
            app_version=str(body.get("app_version") or ""),
            role=role,
        )
        # Always ok:true (fail-open, diagnostic-only) — a rejected/deduped
        # write must never surface as an error to whatever screen the user
        # was already having trouble with.
        return {"ok": True, "recorded": written}

    def frontend_incidents_summary(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/frontend-incidents/summary[?hours=24]"""
        role = self._role_for_user(int(auth["user_id"]))
        if role not in self.FRONTEND_INCIDENT_VIEW_ROLES:
            return {"ok": False, "error": "Доступно только owner, admin и client_manager."}
        try:
            hours = int(params.get("hours") or 24)
        except (TypeError, ValueError):
            hours = 24
        result: dict[str, Any] = {"ok": True, "summary": self.storage.get_frontend_incident_summary(hours=hours)}
        if role in self.FRONTEND_INCIDENT_RAW_ROLES:
            result["recent"] = self.storage.list_frontend_incidents(limit=30)
        return result

    # ── v7.1.15 — launch-readiness "Подключения" (Connections) diagnostics ──
    # Same role gate as onboarding campaigns (owner/admin/client_manager) —
    # deliberately placed right next to it since this dashboard is reached
    # from that same screen. Read-only: no mutation endpoints here.
    def onboarding_connections_summary(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/connections/summary[?campaign_id=N]"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        campaign_id: Optional[int] = None
        raw_campaign_id = str(params.get("campaign_id") or "").strip()
        if raw_campaign_id:
            try:
                campaign_id = int(raw_campaign_id)
            except (TypeError, ValueError):
                return {"ok": False, "error": "invalid campaign_id"}
            if not self.storage.get_onboarding_campaign(campaign_id):
                return {"ok": False, "error": "Кампания не найдена"}
        summary = self.storage.get_onboarding_connections_summary(campaign_id)
        # Food-only is reported separately and only for the "all campaigns"
        # view — it has no per-campaign concept in this dashboard.
        food = self.storage.get_food_onboarding_summary() if campaign_id is None else None
        return {"ok": True, "summary": summary, "food": food, "campaignId": campaign_id}

    def onboarding_connections_errors(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/connections/errors[?limit=20&source_type=cl_code]"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        try:
            limit = int(params.get("limit") or 20)
        except (TypeError, ValueError):
            limit = 20
        source_type = str(params.get("source_type") or "").strip() or None
        errors = self.storage.list_recent_onboarding_connection_errors(limit=limit, source_type=source_type)
        return {"ok": True, "errors": errors}

    def onboarding_launch_health(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/client/onboarding/health — compact status per area, built
        only from local, cheap signals (feature flags, last event timestamps,
        pending/failed counts) — never an external MoyKlass call."""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        return {"ok": True, "health": self.storage.get_launch_health_snapshot(self.settings)}

    def onboarding_campaigns_list(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/campaigns"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        status = str(params.get("status") or "").strip() or None
        return {"ok": True, "campaigns": self.storage.list_onboarding_campaigns(status)}

    def onboarding_campaign_create(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        result = self.storage.create_onboarding_campaign(
            name=str(body.get("name") or ""),
            academic_year=str(body.get("academic_year") or ""),
            created_by=actor,
            invite_ttl_days=body.get("invite_ttl_days"),
            default_payment_mode=str(body.get("default_payment_mode") or "review"),
            auto_enroll_payments=bool(body.get("auto_enroll_payments", True)),
            survey_enabled=bool(body.get("survey_enabled", False)),
            collect_schedule_availability=bool(body.get("collect_schedule_availability", False)),
            note=str(body.get("note") or ""),
            idempotency_key=body.get("idempotency_key"),
        )
        if result.get("ok") and result.get("created"):
            self.storage.log_onboarding_audit_event(
                event_type="onboarding_campaign_created", campaign_id=result["campaign"]["id"],
                actor_telegram_user_id=actor, actor_role=role, result="success",
            )
        return result

    def onboarding_campaign_get(self, auth: dict[str, Any], campaign_id_str: str, params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/campaigns/{id}"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        campaign = self.storage.get_onboarding_campaign(campaign_id)
        if not campaign:
            return {"ok": False, "error": "Кампания не найдена"}
        filters: dict[str, Any] = {}
        for key in ("branch_name", "course_name", "continuation_status", "invite_status"):
            if params.get(key):
                filters[key] = params[key]
        for key in ("academic_level", "preferred_branch"):
            if params.get(key):
                filters[key] = params[key]
        if params.get("telegram_connected") in ("true", "false"):
            filters["telegram_connected"] = params["telegram_connected"] == "true"
        if params.get("in_pilot") in ("true", "false"):
            filters["in_pilot"] = params["in_pilot"] == "true"
        if params.get("availability_filled") in ("true", "false"):
            filters["availability_filled"] = params["availability_filled"] == "true"
        if params.get("weekday"):
            try:
                filters["weekday"] = int(params["weekday"])
            except (TypeError, ValueError):
                pass
        recipients = self.storage.list_onboarding_campaign_recipients(campaign_id, filters)
        secret = self._onboarding_signing_secret()
        for rec in recipients:
            rec["invite_link"] = self._onboarding_invite_link_for(rec.get("invite_id"), secret)
        return {
            "ok": True, "campaign": campaign,
            "stats": self.storage.get_onboarding_campaign_stats(campaign_id),
            "availability_summary": self.storage.get_onboarding_campaign_availability_summary(campaign_id),
            "recipients": recipients,
        }

    # v7.1.12.3 hotfix — shared guard for every staff-facing mutation that
    # targets a campaign by id: the internal standalone availability
    # container (is_system=1) is never a valid target, regardless of how
    # staff obtained its id (it's hidden from the list, but the id could
    # still leak via a recipient's campaign_id in an export or old link).
    def _require_not_system_campaign(self, campaign: dict[str, Any]) -> Optional[dict[str, Any]]:
        if campaign and campaign.get("is_system"):
            return {"ok": False, "error": "Это служебная кампания, управлять ею через интерфейс кампаний нельзя.", "reason_code": "system_campaign"}
        return None

    def _onboarding_campaign_transition(
        self, auth: dict[str, Any], campaign_id_str: str, transition_fn: Any, event_type: str
    ) -> dict[str, Any]:
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        sys_denied = self._require_not_system_campaign(self.storage.get_onboarding_campaign(campaign_id))
        if sys_denied:
            return sys_denied
        result = transition_fn(campaign_id, actor)
        if result.get("ok"):
            self.storage.log_onboarding_audit_event(
                event_type=event_type, campaign_id=campaign_id,
                actor_telegram_user_id=actor, actor_role=role, result="success",
            )
        return result

    def onboarding_campaign_start(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/start"""
        return self._onboarding_campaign_transition(
            auth, campaign_id_str, self.storage.start_onboarding_campaign, "onboarding_campaign_started"
        )

    def onboarding_campaign_close(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/close"""
        return self._onboarding_campaign_transition(
            auth, campaign_id_str, self.storage.close_onboarding_campaign, "onboarding_campaign_closed"
        )

    def onboarding_campaign_archive(self, auth: dict[str, Any], campaign_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/archive"""
        return self._onboarding_campaign_transition(
            auth, campaign_id_str, self.storage.archive_onboarding_campaign, "onboarding_campaign_archived"
        )

    def onboarding_campaign_search_candidates(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/candidates?q=...

        Reuses the exact same MoyKlass search call as admin_client_search_students
        (no new MoyKlass endpoint invented) so staff can pick real candidates to
        import into a campaign. Enriched with existing pilot mode + Telegram-link
        status (read-only, existing storage helpers). branch_name is best-effort
        only (opportunistically read off whatever the raw MoyKlass object
        contains — tenant configs vary) and course_name is left blank here
        (would need a per-student extra MK call); neither ever blocks import.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        q = str(params.get("q") or "").strip()
        if not q:
            return {"ok": False, "error": "Введите имя ученика или userId МойКласс"}
        if len(q) > 200:
            return {"ok": False, "error": "Запрос слишком длинный"}

        mk_results: list[dict] = []
        if q.isdigit():
            try:
                res = self.moyklass.request("GET", f"/v1/company/users/{q}")
                if res.ok:
                    u = res.data if isinstance(res.data, dict) else {}
                    if u.get("id"):
                        mk_results = [u]
                    elif isinstance(res.data, list) and res.data:
                        mk_results = res.data[:10]
            except Exception:
                pass
        else:
            try:
                res = self.moyklass.request("GET", "/v1/company/users", params={"q": q, "limit": "30"})
                if res.ok:
                    raw = res.data
                    if isinstance(raw, list):
                        mk_results = raw[:30]
                    elif isinstance(raw, dict) and isinstance(raw.get("items"), list):
                        mk_results = raw["items"][:30]
            except Exception:
                pass

        candidates = [self._onboarding_mk_user_to_candidate(u) for u in mk_results]
        candidates = [c for c in candidates if c is not None]
        self._onboarding_cache_candidates(candidates)
        return {"ok": True, "candidates": candidates, "query": q}

    # v7.1.12.1 hotfix — how long a candidate stays trusted as "server-verified"
    # after either search or the bulk loader last returned it. Generous enough
    # to cover a full staff review-then-select-all-then-confirm workflow for
    # 1700+ candidates without forcing a reload, short enough that it's never
    # mistaken for a live guarantee.
    _ONBOARDING_CANDIDATES_CACHE_TTL_SECONDS = 3600

    def _onboarding_candidates_cache_dict(self) -> dict[str, tuple[float, dict[str, Any]]]:
        """Lazily creates the cache dict if missing.

        Tests across this project construct MiniAppContext via
        object.__new__(MiniAppContext), bypassing __init__ (an established
        pattern predating this hotfix — see test_onboarding_campaigns_v7112,
        test_onboarding_campaign_v71121, test_onboarding_mass_scale_v7112).
        Reading self._onboarding_candidates_cache directly would raise
        AttributeError on any such instance; this keeps every existing
        fixture working unchanged instead of requiring every test file to
        be touched just to add one more cache attribute.
        """
        cache = getattr(self, "_onboarding_candidates_cache", None)
        if cache is None:
            cache = {}
            self._onboarding_candidates_cache = cache
        return cache

    def _onboarding_cache_candidates(self, candidates: list[dict[str, Any]]) -> None:
        """Record candidates returned by search/bulk-fetch as server-verified.

        onboarding_campaign_import_recipients cross-checks every submitted
        mk_user_id against this cache and always re-reads name/branch/course
        from here — frontend-supplied copies of those fields are never
        trusted, only the mk_user_id selection itself is.
        """
        cache = self._onboarding_candidates_cache_dict()
        now = time.time()
        for c in candidates:
            mk_user_id = str(c.get("mk_user_id") or "").strip()
            if mk_user_id:
                cache[mk_user_id] = (now, c)

    def _onboarding_verified_candidate(self, mk_user_id: str) -> Optional[dict[str, Any]]:
        entry = self._onboarding_candidates_cache_dict().get(mk_user_id)
        if not entry:
            return None
        fetched_at, candidate = entry
        if (time.time() - fetched_at) > self._ONBOARDING_CANDIDATES_CACHE_TTL_SECONDS:
            return None
        return candidate

    def _onboarding_mk_user_to_candidate(self, u: dict[str, Any]) -> Optional[dict[str, Any]]:
        """Shared MoyKlass-raw-user -> campaign-candidate mapping, used by
        both the query search (onboarding_campaign_search_candidates) and
        the bulk pagination fetch (onboarding_campaign_bulk_candidates) so
        the two paths can never silently drift apart in shape."""
        mk_user_id = str(u.get("id") or u.get("userId") or u.get("mk_user_id") or "").strip()
        if not mk_user_id:
            return None
        first = str(u.get("name") or u.get("firstName") or "").strip()
        last = str(u.get("lastName") or "").strip()
        full_name = f"{first} {last}".strip() if last else first
        filial = u.get("filial")
        branch_name = str(filial.get("name") if isinstance(filial, dict) else (u.get("filialName") or u.get("branch") or "")).strip()
        pilot = self.storage.get_pilot_client(mk_user_id)
        link_status = self.storage.get_client_link_status_for_student(mk_user_id)
        active_link = next((l for l in (link_status.get("links") or []) if l.get("status") == "active"), None)
        return {
            "mk_user_id": mk_user_id,
            "child_display_name": full_name or f"Ученик #{mk_user_id}",
            "branch_name": branch_name,
            "course_name": "",
            "telegram_connected": bool(active_link),
            "pilot_mode": pilot.get("mode") if pilot else None,
        }

    _ONBOARDING_BULK_CANDIDATES_MAX_PAGES = 30
    _ONBOARDING_BULK_CANDIDATES_PAGE_SIZE = 200

    def onboarding_campaign_bulk_candidates(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/candidates/bulk

        Loads ALL MoyKlass students (not just a search-limited page) via
        MoyKlassClient.list_users_bulk — the actual fix for "300+ clients":
        onboarding_campaign_search_candidates above is a name/id SEARCH
        capped at ~30 results and is not a substitute for this. One backend
        call does the full pagination server-side; the frontend never issues
        one HTTP request per page or per candidate. Only ever RETURNS
        candidates — nothing here creates a recipient row; staff must still
        explicitly select and call recipients/import.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        mk_params: dict[str, Any] = {}
        # Optional passthrough filter (e.g. a MoyKlass filial/branch id) —
        # never required; an empty call fetches the full student list.
        if params.get("filialId"):
            mk_params["filialId"] = params["filialId"]
        result = self.moyklass.list_users_bulk(
            params=mk_params or None,
            page_size=self._ONBOARDING_BULK_CANDIDATES_PAGE_SIZE,
            max_pages=self._ONBOARDING_BULK_CANDIDATES_MAX_PAGES,
        )
        diagnostics = (result.data or {}).get("diagnostics", {}) if isinstance(result.data, dict) else {}
        raw_items = (result.data or {}).get("items", []) if isinstance(result.data, dict) else []
        candidates = [c for c in (self._onboarding_mk_user_to_candidate(u) for u in raw_items) if c is not None]
        self._onboarding_cache_candidates(candidates)
        return {
            "ok": bool(result.ok),
            "candidates": candidates,
            "diagnostics": diagnostics,
            "error": result.error if not result.ok else None,
        }

    # ── v7.1.13 research — "students from schedule period" candidate source ──
    # Live audit against the real MoyKlass account (2025-09-01..today, 334
    # days) confirmed: lesson.status is reliably 0 (not held) or 1 (held) —
    # no cancelled (status="3") lesson was ever observed in this account's
    # real data; lessonRecord.skip (enrollment-level cancel flag) was 0/12599
    # true — never observed true either. Both filters are still implemented
    # (defensive, correct, and forward-compatible if either value ever
    # appears), but neither is validated against a real positive example —
    # honestly documented rather than claimed proven. lessonRecord.visit
    # (attendance) DID show real variance (10408 true / 2191 false) and is
    # treated as reliable.
    _MK_CANCELLED_LESSON_STATUSES = ("3", "cancelled", "отменено", "canceled")
    _ONBOARDING_SCHEDULE_MAX_PERIOD_DAYS = 400
    _ONBOARDING_SCHEDULE_MIN_LESSONS_ALLOWED = (1, 2, 4, 8)
    _ONBOARDING_SCHEDULE_RECORDS_LIMIT = 100000
    _ONBOARDING_SCHEDULE_LESSONS_LIMIT = 60000
    _ONBOARDING_SCHEDULE_CACHE_TTL_SECONDS = 600

    def _onboarding_schedule_cache_dict(self) -> dict[tuple[Any, ...], tuple[float, dict[str, Any]]]:
        """Lazily creates the cache dict if missing — same rationale as
        _onboarding_candidates_cache_dict: tests across this project build
        MiniAppContext via object.__new__(), bypassing __init__."""
        cache = getattr(self, "_onboarding_schedule_cache", None)
        if cache is None:
            cache = {}
            self._onboarding_schedule_cache = cache
        return cache

    def _onboarding_list_students_from_schedule(
        self, date_from: date, date_to: date, minimum_lessons: int, attended_only: bool,
        exclude_cancelled_classes: bool, exclude_cancelled_enrollments: bool,
    ) -> dict[str, Any]:
        """Read-only aggregation over MoyKlass lessons + lessonRecords for a
        date range — never creates, imports, or touches any recipient/
        invitation/pilot/payment record. Two live MoyKlass calls total
        (get_lessons_between + list_lesson_records_between), each already
        paginating server-side internally — never one request per lesson or
        per student. Short-lived cache keyed by every input parameter, kept
        in a dict separate from the "all clients" candidates cache.
        """
        cache_key = (date_from.isoformat(), date_to.isoformat(), int(minimum_lessons),
                     bool(attended_only), bool(exclude_cancelled_classes), bool(exclude_cancelled_enrollments))
        cache = self._onboarding_schedule_cache_dict()
        cached = cache.get(cache_key)
        if cached and (time.time() - cached[0]) <= self._ONBOARDING_SCHEDULE_CACHE_TTL_SECONDS:
            return cached[1]

        lessons_result = self.moyklass.get_lessons_between(
            date_from.isoformat(), date_to.isoformat(), limit=self._ONBOARDING_SCHEDULE_LESSONS_LIMIT,
        )
        lesson_items = [x for x in extract_items(lessons_result.data) if isinstance(x, dict)] if lessons_result.ok else []
        cancelled_lessons = sum(1 for it in lesson_items if str(it.get("status")) in self._MK_CANCELLED_LESSON_STATUSES)

        records_result = self.moyklass.list_lesson_records_between(
            date_from, date_to, limit=self._ONBOARDING_SCHEDULE_RECORDS_LIMIT,
        )
        records = (records_result.data or {}).get("lessonRecords", []) if isinstance(records_result.data, dict) else []

        no_user_id = 0
        cancelled_enrollments = 0
        cancelled_class_records = 0
        by_user_count: dict[str, int] = {}
        by_user_attended: dict[str, int] = {}
        for r in records:
            if not isinstance(r, dict):
                continue
            uid = r.get("userId") or r.get("studentId") or r.get("clientId") or r.get("idUser")
            if not uid:
                no_user_id += 1
                continue
            uid = str(uid)
            skip = bool(r.get("skip"))
            if skip:
                cancelled_enrollments += 1
            lesson = r.get("lesson") if isinstance(r.get("lesson"), dict) else {}
            lesson_status = str(lesson.get("status")) if lesson else str(r.get("lessonStatus"))
            lesson_cancelled = lesson_status in self._MK_CANCELLED_LESSON_STATUSES
            if lesson_cancelled:
                cancelled_class_records += 1
            if (exclude_cancelled_enrollments and skip) or (exclude_cancelled_classes and lesson_cancelled):
                continue
            by_user_count[uid] = by_user_count.get(uid, 0) + 1
            visit = r.get("visit")
            visited = visit is True or str(visit).lower() in ("1", "true", "yes", "y", "да")
            if visited:
                by_user_attended[uid] = by_user_attended.get(uid, 0) + 1

        source_counts = by_user_attended if attended_only else by_user_count
        threshold = max(1, int(minimum_lessons))
        eligible_ids = [uid for uid, c in source_counts.items() if c >= threshold]

        distribution = {"1": 0, "2-3": 0, "4-7": 0, "8-15": 0, "16+": 0}
        for c in by_user_count.values():
            bucket = "1" if c == 1 else "2-3" if c <= 3 else "4-7" if c <= 7 else "8-15" if c <= 15 else "16+"
            distribution[bucket] += 1

        result = {
            "ok": bool(lessons_result.ok) and bool(records_result.ok),
            "mk_user_ids": eligible_ids,
            "diagnostics": {
                "lessons_found": len(lesson_items),
                "cancelled_lessons": cancelled_lessons,
                "lesson_records_found": len(records),
                "cancelled_class_records": cancelled_class_records,
                "cancelled_enrollments": cancelled_enrollments,
                "records_without_mk_user_id": no_user_id,
                "unique_students_any_record": len(by_user_count),
                "unique_students_attended": len(by_user_attended),
                "unique_students_2plus": sum(1 for c in by_user_count.values() if c >= 2),
                "unique_students_4plus": sum(1 for c in by_user_count.values() if c >= 4),
                "unique_students_8plus": sum(1 for c in by_user_count.values() if c >= 8),
                "unique_students_eligible": len(eligible_ids),
                "distribution": distribution,
                "lessons_error": lessons_result.error if not lessons_result.ok else None,
                "records_error": records_result.error if not records_result.ok else None,
            },
        }
        cache[cache_key] = (time.time(), result)
        return result

    def onboarding_campaign_candidates_from_schedule(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/client/onboarding/candidates/from-schedule

        Read-only candidate discovery: which real MoyKlass students had
        enough non-cancelled schedule activity in [date_from, date_to] to be
        worth inviting into a new onboarding campaign. Never creates a
        recipient, invite, pilot record, or payment intent — only ever
        RETURNS candidates in the exact same shape onboarding_campaign_
        bulk_candidates returns, so the existing selection UI (manual
        checkbox, "Выбрать всех загруженных — N", "Снять выбор", single
        import request) works unchanged.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        date_from_str = str(params.get("date_from") or "").strip()
        date_to_str = str(params.get("date_to") or "").strip()
        try:
            date_from = date.fromisoformat(date_from_str)
            date_to = date.fromisoformat(date_to_str)
        except ValueError:
            return {"ok": False, "error": "Некорректный формат даты (ожидается YYYY-MM-DD)"}
        if date_from > date_to:
            return {"ok": False, "error": "Дата начала не может быть позже даты окончания"}
        if (date_to - date_from).days > self._ONBOARDING_SCHEDULE_MAX_PERIOD_DAYS:
            return {"ok": False, "error": f"Период не может превышать {self._ONBOARDING_SCHEDULE_MAX_PERIOD_DAYS} дней"}
        try:
            minimum_lessons = int(params.get("minimum_lessons") or 1)
        except (TypeError, ValueError):
            return {"ok": False, "error": "Некорректное значение minimum_lessons"}
        if minimum_lessons not in self._ONBOARDING_SCHEDULE_MIN_LESSONS_ALLOWED:
            return {"ok": False, "error": f"minimum_lessons должен быть одним из {self._ONBOARDING_SCHEDULE_MIN_LESSONS_ALLOWED}"}
        attended_only = str(params.get("attended_only") or "").strip().lower() in ("1", "true", "yes")
        exclude_cancelled_classes = str(params.get("exclude_cancelled_classes", "true")).strip().lower() not in ("0", "false", "no")
        exclude_cancelled_enrollments = str(params.get("exclude_cancelled_enrollments", "true")).strip().lower() not in ("0", "false", "no")

        schedule = self._onboarding_list_students_from_schedule(
            date_from, date_to, minimum_lessons, attended_only, exclude_cancelled_classes, exclude_cancelled_enrollments,
        )
        if not schedule["mk_user_ids"] and not schedule["ok"]:
            return {
                "ok": False,
                "error": "МойКласс временно недоступен, не удалось загрузить расписание за период",
                "diagnostics": schedule["diagnostics"],
            }

        # Names/branch resolved via the SAME bulk-candidates path used by the
        # "all clients" source — one extra call, never a second parallel
        # source of truth for display data, and it warms the same
        # verification cache the import endpoint relies on.
        bulk = self.onboarding_campaign_bulk_candidates(auth, {})
        by_id = {c["mk_user_id"]: c for c in (bulk.get("candidates") or [])}
        candidates = [by_id[mk] for mk in schedule["mk_user_ids"] if mk in by_id]
        missing = len(schedule["mk_user_ids"]) - len(candidates)

        diagnostics = dict(schedule["diagnostics"])
        diagnostics["missing_from_bulk_users"] = missing
        return {
            "ok": bool(schedule["ok"]) and bool(bulk.get("ok")),
            "candidates": candidates,
            "diagnostics": diagnostics,
            "error": None if schedule["ok"] else "Частичные данные — МойКласс вернул ошибку на части запроса",
        }

    def _onboarding_resolve_verified_candidates(
        self, mk_user_ids: list[str]
    ) -> tuple[dict[str, dict[str, Any]], Optional[str]]:
        """Resolve mk_user_ids to server-verified candidate data ONLY.

        v7.1.12.1 hotfix #2 — closes a trust-boundary gap: the frontend is
        never trusted for child_display_name/branch_name/course_name/
        academic_level/parent_display_name/MoyKlass status/anything else.
        Only mk_user_id is ever taken from a request; every other field a
        client sends is a hint, never a source of truth. Resolution order:
          1. the search/bulk-fetch cache (this session, still fresh)
          2. an existing trusted client_parent_child_links record (a
             previously-verified real client, independent of this request)
          3. ONE live MoyKlass bulk fetch covering every id still
             unresolved after (1)+(2) — never one MoyKlass call per
             candidate, so this stays cheap even for 1753 ids, and this is
             exactly what makes verification work again after a server
             restart wiped the in-memory cache without forcing staff to
             re-click "Загрузить всех учеников".
        Returns (verified_by_id, moyklass_error) — moyklass_error is set
        only if step 3 ran and MoyKlass itself failed (used by the caller to
        decide whether to fail closed instead of silently under-importing).
        """
        verified: dict[str, dict[str, Any]] = {}
        unresolved: list[str] = []
        for mk_user_id in mk_user_ids:
            cached = self._onboarding_verified_candidate(mk_user_id)
            if cached is not None:
                verified[mk_user_id] = cached
            else:
                unresolved.append(mk_user_id)

        still_unresolved: list[str] = []
        for mk_user_id in unresolved:
            local = self.storage.get_trusted_local_client_candidate(mk_user_id)
            if local is not None:
                verified[mk_user_id] = local
            else:
                still_unresolved.append(mk_user_id)

        moyklass_error: Optional[str] = None
        if still_unresolved:
            # Any failure talking to MoyKlass (bad response, timeout,
            # network exception) is treated as unavailability, never left to
            # crash the request — see the fail-closed handling in the caller.
            try:
                result = self.moyklass.list_users_bulk(
                    page_size=self._ONBOARDING_BULK_CANDIDATES_PAGE_SIZE,
                    max_pages=self._ONBOARDING_BULK_CANDIDATES_MAX_PAGES,
                )
            except Exception as exc:
                result = None
                moyklass_error = str(exc) or "МойКласс недоступен"
            if result is not None:
                raw_items = (result.data or {}).get("items", []) if isinstance(result.data, dict) else []
                fetched = [c for c in (self._onboarding_mk_user_to_candidate(u) for u in raw_items) if c is not None]
                # Warms the cache too — the next import (or a staff member
                # opening "Добавить получателей" right after) benefits from
                # this same fetch instead of triggering another one.
                self._onboarding_cache_candidates(fetched)
                by_id = {c["mk_user_id"]: c for c in fetched}
                for mk_user_id in still_unresolved:
                    found = by_id.get(mk_user_id)
                    if found is not None:
                        verified[mk_user_id] = found
            if result is not None and not result.ok:
                moyklass_error = result.error or "МойКласс недоступен"
        return verified, moyklass_error

    def onboarding_campaign_import_recipients(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/recipients/import

        Only ever imports the explicit list of mk_user_ids the staff member
        selected client-side — never the whole MoyKlass database. Idempotent
        per (campaign_id, mk_user_id). Never creates a pilot record (pilot
        creation only ever happens at invite activation time). One request
        handles the whole selection regardless of size (v7.1.12.1 raised the
        cap from 500 to ONBOARDING_IMPORT_MAX_BATCH_SIZE=2500 after production
        hit exactly the old cap trying to add all 1753 bulk-loaded students).

        v7.1.12.1 hotfix #2 — the request body is trusted for exactly one
        field: mk_user_id. Every other field a client sends (name, branch,
        course, academic level, parent name, ...) is discarded outright; see
        _onboarding_resolve_verified_candidates for where the real data comes
        from instead. An id that can't be verified by any trusted source is
        never imported — it's reported per-item as candidate_not_verified
        under "errors", and "failed" in the response reflects it, so the
        response is never a false "fully successful" for a partial import.
        If NOTHING could be verified and MoyKlass itself was unreachable,
        the whole request fails closed (ok=False) rather than silently
        importing zero real recipients while looking like a normal call.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        raw_recipients = body.get("recipients")
        if not isinstance(raw_recipients, list) or not raw_recipients:
            return {"ok": False, "error": "Список получателей пуст"}
        if len(raw_recipients) > ONBOARDING_IMPORT_MAX_BATCH_SIZE:
            return {"ok": False, "error": f"Слишком много получателей за один раз (максимум {ONBOARDING_IMPORT_MAX_BATCH_SIZE})"}

        requested_ids: list[str] = []
        seen_ids: set[str] = set()
        for r in raw_recipients:
            if not isinstance(r, dict):
                continue
            mk_user_id = str(r.get("mk_user_id") or "").strip()
            if not mk_user_id or mk_user_id in seen_ids:
                continue
            seen_ids.add(mk_user_id)
            requested_ids.append(mk_user_id)
        if not requested_ids:
            return {"ok": False, "error": "Список получателей пуст"}

        # Fail fast on campaign state before doing any verification work —
        # storage.import_onboarding_campaign_recipients enforces this same
        # rule too, but checking here avoids a wasted MoyKlass round-trip
        # for a request that was always going to be rejected anyway.
        campaign = self.storage.get_onboarding_campaign(campaign_id)
        if not campaign:
            return {"ok": False, "error": "Кампания не найдена"}
        sys_denied = self._require_not_system_campaign(campaign)
        if sys_denied:
            return sys_denied
        if campaign["status"] not in ("draft", "active"):
            return {"ok": False, "error": "Получателей можно добавлять только в кампанию в статусе draft или active", "reason_code": "invalid_campaign_status"}

        # Already a recipient of THIS campaign: the insert below is a no-op
        # regardless of name data, so this id never needs verification (and
        # never risks a candidate_not_verified false-positive just because
        # its cache entry expired since it was first added).
        existing_ids = self.storage.get_onboarding_campaign_recipient_mk_ids(campaign_id)
        to_verify = [mk for mk in requested_ids if mk not in existing_ids]

        verified: dict[str, dict[str, Any]] = {}
        moyklass_error: Optional[str] = None
        if to_verify:
            verified, moyklass_error = self._onboarding_resolve_verified_candidates(to_verify)

        unverified_ids = [mk for mk in to_verify if mk not in verified]

        # Fail closed: nothing at all could be verified (no cache, no local
        # trusted record, and the live MoyKlass check itself failed) — never
        # fall back to importing frontend-only data.
        if to_verify and not verified and moyklass_error:
            return {
                "ok": False,
                "error": "МойКласс временно недоступен, не удалось проверить получателей. Попробуйте позже.",
                "reason_code": "moyklass_unavailable",
            }

        clean: list[dict[str, Any]] = []
        for mk_user_id in requested_ids:
            if mk_user_id in existing_ids:
                clean.append({"mk_user_id": mk_user_id, "child_display_name": "", "branch_name": "", "course_name": "", "parent_display_name": ""})
            elif mk_user_id in verified:
                v = verified[mk_user_id]
                clean.append({
                    "mk_user_id": mk_user_id,
                    "child_display_name": str(v.get("child_display_name") or "")[:200],
                    "branch_name": str(v.get("branch_name") or "")[:100],
                    "course_name": str(v.get("course_name") or "")[:100],
                    "parent_display_name": "",
                })
        errors = [{"mk_user_id": mk, "error_code": "candidate_not_verified"} for mk in unverified_ids]

        # clean may legitimately be empty here (every id was either genuinely
        # unverifiable or, in the moyklass_error+partial-verified case below,
        # simply not resolved) — import_onboarding_campaign_recipients treats
        # an empty list as a no-op (added=0), matching this codebase's
        # existing batch-endpoint convention (see create_onboarding_invites_
        # batch) of returning ok=true with per-item failures reported via
        # counts, rather than failing the whole request over partial misses.
        result = self.storage.import_onboarding_campaign_recipients(campaign_id, clean, actor)
        if result.get("ok"):
            result["failed"] = len(errors)
            result["errors"] = errors
            self.storage.log_onboarding_audit_event(
                event_type="onboarding_recipient_added", campaign_id=campaign_id,
                actor_telegram_user_id=actor, actor_role=role, result="success",
                note=f"added={result.get('added')} already_present={result.get('already_present')} failed={len(errors)}",
            )
        return result

    def onboarding_campaign_continuation_status(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/continuation-status

        Accepts either a single recipient_id or a recipient_ids array (bulk).
        Every recipient_id's campaign ownership is re-verified server-side —
        the frontend's campaign_id in the URL is never trusted as proof a
        recipient belongs to it.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        new_status = str(body.get("status") or "").strip()
        comment = body.get("comment")

        recipient_ids_raw = body.get("recipient_ids")
        if isinstance(recipient_ids_raw, list) and recipient_ids_raw:
            try:
                recipient_ids = [int(x) for x in recipient_ids_raw]
            except (TypeError, ValueError):
                return {"ok": False, "error": "Некорректный список получателей"}
            owned = []
            for rid in recipient_ids:
                rec = self.storage.get_onboarding_recipient(rid)
                if rec and rec["campaign_id"] == campaign_id:
                    owned.append(rid)
            if not owned:
                return {"ok": False, "error": "Получатели не найдены в этой кампании"}
            return self.storage.bulk_update_continuation_status(owned, new_status, actor, role, comment=comment)

        try:
            recipient_id = int(body.get("recipient_id"))
        except (TypeError, ValueError):
            return {"ok": False, "error": "recipient_id или recipient_ids обязателен"}
        rec = self.storage.get_onboarding_recipient(recipient_id)
        if not rec or rec["campaign_id"] != campaign_id:
            return {"ok": False, "error": "Получатель не найден в этой кампании"}
        return self.storage.update_recipient_continuation_status(recipient_id, new_status, actor, role, comment=comment, source="staff")

    def onboarding_recipient_academic_level(self, auth: dict[str, Any], recipient_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/recipients/{id}/academic-level — staff-only
        manual override. Always wins over auto-detection and survives any
        later re-import (see update_recipient_academic_level's docstring)."""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            recipient_id = int(recipient_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid recipient id"}
        new_level = str(body.get("academic_level") or "").strip()
        return self.storage.update_recipient_academic_level(recipient_id, new_level, actor, role, comment=body.get("comment"))

    # ── v7.1.12.1 — schedule availability ────────────────────────────────────
    # Dual authorization: staff (CLIENT_ONBOARDING_CAMPAIGN_ROLES, any
    # recipient in a campaign they can already see) or the parent who owns
    # the specific child (role == "parent" AND the recipient's mk_user_id is
    # among that parent's actively-linked children — never trusted from the
    # client, always re-derived from client_parent_child_links here).

    # v7.1.13 addendum — a food-only client must never see tuition-payment
    # or permanent-schedule notifications (even family-scope ones) unless
    # they are also a regular/combined client. client_kind is always
    # recomputed server-side (storage.get_client_kind_for_parent), never
    # taken from the frontend.
    def _notification_allowed_categories(self, client_kind: str) -> Optional[tuple[str, ...]]:
        if client_kind == "food_only":
            return NOTIFICATION_CATEGORIES_FOOD_ONLY
        return None

    def _require_availability_access(self, auth: dict[str, Any], mk_user_id: Any) -> tuple[Optional[str], Optional[dict[str, Any]]]:
        """v7.1.12.3 — keyed directly on mk_user_id rather than a recipient
        dict (pure refactor, identical behavior to the pre-v7.1.12.3 version
        which just read recipient.get("mk_user_id") internally) so the new
        permanent, non-campaign entry point (client_schedule_availability_*)
        can reuse the exact same ownership check without needing a
        client_onboarding_recipients row to exist first."""
        role = self._role_for_user(int(auth["user_id"]))
        if role == "parent":
            parent_tid = self._effective_client_identity(auth)
            children = self.storage.list_client_children_for_parent(parent_tid)
            if not any(str(c.get("mk_user_id")) == str(mk_user_id) for c in children):
                return None, {"ok": False, "error": "Доступ только к своим детям."}
            # v7.1.13.1 — distinct source so a save made by the owner
            # previewing a client's cabinet is never indistinguishable in
            # storage/audit data from a submission the real parent made.
            return ("owner_test" if self._owner_test_client_mode_active(auth) else "parent_app"), None
        if role in CLIENT_ONBOARDING_CAMPAIGN_ROLES:
            return "staff", None
        return None, {"ok": False, "error": "Доступ запрещён."}

    def onboarding_recipient_availability_get(self, auth: dict[str, Any], recipient_id_str: str) -> dict[str, Any]:
        """GET /api/client/onboarding/recipients/{id}/availability"""
        try:
            recipient_id = int(recipient_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid recipient id"}
        recipient = self.storage.get_onboarding_recipient(recipient_id)
        if not recipient:
            return {"ok": False, "error": "Получатель не найден"}
        _source, denied = self._require_availability_access(auth, recipient.get("mk_user_id"))
        if denied:
            return denied
        result = self.storage.get_schedule_availability(recipient_id)
        if result.get("ok"):
            result["child_display_name"] = recipient.get("child_display_name")
            result["campaign_id"] = recipient.get("campaign_id")
        return result

    def onboarding_recipient_availability_submit(self, auth: dict[str, Any], recipient_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/recipients/{id}/availability

        Never blocks or is required for registration itself — activation
        (storage.activate_onboarding_invite) has already completed by the
        time this can ever be called; this is purely an optional follow-up.
        """
        try:
            recipient_id = int(recipient_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid recipient id"}
        recipient = self.storage.get_onboarding_recipient(recipient_id)
        if not recipient:
            return {"ok": False, "error": "Получатель не найден"}
        source, denied = self._require_availability_access(auth, recipient.get("mk_user_id"))
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        intervals = body.get("intervals")
        if not isinstance(intervals, list):
            intervals = []
        return self.storage.submit_schedule_availability(
            recipient_id, actor, role,
            preferred_branch=body.get("preferred_branch"),
            available_from=body.get("available_from"),
            schedule_comment=body.get("schedule_comment"),
            intervals=intervals,
            source=source,
        )

    # v7.1.12.3 — permanent schedule-availability entry point for ANY linked
    # client (CL-code, onboarding invite, or staff/manual link), independent
    # of campaign/recipient/invite/continuation_status/pilot/payment state.
    # Identity here is mk_user_id (the stable, already-trusted concept
    # _require_availability_access checks ownership against) rather than
    # recipient_id — bridged internally via storage.get_or_create_recipient_
    # for_client so the underlying storage layer (submit_schedule_
    # availability/get_schedule_availability/client_schedule_availability)
    # is reused completely unchanged, with zero new tables.
    def client_schedule_availability_get(self, auth: dict[str, Any], mk_user_id_str: str) -> dict[str, Any]:
        """GET /api/client/schedule-availability/{mk_user_id}

        Read-only: never creates a recipient row just from viewing the form
        (e.g. the multi-child picker probing fill-status for each child) —
        a student with no prior submission gets a blank-form shape back.
        """
        mk_user_id = str(mk_user_id_str or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "invalid mk_user_id"}
        _source, denied = self._require_availability_access(auth, mk_user_id)
        if denied:
            return denied
        trusted = self.storage.get_trusted_local_client_candidate(mk_user_id)
        display_name = (trusted or {}).get("child_display_name") or None
        status = self.storage.get_availability_status_for_mk_user(mk_user_id)
        if not status.get("recipient_id"):
            return {
                "ok": True, "filled": False, "child_display_name": display_name,
                "preferred_branch": "unknown", "available_from": None, "schedule_comment": "",
                "availability_updated_at": None, "intervals": [],
            }
        result = self.storage.get_schedule_availability(status["recipient_id"])
        if result.get("ok"):
            result["filled"] = bool(result.get("availability_updated_at"))
            result["child_display_name"] = display_name or self.storage.get_onboarding_recipient(status["recipient_id"]).get("child_display_name")
        return result

    def client_schedule_availability_submit(self, auth: dict[str, Any], mk_user_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/schedule-availability/{mk_user_id}

        Lazily finds-or-creates the underlying recipient row (reusing an
        existing one from a real campaign if this student already has one —
        never a second, fragmented row) then delegates to the exact same
        storage.submit_schedule_availability used by the onboarding-invite
        flow. child_display_name is always re-derived server-side from the
        trusted client_parent_child_links row, never taken from the request
        body.
        """
        mk_user_id = str(mk_user_id_str or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "invalid mk_user_id"}
        source, denied = self._require_availability_access(auth, mk_user_id)
        if denied:
            return denied
        # v7.1.13.1 — an owner previewing a real client's cabinet must
        # explicitly confirm before a save actually writes to that client's
        # data; a real parent's own flow is completely unaffected (never
        # asked for this flag, source is "owner_test" only in test mode).
        if source == "owner_test" and not bool(body.get("ownerTestConfirm")):
            return {"ok": False, "error": "owner_confirm_required"}
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        trusted = self.storage.get_trusted_local_client_candidate(mk_user_id)
        display_name = (trusted or {}).get("child_display_name") or f"Ученик #{mk_user_id}"
        recipient = self.storage.get_or_create_recipient_for_client(mk_user_id, display_name, actor)
        intervals = body.get("intervals")
        if not isinstance(intervals, list):
            intervals = []
        result = self.storage.submit_schedule_availability(
            recipient["id"], actor, role,
            preferred_branch=body.get("preferred_branch"),
            available_from=body.get("available_from"),
            schedule_comment=body.get("schedule_comment"),
            intervals=intervals,
            source=source,
        )
        if result.get("ok"):
            result["filled"] = True
        return result

    # v7.1.12.1 — reproducible HMAC-signed invite links. The deep-link secret
    # is the app's existing stable secret (telegram_bot_token — the same one
    # already used for signed Mini App URLs), so a link can be re-derived at
    # ANY later time (repeat CSV export, a fresh process after a restart,
    # "copy link" on an old invite) purely from data already in the DB — no
    # plaintext bearer token is ever stored or needs to be recovered.
    def _onboarding_signing_secret(self) -> str:
        return getattr(self.settings, "telegram_bot_token", "") or ""

    def _onboarding_invite_link_from_payload(self, payload: dict[str, Any]) -> str:
        bot_username = getattr(self.settings, "bot_username", "") or "yellowclubagent_bot"
        return f"https://t.me/{bot_username}?start={ONBOARDING_INVITE_TOKEN_PREFIX}{payload['invite_id']}_{payload['signature']}"

    def _onboarding_invite_link_for(self, invite_id: Any, secret: Optional[str] = None) -> Optional[str]:
        """Best-effort reproducible link for a recipient's (possibly absent)
        invite — returns None when there is no invite at all, and the actual
        link (regardless of status: active/used/revoked/expired all
        reproduce) otherwise, per spec: a non-active invite's link may still
        be displayed, paired with its status, but can never be re-activated."""
        if not invite_id:
            return None
        secret = secret if secret is not None else self._onboarding_signing_secret()
        payload = self.storage.get_onboarding_invite_link_payload(invite_id, secret)
        if not payload:
            return None
        return self._onboarding_invite_link_from_payload(payload)

    def onboarding_campaign_create_invite(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/invites

        Body: {recipient_id, force_regenerate?}. Unlike the old random-token
        scheme, this link is NOT one-shot-visible-only — it can be re-derived
        later (see _onboarding_invite_link_for / GET campaign detail /
        export.csv), so nothing here needs special "shown once" handling.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        sys_denied = self._require_not_system_campaign(self.storage.get_onboarding_campaign(campaign_id))
        if sys_denied:
            return sys_denied
        try:
            recipient_id = int(body.get("recipient_id"))
        except (TypeError, ValueError):
            return {"ok": False, "error": "recipient_id обязателен"}
        force_regenerate = bool(body.get("force_regenerate", False))
        result = self.storage.create_onboarding_invite(campaign_id, recipient_id, actor, self._onboarding_signing_secret(), force_regenerate=force_regenerate)
        if not result.get("ok"):
            return result
        return {
            "ok": True,
            "invite_id": result["invite_id"],
            "invite_link": self._onboarding_invite_link_from_payload(result),
            "expires_at": result["expires_at"],
            "regenerated_from_invite_id": result.get("regenerated_from_invite_id"),
        }

    def onboarding_invite_revoke(self, auth: dict[str, Any], invite_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/invites/{id}/revoke"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            invite_id = int(invite_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid invite id"}
        return self.storage.revoke_onboarding_invite(invite_id, actor, role)

    def onboarding_invite_regenerate(self, auth: dict[str, Any], invite_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/invites/{id}/regenerate"""
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            invite_id = int(invite_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid invite id"}
        result = self.storage.regenerate_onboarding_invite(invite_id, actor, role, self._onboarding_signing_secret())
        if not result.get("ok"):
            return result
        return {
            "ok": True,
            "invite_id": result["invite_id"],
            "invite_link": self._onboarding_invite_link_from_payload(result),
            "expires_at": result["expires_at"],
        }

    def onboarding_invite_get_link(self, auth: dict[str, Any], invite_id_str: str) -> dict[str, Any]:
        """POST /api/client/onboarding/invites/{id}/link — re-fetch (never
        re-activate) a persistent link for an invite that may have been
        created in an earlier session, process, or even before a server
        restart. Explicit action so it can carry its own audit event
        (invite_link_exported) distinct from silently including it in every
        campaign-detail read.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            invite_id = int(invite_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid invite id"}
        payload = self.storage.get_onboarding_invite_link_payload(invite_id, self._onboarding_signing_secret())
        if not payload:
            return {"ok": False, "error": "Приглашение не найдено"}
        self.storage.log_onboarding_audit_event(
            event_type="invite_link_exported", campaign_id=payload["campaign_id"], recipient_id=payload["recipient_id"],
            invite_id=invite_id, actor_telegram_user_id=actor, actor_role=role, result="success",
        )
        return {"ok": True, "invite_id": invite_id, "invite_link": self._onboarding_invite_link_from_payload(payload), "status": payload["status"], "expires_at": payload["expires_at"]}

    def onboarding_campaign_create_invites_batch(self, auth: dict[str, Any], campaign_id_str: str, body: dict[str, Any]) -> dict[str, Any]:
        """POST /api/client/onboarding/campaigns/{id}/invites/batch

        Body: {recipient_ids: [...], force_regenerate?, idempotency_key?}.
        One server-side call for up to ONBOARDING_INVITE_MAX_BATCH_SIZE
        recipients — the frontend never issues one HTTP request per
        recipient for a 300+-client rollout.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        sys_denied = self._require_not_system_campaign(self.storage.get_onboarding_campaign(campaign_id))
        if sys_denied:
            return sys_denied
        recipient_ids_raw = body.get("recipient_ids")
        if not isinstance(recipient_ids_raw, list) or not recipient_ids_raw:
            return {"ok": False, "error": "Список получателей пуст"}
        result = self.storage.create_onboarding_invites_batch(
            campaign_id, recipient_ids_raw, actor, self._onboarding_signing_secret(),
            force_regenerate=bool(body.get("force_regenerate", False)),
            idempotency_key=body.get("idempotency_key"),
        )
        if not result.get("ok"):
            return result
        secret = self._onboarding_signing_secret()
        for r in result["results"]:
            if r.get("invite_id") and r.get("signature"):
                r["invite_link"] = self._onboarding_invite_link_from_payload({"invite_id": r["invite_id"], "signature": r["signature"]})
                del r["signature"]  # never leave the raw signature sitting in a JSON blob beyond building the link
        return result

    _ONBOARDING_CSV_HEADER = [
        "Ребёнок", "MoyKlass ID", "Учебный уровень", "Филиал", "Группа/курс", "Родитель",
        "Удобные интервалы", "Допустимые интервалы", "Дата начала", "Комментарий",
        "Статус продолжения", "Статус подключения", "Статус приглашения",
        "Срок действия", "Персональная ссылка",
    ]
    _ONBOARDING_CONTINUATION_LABELS = {
        "unknown": "Не уточнено", "continues": "Продолжает обучение",
        "undecided": "Пока не решили", "needs_consultation": "Нужна консультация",
        "not_continuing": "Не продолжает",
    }
    _ONBOARDING_ACADEMIC_LEVEL_LABELS = {
        "unknown": "Не определён", "year_1": "1-й учебный год", "year_2": "2-й учебный год",
        "year_3": "3-й учебный год", "year_4": "4-й учебный год", "advanced": "Продвинутый уровень",
    }
    _ONBOARDING_WEEKDAY_LABELS = {1: "Пн", 2: "Вт", 3: "Ср", 4: "Чт", 5: "Пт", 6: "Сб", 7: "Вс"}

    @classmethod
    def _onboarding_format_intervals(cls, intervals: list[dict], preference: str) -> str:
        parts = [
            f"{cls._ONBOARDING_WEEKDAY_LABELS.get(iv['weekday'], iv['weekday'])} {iv['start_time']}-{iv['end_time']}"
            for iv in intervals if iv.get("preference") == preference
        ]
        return "; ".join(parts)

    def onboarding_campaign_export_csv(self, auth: dict[str, Any], campaign_id_str: str, params: dict[str, str]) -> "tuple[bytes, str] | dict[str, Any]":
        """GET /api/client/onboarding/campaigns/{id}/export.csv

        Read-only — never mutates any campaign/recipient/invite row. Never
        includes token_hash, initData, API keys, or other secrets. Unlike
        the original one-shot-token design, "Персональная ссылка" is now
        populated for EVERY invite that exists (any status) — see
        _onboarding_invite_link_for — because the link is a reproducible
        HMAC-signed payload, not a stored secret; nothing here is ever the
        one-and-only chance to see it.
        """
        denied = self._require_onboarding_campaign_access(auth)
        if denied:
            return denied
        role = self._role_for_user(int(auth["user_id"]))
        actor = str(auth.get("user_id") or "")
        try:
            campaign_id = int(campaign_id_str)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid campaign id"}
        campaign = self.storage.get_onboarding_campaign(campaign_id)
        if not campaign:
            return {"ok": False, "error": "Кампания не найдена"}
        sys_denied = self._require_not_system_campaign(campaign)
        if sys_denied:
            return sys_denied
        recipients = self.storage.list_onboarding_campaign_recipients(campaign_id)
        secret = self._onboarding_signing_secret()

        buf = io.StringIO()
        writer = csv.writer(buf)
        writer.writerow(self._ONBOARDING_CSV_HEADER)
        exported_invite_ids = []
        for r in recipients:
            continuation_label = self._ONBOARDING_CONTINUATION_LABELS.get(r["continuation_status"], r["continuation_status"])
            academic_label = self._ONBOARDING_ACADEMIC_LEVEL_LABELS.get(r["academic_level"], r["academic_level"])
            link_status = "Подключён" if r["telegram_connected"] else "Не подключён"
            invite_status_label = {
                "none": "Не создано", "active": "Создано", "used": "Использовано",
                "revoked": "Отозвано", "expired": "Истекло",
            }.get(r["invite_status"], r["invite_status"])
            invite_link = self._onboarding_invite_link_for(r.get("invite_id"), secret) or "—"
            if r.get("invite_id"):
                exported_invite_ids.append(r["invite_id"])
            writer.writerow([
                r["child_display_name"], r["mk_user_id"], academic_label, r["branch_name"], r["course_name"],
                r["parent_display_name"],
                self._onboarding_format_intervals(r["availability_intervals"], "preferred"),
                self._onboarding_format_intervals(r["availability_intervals"], "possible"),
                r.get("available_from") or "", r.get("schedule_comment") or "",
                continuation_label, link_status, invite_status_label,
                r.get("invite_expires_at") or "", invite_link,
            ])
        csv_bytes = ("﻿" + buf.getvalue()).encode("utf-8")  # BOM for Excel Cyrillic
        filename = f"campaign_{campaign_id}_export.csv"
        if exported_invite_ids:
            self.storage.log_onboarding_audit_event(
                event_type="invite_link_exported", campaign_id=campaign_id,
                actor_telegram_user_id=actor, actor_role=role, result="success",
                note=f"csv_export count={len(exported_invite_ids)}",
            )
        return csv_bytes, filename

    @staticmethod
    def _normalize_payment_intent(pi: dict) -> dict:
        """Add derived frontend-friendly fields to a payment_intent row."""
        status = str(pi.get("status") or "")
        paid_minor = pi.get("paid_amount_minor")
        pi["paid_amount_byn"] = round(int(paid_minor) / 100.0, 2) if paid_minor is not None else None
        pi["payment_status"] = status
        pi["can_pay"] = status in ("draft", "ready")
        return pi

    def payment_intent_webhook_readiness(self, auth: dict[str, Any], public_id: str) -> dict[str, Any]:
        """GET /api/payments/intents/{id}/webhook-readiness — read-only pre-flight check."""
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        intent = self.storage.get_payment_intent(public_id)
        if not intent:
            return {"ok": False, "error": "Черновик платежа не найден", "public_id": public_id}

        cfg = self.settings
        checks: list[dict] = []

        def _check(name: str, ok: bool, detail: str = "") -> None:
            checks.append({"name": name, "ok": ok, "detail": detail})

        _check("status_is_bepaid_created",
               intent.get("status") == "bepaid_created",
               f"status={intent.get('status')}")
        _check("has_bepaid_uid",
               bool(intent.get("bepaid_uid")),
               f"bepaid_uid={'set' if intent.get('bepaid_uid') else 'missing'}")
        _check("has_tracking_id",
               bool(intent.get("bepaid_tracking_id")),
               f"tracking_id={'set' if intent.get('bepaid_tracking_id') else 'missing'}")
        _check("has_order_id",
               bool(intent.get("bepaid_order_id")),
               f"order_id={'set' if intent.get('bepaid_order_id') else 'missing'}")
        _check("signature_verification_configured",
               bool(getattr(cfg, "bepaid_erip_public_key", "")),
               "erip_public_key configured" if getattr(cfg, "bepaid_erip_public_key", "") else "no public key")
        _check("webhook_path_secret_configured",
               bool(getattr(cfg, "bepaid_webhook_path_secret", "")),
               "configured" if getattr(cfg, "bepaid_webhook_path_secret", "") else "missing")
        _check("not_already_paid",
               intent.get("status") != "paid",
               f"status={intent.get('status')}")
        _check("has_amount_minor",
               bool(intent.get("amount_minor")),
               f"amount_minor={intent.get('amount_minor')}")
        _check("auto_post_to_moyklass_disabled",
               not getattr(cfg, "bepaid_auto_post_to_moyklass", True),
               "disabled" if not getattr(cfg, "bepaid_auto_post_to_moyklass", True) else "WARNING:enabled")
        if intent.get("source") in MOYKLASS_INVOICE_INTENT_SOURCES:
            _check("has_mk_user_id",
                   bool(intent.get("mk_user_id")),
                   f"mk_user_id={intent.get('mk_user_id')}")
            _check("has_mk_invoice_id",
                   bool(intent.get("mk_invoice_id")),
                   f"mk_invoice_id={intent.get('mk_invoice_id')}")

        all_ok = all(c["ok"] for c in checks)
        audit = self.storage.list_payment_webhook_audit(intent_public_id=public_id, limit=20)
        return {
            "ok": True,
            "public_id": public_id,
            "ready": all_ok,
            "checks": checks,
            "intent_status": intent.get("status"),
            "webhook_audit": audit,
        }

    # ── v7.0.92: MoyKlass manual payment posting ──────────────────────────────

    # ── v7.0.92.1: MoyKlass payment type discovery ───────────────────────────

    def moyklass_payment_types(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/payments/moyklass/payment-types — list payment types + dual-channel readiness.

        Read-only. No POST to MoyKlass. No .env modification.
        Owner/admin only. Returns normalized type list + ERIP and acquiring candidates.
        """
        denied = self._require_moyklass_post_access(auth)
        if denied:
            return denied

        if not self.moyklass.is_configured:
            return {"ok": False, "error": "МойКласс API не настроен (MOYKLASS_API_KEY)"}

        result = self.moyklass.get_payment_types()
        if not result.ok:
            return {
                "ok": False,
                "error": f"Ошибка получения типов оплаты из МойКласс: HTTP {result.status}",
                "mk_status": result.status,
                "mk_error": (result.error or "")[:200],
            }

        raw_items = result.data if isinstance(result.data, list) else []
        items = [_normalize_payment_type(r) for r in raw_items if isinstance(r, dict)]

        cfg = self.settings
        erip_id = int(getattr(cfg, "moyklass_erip_payment_type_id", 0) or 0)
        acq_id = int(getattr(cfg, "moyklass_acquiring_payment_type_id", 0) or 0)

        erip_type: dict | None = next((i for i in items if i["id"] == erip_id), None) if erip_id else None
        acq_type: dict | None = next((i for i in items if i["id"] == acq_id), None) if acq_id else None

        erip_candidates = [
            {"id": i["id"], "name": i["name"]}
            for i in items
            if _is_erip_candidate(i["name"])
        ]
        acq_candidates = [
            {"id": i["id"], "name": i["name"]}
            for i in items
            if _is_acquiring_candidate(i["name"])
        ]

        erip_readiness = _build_payment_type_readiness(erip_id, erip_type, _REQUIRED_ERIP_TYPE_NAME)
        acq_readiness = _build_payment_type_readiness(acq_id, acq_type, _REQUIRED_ACQUIRING_TYPE_NAME)

        return {
            "ok": True,
            # Legacy single-channel fields (backward-compat)
            "configured_payment_type_id": erip_id if erip_id > 0 else None,
            "configured_payment_type_found": erip_type is not None,
            "configured_payment_type": erip_readiness,
            # Dual-channel readiness (v7.0.92.2)
            "erip": {
                "configured_payment_type_id": erip_id if erip_id > 0 else None,
                "configured_payment_type_found": erip_type is not None,
                "payment_type": erip_readiness,
            },
            "acquiring": {
                "configured_payment_type_id": acq_id if acq_id > 0 else None,
                "configured_payment_type_found": acq_type is not None,
                "payment_type": acq_readiness,
            },
            "items": items,
            "diagnostics": {
                "total": len(items),
                "active": sum(1 for i in items if i.get("active", True) and not i.get("deleted", False)),
                "possible_erip_matches": len(erip_candidates),
                "erip_candidates": erip_candidates,
                "possible_acquiring_matches": len(acq_candidates),
                "acquiring_candidates": acq_candidates,
                "auto_select": False,
                "env_hint_erip": (
                    f"MOYKLASS_ERIP_PAYMENT_TYPE_ID={erip_candidates[0]['id']}"
                    if len(erip_candidates) == 1 else None
                ),
                "env_hint_acquiring": (
                    f"MOYKLASS_ACQUIRING_PAYMENT_TYPE_ID={acq_candidates[0]['id']}"
                    if len(acq_candidates) == 1 else None
                ),
                "manual_selection_required": len(erip_candidates) != 1 or len(acq_candidates) != 1,
            },
        }

    def payment_integrity_audit(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/payments/integrity-audit — read-only data integrity check.

        Owner/admin only. Makes NO writes, NO external API calls.
        v7.0.96.0
        """
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_MK_POST_ROLES:
            return {"ok": False, "error": "Аудит доступен только owner и admin."}
        result = self.storage.audit_payment_integrity()
        log.info(
            "payment_event=integrity_audit_completed intent=all "
            "checked=%d critical=%d warning=%d info=%d",
            result["checked"],
            len(result["critical"]),
            len(result["warning"]),
            len(result["info"]),
        )
        return {"ok": True, **result}

    def _require_moyklass_post_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        if auth.get("_is_automation"):
            return None
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_MK_POST_ROLES:
            return {"ok": False, "error": "Доступно только owner и admin."}
        return None

    def _require_moyklass_manual_action_access(self, auth: dict[str, Any]) -> dict[str, Any] | None:
        """v7.1.11 — gate for the manual 'Внести в МойКласс' action trio only
        (readiness / post / reconcile). Deliberately separate from
        _require_moyklass_post_access, which also gates moyklass_payment_types
        (an unrelated owner/admin-only diagnostics endpoint) — widening that
        shared function to PAYMENT_MK_MANUAL_POST_ROLES would have accidentally
        given client_manager access to payment_types too."""
        if auth.get("_is_automation"):
            return None
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_MK_MANUAL_POST_ROLES:
            return {"ok": False, "error": "Внесение оплаты в МойКласс доступно только owner, admin и client_manager."}
        return None

    def payment_intent_moyklass_readiness(self, auth: dict[str, Any], public_id: str) -> dict[str, Any]:
        """GET /api/payments/intents/{id}/moyklass-post-readiness — read-only pre-flight check.

        Fetches the live invoice from MoyKlass and verifies all preconditions.
        Does NOT modify any state.
        """
        from decimal import Decimal, ROUND_HALF_UP

        denied = self._require_moyklass_manual_action_access(auth)
        if denied:
            return denied

        intent = self.storage.get_payment_intent(public_id)
        if not intent:
            return {"ok": False, "error": "Черновик платежа не найден", "public_id": public_id}

        cfg = self.settings
        checks: list[dict] = []
        warnings: list[str] = []

        def _check(code: str, ok: bool, label: str, detail: str = "") -> bool:
            checks.append({"code": code, "ok": ok, "label": label, "detail": detail})
            return ok

        # — Local intent checks —
        _check("intent_paid", intent.get("status") == "paid",
               "Оплата подтверждена bePaid", f"status={intent.get('status')}")
        _check("webhook_verified", bool(intent.get("webhook_verified")),
               "Webhook верифицирован", f"verified={intent.get('webhook_verified')}")
        _check("has_tx_uid", bool(intent.get("paid_transaction_uid")),
               "Transaction UID присутствует", f"uid={str(intent.get('paid_transaction_uid') or '')[:8]}...")
        _check("not_test_transaction", not bool(intent.get("is_test")),
               "Не тестовая транзакция", f"is_test={intent.get('is_test')}")
        _check("currency_byn", str(intent.get("paid_currency") or "").upper() == "BYN",
               "Валюта BYN", f"currency={intent.get('paid_currency')}")
        _check("paid_amount_positive", int(intent.get("paid_amount_minor") or 0) > 0,
               "Сумма оплаты положительная", f"paid_amount_minor={intent.get('paid_amount_minor')}")
        _check("amounts_match",
               int(intent.get("paid_amount_minor") or 0) == int(intent.get("amount_minor") or -1),
               "Сумма bePaid = сумме intent",
               f"paid={intent.get('paid_amount_minor')}_expected={intent.get('amount_minor')}")
        _check("source_is_invoice", intent.get("source") in MOYKLASS_INVOICE_INTENT_SOURCES,
               "Источник — счёт МойКласс", f"source={intent.get('source')}")
        if intent.get("source") == "moyklass_invoice_automation":
            _inv_id_ref = str(intent.get("mk_invoice_id") or "")
            _expected_ref = f"mk_invoice_{_inv_id_ref}" if _inv_id_ref else ""
            _actual_ref = str(intent.get("source_reference") or "")
            _check("source_reference_valid",
                   bool(_inv_id_ref) and _actual_ref == _expected_ref,
                   "source_reference совпадает с mk_invoice_id",
                   f"source_reference={_actual_ref}")
        _check("has_mk_user_id", bool(intent.get("mk_user_id")),
               "mk_user_id присутствует", f"mk_user_id={intent.get('mk_user_id')}")
        _check("has_mk_invoice_id", bool(intent.get("mk_invoice_id")),
               "mk_invoice_id присутствует", f"mk_invoice_id={intent.get('mk_invoice_id')}")
        _check("not_cancelled", intent.get("status") not in ("cancelled", "error"),
               "Intent не отменён", f"status={intent.get('status')}")
        _check("not_requires_check", intent.get("status") != "bepaid_requires_check",
               "Нет статуса requires_check", f"status={intent.get('status')}")
        _check("not_already_posted", intent.get("status") != "posted_to_moyklass",
               "Ещё не внесено в МойКласс", f"status={intent.get('status')}")
        _check("no_mk_payment_id", not intent.get("mk_payment_id"),
               "MK payment ID не сохранён", f"mk_payment_id={intent.get('mk_payment_id')}")
        _check("no_active_claim",
               intent.get("mk_posting_status") not in ("claiming", "ambiguous"),
               "Нет активного claim", f"mk_posting_status={intent.get('mk_posting_status')}")
        # v7.0.96.0 — informational only; global flag does not block manual posting
        if getattr(cfg, "bepaid_auto_post_to_moyklass", False):
            warnings.append("Глобальный авто-постинг включён (BEPAID_AUTO_POST_TO_MOYKLASS)")

        # — Payment type config check (channel-specific, v7.0.93.2.6) —
        paid_channel = resolve_effective_payment_channel(intent)
        if paid_channel == "acquiring":
            payment_type_id = int(getattr(cfg, "moyklass_acquiring_payment_type_id", 0) or 0)
            _pt_env_key = "MOYKLASS_ACQUIRING_PAYMENT_TYPE_ID"
            _pt_required_name = _REQUIRED_ACQUIRING_TYPE_NAME
            _pt_channel_label = "Эквайринг"
        else:
            payment_type_id = int(getattr(cfg, "moyklass_erip_payment_type_id", 0) or 0)
            _pt_env_key = "MOYKLASS_ERIP_PAYMENT_TYPE_ID"
            _pt_required_name = _REQUIRED_ERIP_TYPE_NAME
            _pt_channel_label = "ЕРИП"
        _check("payment_type_configured", payment_type_id > 0,
               f"Тип оплаты МойКласс настроен ({_pt_channel_label})",
               f"{_pt_env_key}={payment_type_id if payment_type_id > 0 else 'not set'}")

        # — MK subscription check (if source is invoice) —
        mk_sub_id = intent.get("mk_user_subscription_id")
        if mk_sub_id and _check("has_mk_subscription_id", bool(mk_sub_id),
                                "Абонемент присутствует", f"mk_user_subscription_id={mk_sub_id}"):
            pass  # will be included in posting payload

        # Short-circuit before MK invoice fetch if local checks already fail
        local_failed = [c for c in checks if not c["ok"]]
        invoice: dict = {}
        invoice_remaining_minor: int = -1
        invoice_error: str = ""
        _invoice_error_class: str = ""
        paid_amount_minor = int(intent.get("paid_amount_minor") or 0)
        mk_invoice_id_str = str(intent.get("mk_invoice_id") or "")
        mk_user_id = int(intent.get("mk_user_id") or 0)

        if not local_failed and self.moyklass.is_configured:
            # — Live payment type check (v7.0.92.1) —
            if payment_type_id > 0:
                try:
                    pt_result = self.moyklass.get_payment_type_by_id(payment_type_id)
                    if pt_result.ok and isinstance(pt_result.data, dict):
                        pt = pt_result.data
                        pt_deleted = bool(pt.get("deleted", False))
                        pt_active = bool(pt.get("active", True))
                        if pt_deleted:
                            _check("payment_type_valid", False, "Тип оплаты не удалён",
                                   f"paymentTypeId={payment_type_id} deleted=true")
                        elif not pt_active:
                            _check("payment_type_valid", False, "Тип оплаты активен",
                                   f"paymentTypeId={payment_type_id} active=false")
                        else:
                            actual_pt_name = str(pt.get("name") or "")
                            _check("payment_type_valid", True, "Тип оплаты существует и активен",
                                   f"paymentTypeId={payment_type_id} name={actual_pt_name[:40]!r}")
                            # v7.0.93.2.6 — exact name match (fail-closed)
                            _check("payment_type_name_match",
                                   _check_exact_type_name(actual_pt_name, _pt_required_name),
                                   f"Имя типа оплаты: «{_pt_required_name}»",
                                   f"actual={actual_pt_name!r} expected={_pt_required_name!r}")
                    elif pt_result.status == 404:
                        _check("payment_type_valid", False, "Тип оплаты найден в МойКласс",
                               f"paymentTypeId={payment_type_id} → 404 Not Found")
                    else:
                        warnings.append(
                            f"Не удалось проверить тип оплаты: HTTP {pt_result.status}"
                        )
                except Exception as e:
                    warnings.append(f"Ошибка проверки типа оплаты: {str(e)[:100]}")

            # — Live invoice check —
            if mk_invoice_id_str and mk_user_id:
                try:
                    inv_result = self.moyklass.get_invoice_by_id(int(mk_invoice_id_str))
                    if inv_result.ok and isinstance(inv_result.data, dict):
                        invoice = inv_result.data
                        inv_user_id = int(invoice.get("userId") or 0)
                        _check("invoice_belongs_to_user", inv_user_id == mk_user_id,
                               "Счёт принадлежит ученику",
                               f"invoice.userId={inv_user_id}_expected={mk_user_id}")
                        inv_sub_id = invoice.get("userSubscriptionId")
                        if mk_sub_id:
                            sub_match = (inv_sub_id is None or int(inv_sub_id or 0) == int(mk_sub_id or 0))
                            _check("invoice_subscription_matches", sub_match,
                                   "Абонемент счёта совпадает",
                                   f"invoice.userSubscriptionId={inv_sub_id}_expected={mk_sub_id}")
                        price_dec = Decimal(str(invoice.get("price") or 0))
                        payed_dec = Decimal(str(invoice.get("payed") or 0))
                        remaining_dec = (price_dec - payed_dec).quantize(
                            Decimal("0.01"), rounding=ROUND_HALF_UP
                        )
                        invoice_remaining_minor = int(
                            (remaining_dec * 100).to_integral_value(rounding=ROUND_HALF_UP)
                        )
                        _check("invoice_remaining_positive", invoice_remaining_minor > 0,
                               "Остаток счёта > 0", f"remaining_minor={invoice_remaining_minor}")
                        _check("invoice_remaining_matches_paid",
                               invoice_remaining_minor == paid_amount_minor,
                               "Остаток счёта = сумме оплаты",
                               f"remaining={invoice_remaining_minor}_paid={paid_amount_minor}")
                        if invoice_remaining_minor != paid_amount_minor:
                            warnings.append(
                                f"Остаток счёта {invoice_remaining_minor} коп. ≠ оплачено {paid_amount_minor} коп. "
                                f"Частичный платёж не поддерживается в v7.0.92."
                            )
                    elif inv_result.status == 404:
                        _check("invoice_exists", False,
                               "Счёт МойКласс найден", f"invoice_id={mk_invoice_id_str} → 404 Not Found")
                        invoice_error = f"Счёт {mk_invoice_id_str} не найден в МойКласс"
                    else:
                        _check("invoice_fetch_ok", False,
                               "Счёт МойКласс доступен",
                               f"status={inv_result.status} error={inv_result.error[:100]}")
                        invoice_error = f"Ошибка получения счёта: HTTP {inv_result.status}"
                        if inv_result.status in _TRANSIENT_MK_HTTP_STATUSES:
                            _invoice_error_class = "transient"
                except Exception as e:
                    _check("invoice_fetch_ok", False, "Счёт МойКласс доступен",
                           f"exception={str(e)[:100]}")
                    invoice_error = f"Исключение при получении счёта: {str(e)[:200]}"
                    _invoice_error_class = "transient"
        elif not self.moyklass.is_configured:
            _check("moyklass_configured", False, "МойКласс API настроен", "MOYKLASS_API_KEY не задан")

        # Audit
        self.storage.log_moyklass_post_audit(
            "moyklass_post_readiness_checked",
            intent_public_id=public_id,
            payment_intent_id=int(intent.get("id") or 0) or None,
            transaction_uid=str(intent.get("paid_transaction_uid") or "") or None,
            mk_user_id=mk_user_id or None,
            mk_invoice_id=mk_invoice_id_str or None,
            mk_user_subscription_id=str(mk_sub_id or "") or None,
            amount_minor=paid_amount_minor or None,
            currency=str(intent.get("paid_currency") or "") or None,
            invoice_remaining_minor=invoice_remaining_minor if invoice_remaining_minor >= 0 else None,
            result="ready" if all(c["ok"] for c in checks) else "not_ready",
        )

        all_ok = all(c["ok"] for c in checks)
        fingerprint = _compute_moyklass_post_fingerprint(intent, invoice) if (all_ok and invoice) else ""

        paid_byn = float(Decimal(str(paid_amount_minor)) / Decimal("100")) if paid_amount_minor else None
        preview: dict = {
            "intent_public_id": public_id,
            "student_name": intent.get("student_name"),
            "mk_user_id": mk_user_id,
            "mk_invoice_id": mk_invoice_id_str or None,
            "mk_user_subscription_id": int(mk_sub_id) if mk_sub_id else None,
            "invoice_total_minor": int(
                (Decimal(str(invoice.get("price") or 0)) * 100).to_integral_value(rounding=ROUND_HALF_UP)
            ) if invoice else None,
            "invoice_paid_minor": int(
                (Decimal(str(invoice.get("payed") or 0)) * 100).to_integral_value(rounding=ROUND_HALF_UP)
            ) if invoice else None,
            "invoice_remaining_minor": invoice_remaining_minor if invoice_remaining_minor >= 0 else None,
            "paid_amount_minor": paid_amount_minor or None,
            "paid_amount_byn": paid_byn,
            "currency": str(intent.get("paid_currency") or "BYN"),
            "paid_at": str(intent.get("paid_at") or "") or None,
            "transaction_uid": str(intent.get("paid_transaction_uid") or "") or None,
            "payment_method_label": f"bePaid {_pt_channel_label}",
            "payment_channel": paid_channel,
            "payment_type_id": payment_type_id if payment_type_id > 0 else None,
            "payment_type_required_name": _pt_required_name,
        }

        return {
            "ok": True,
            "ready": all_ok,
            "checks": checks,
            "warnings": warnings,
            "preview": preview,
            "snapshot_fingerprint": fingerprint,
            "invoice_error": invoice_error or None,
            "error_class": _invoice_error_class or None,
        }

    def payment_intent_post_to_moyklass(
        self, auth: dict[str, Any], public_id: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/post-to-moyklass — create payment in MoyKlass.

        Requires: confirm=true, snapshot_fingerprint from readiness endpoint.
        Atomic claim guards against double-click and concurrent requests.
        """
        from decimal import Decimal, ROUND_HALF_UP
        import json as _json

        denied = self._require_moyklass_manual_action_access(auth)
        if denied:
            return denied

        if not body.get("confirm"):
            return {"ok": False, "error": "confirm=true обязателен"}

        client_fingerprint = str(body.get("snapshot_fingerprint") or "").strip()
        if not client_fingerprint:
            return {"ok": False, "error": "snapshot_fingerprint обязателен"}

        user_id_str = str(auth.get("user_id") or "")

        # 1. Load intent
        intent = self.storage.get_payment_intent(public_id)
        if not intent:
            return {"ok": False, "error": "Черновик не найден"}

        # 2. Idempotency: already posted
        if intent.get("status") == "posted_to_moyklass" and intent.get("mk_payment_id"):
            log.info(
                "payment_event=posting_blocked intent=%s mk_invoice_id=%s "
                "mk_payment_id=%s result=blocked reason=already_posted",
                public_id, str(intent.get("mk_invoice_id") or ""), intent.get("mk_payment_id"),
            )
            self.storage.log_moyklass_post_audit(
                "moyklass_post_already_done",
                intent_public_id=public_id,
                payment_intent_id=int(intent.get("id") or 0) or None,
                mk_payment_id=int(intent.get("mk_payment_id") or 0) or None,
            )
            return {
                "ok": True, "idempotent": True,
                "mk_payment_id": intent.get("mk_payment_id"),
                "intent_status": intent.get("status"),
            }

        # 3. Guard: ambiguous state blocks retry
        if intent.get("mk_posting_status") == "ambiguous":
            self.storage.log_moyklass_post_audit(
                "moyklass_post_blocked",
                intent_public_id=public_id,
                reason="ambiguous_state_blocks_retry",
            )
            return {
                "ok": False,
                "error": "Не удалось определить, создалась ли оплата в МойКласс. "
                         "Повторная отправка заблокирована до проверки. "
                         "Используйте «Проверить в МойКласс».",
                "block_reason": "ambiguous_requires_reconciliation",
            }

        # 4. Guard: wrong state
        if intent.get("status") != "paid":
            self.storage.log_moyklass_post_audit(
                "moyklass_post_blocked",
                intent_public_id=public_id,
                reason=f"wrong_status:{intent.get('status')}",
            )
            return {"ok": False, "error": f"Оплата bePaid ещё не подтверждена (статус: {intent.get('status')})"}

        # 4b. Guard: withdrawn from client — v7.1.11 fix. client_visibility is
        # independent of status (withdraw_payment_intent_from_client never
        # touches status), so a withdrawn-but-still-"paid" intent previously
        # passed the check above unblocked. The frontend already hides the
        # button for withdrawn intents; this closes the matching backend gap
        # so a direct API call can't bypass it.
        if str(intent.get("client_visibility") or "") == "withdrawn":
            self.storage.log_moyklass_post_audit(
                "moyklass_post_blocked",
                intent_public_id=public_id,
                reason="withdrawn_from_client",
            )
            return {"ok": False, "error": "Счёт отозван у клиента. Внесение в МойКласс недоступно."}

        cfg = self.settings
        mk_user_id = int(intent.get("mk_user_id") or 0)
        mk_invoice_id_str = str(intent.get("mk_invoice_id") or "")
        mk_sub_id_str = str(intent.get("mk_user_subscription_id") or "")
        paid_amount_minor = int(intent.get("paid_amount_minor") or 0)
        paid_channel = resolve_effective_payment_channel(intent)
        if paid_channel == "acquiring":
            payment_type_id = int(getattr(cfg, "moyklass_acquiring_payment_type_id", 0) or 0)
            _missing_env = "MOYKLASS_ACQUIRING_PAYMENT_TYPE_ID"
        else:
            payment_type_id = int(getattr(cfg, "moyklass_erip_payment_type_id", 0) or 0)
            _missing_env = "MOYKLASS_ERIP_PAYMENT_TYPE_ID"

        # 5. Quick sanity checks
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id отсутствует"}
        if not mk_invoice_id_str:
            return {"ok": False, "error": "mk_invoice_id отсутствует"}
        if paid_amount_minor <= 0:
            return {"ok": False, "error": "paid_amount_minor отсутствует или равен 0"}
        if payment_type_id <= 0:
            self.storage.log_moyklass_post_audit(
                "moyklass_post_config_missing",
                intent_public_id=public_id,
                reason=f"{_missing_env}_not_set",
            )
            return {"ok": False, "error": f"Не настроен тип оплаты МойКласс ({_missing_env})"}
        if not self.moyklass.is_configured:
            return {"ok": False, "error": "МойКласс API не настроен"}

        # 5b. Exact name validation — fetch live payment type, fail-closed (v7.0.93.2.6)
        _pt_required_name = _REQUIRED_ACQUIRING_TYPE_NAME if paid_channel == "acquiring" else _REQUIRED_ERIP_TYPE_NAME
        try:
            _pt_result = self.moyklass.get_payment_type_by_id(payment_type_id)
            if _pt_result.ok and isinstance(_pt_result.data, dict):
                _actual_pt_name = str(_pt_result.data.get("name") or "")
                if not _check_exact_type_name(_actual_pt_name, _pt_required_name):
                    self.storage.log_moyklass_post_audit(
                        "moyklass_post_blocked",
                        intent_public_id=public_id,
                        reason=f"payment_type_name_mismatch:expected={_pt_required_name!r}:actual={_actual_pt_name!r}",
                    )
                    return {
                        "ok": False,
                        "error": (
                            f"Тип оплаты МойКласс не соответствует каналу ({paid_channel}). "
                            f"Ожидается «{_pt_required_name}», настроен «{_actual_pt_name}». "
                            f"Исправьте {_missing_env}."
                        ),
                        "error_code": "payment_type_name_mismatch",
                    }
            elif _pt_result.status == 404:
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_blocked",
                    intent_public_id=public_id,
                    reason=f"payment_type_not_found:id={payment_type_id}",
                )
                return {
                    "ok": False,
                    "error": f"Тип оплаты {payment_type_id} не найден в МойКласс.",
                    "error_code": "payment_type_not_found",
                }
            else:
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_blocked",
                    intent_public_id=public_id,
                    reason=f"payment_type_fetch_failed:HTTP_{_pt_result.status}",
                )
                return {
                    "ok": False,
                    "error": f"Не удалось проверить тип оплаты МойКласс: HTTP {_pt_result.status}. Оплата заблокирована.",
                    "error_code": "payment_type_fetch_failed",
                }
        except Exception as _pt_exc:
            self.storage.log_moyklass_post_audit(
                "moyklass_post_blocked",
                intent_public_id=public_id,
                reason=f"payment_type_check_exception:{str(_pt_exc)[:100]}",
            )
            return {
                "ok": False,
                "error": f"Не удалось проверить тип оплаты: {str(_pt_exc)[:100]}. Оплата заблокирована.",
                "error_code": "payment_type_check_exception",
            }

        # 6. Atomic claim
        log.info(
            "payment_event=posting_started intent=%s mk_invoice_id=%s "
            "channel=%s transaction_uid=%s status=paid result=started",
            public_id, mk_invoice_id_str, paid_channel,
            str(intent.get("paid_transaction_uid") or ""),
        )
        claimed = self.storage.payment_intent_claim_moyklass_post(public_id, user_id_str)
        if not claimed:
            self.storage.log_moyklass_post_audit(
                "moyklass_post_duplicate_blocked",
                intent_public_id=public_id,
                reason="claim_already_held",
            )
            return {
                "ok": False,
                "error": "Операцию уже выполняет другой запрос. Подождите и проверьте статус.",
                "block_reason": "claim_conflict",
            }

        self.storage.log_moyklass_post_audit(
            "moyklass_post_claimed",
            intent_public_id=public_id,
            payment_intent_id=int(intent.get("id") or 0) or None,
            transaction_uid=str(intent.get("paid_transaction_uid") or "") or None,
            mk_user_id=mk_user_id,
            mk_invoice_id=mk_invoice_id_str,
            mk_user_subscription_id=mk_sub_id_str or None,
            amount_minor=paid_amount_minor,
            currency=str(intent.get("paid_currency") or "BYN"),
        )

        try:
            # 7. Re-fetch intent to get latest state
            intent = self.storage.get_payment_intent(public_id) or intent

            # 8. Re-fetch live invoice from MoyKlass
            inv_result = self.moyklass.get_invoice_by_id(int(mk_invoice_id_str))
            if not inv_result.ok:
                self.storage.payment_intent_release_moyklass_claim(
                    public_id,
                    error=f"invoice_fetch_failed:status={inv_result.status}:{inv_result.error[:200]}",
                )
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_blocked",
                    intent_public_id=public_id,
                    mk_invoice_id=mk_invoice_id_str,
                    reason=f"invoice_fetch_failed:HTTP_{inv_result.status}",
                )
                return {
                    "ok": False,
                    "error": f"Не удалось получить счёт МойКласс: HTTP {inv_result.status}",
                }
            if not isinstance(inv_result.data, dict):
                self.storage.payment_intent_release_moyklass_claim(
                    public_id, error="invoice_fetch_bad_data"
                )
                return {"ok": False, "error": "МойКласс вернул некорректный ответ по счёту"}
            invoice = inv_result.data

            # 9. Verify invoice belongs to correct user
            inv_user_id = int(invoice.get("userId") or 0)
            if inv_user_id != mk_user_id:
                self.storage.payment_intent_release_moyklass_claim(
                    public_id, error=f"invoice_user_mismatch:{inv_user_id}!={mk_user_id}"
                )
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_invoice_mismatch",
                    intent_public_id=public_id,
                    mk_invoice_id=mk_invoice_id_str,
                    reason=f"invoice_userId={inv_user_id}_expected={mk_user_id}",
                )
                return {
                    "ok": False,
                    "error": f"Счёт принадлежит другому ученику (userId={inv_user_id})",
                }

            # 10. Compute and verify fingerprint
            new_fingerprint = _compute_moyklass_post_fingerprint(intent, invoice)
            if new_fingerprint != client_fingerprint:
                self.storage.payment_intent_release_moyklass_claim(
                    public_id, error=f"fingerprint_mismatch"
                )
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_invoice_changed",
                    intent_public_id=public_id,
                    mk_invoice_id=mk_invoice_id_str,
                    fingerprint=new_fingerprint,
                    reason="fingerprint_mismatch_invoice_changed_after_preview",
                )
                return {
                    "ok": False,
                    "error": "Счёт изменился после предварительной проверки. Выполните проверку заново.",
                    "error_code": "invoice_changed_after_preview",
                    "http_status": 409,
                }

            # 11. Verify remaining amount
            price_dec = Decimal(str(invoice.get("price") or 0))
            payed_dec = Decimal(str(invoice.get("payed") or 0))
            remaining_dec = (price_dec - payed_dec).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            invoice_remaining_minor = int(
                (remaining_dec * 100).to_integral_value(rounding=ROUND_HALF_UP)
            )
            if invoice_remaining_minor != paid_amount_minor:
                self.storage.payment_intent_release_moyklass_claim(
                    public_id,
                    error=f"remaining_mismatch:remaining={invoice_remaining_minor}_paid={paid_amount_minor}",
                )
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_invoice_mismatch",
                    intent_public_id=public_id,
                    mk_invoice_id=mk_invoice_id_str,
                    amount_minor=paid_amount_minor,
                    invoice_remaining_minor=invoice_remaining_minor,
                    reason=f"amount_mismatch:expected={invoice_remaining_minor}_got={paid_amount_minor}",
                )
                return {
                    "ok": False,
                    "error": f"Сумма bePaid не совпадает с остатком счёта "
                             f"({paid_amount_minor} коп. ≠ {invoice_remaining_minor} коп.)",
                }

            # 12. Build MoyKlass payment payload
            summa_byn = float(Decimal(str(paid_amount_minor)) / Decimal("100"))
            paid_date = str(intent.get("paid_at") or "")[:10]  # YYYY-MM-DD
            if not paid_date:
                paid_date = str(intent.get("updated_at") or "")[:10]
            mk_sub_id_int = int(mk_sub_id_str) if mk_sub_id_str and mk_sub_id_str.isdigit() else None
            mk_filial_id = int(intent.get("mk_filial_id") or 0) or None
            comment_parts = [
                f"Yellow Club bePaid intent={public_id}",
                f"tx={str(intent.get('paid_transaction_uid') or '')[:12]}",
                f"inv={mk_invoice_id_str}",
            ]
            comment = " ".join(comment_parts)[:500]

            self.storage.log_moyklass_post_audit(
                "moyklass_post_started",
                intent_public_id=public_id,
                payment_intent_id=int(intent.get("id") or 0) or None,
                transaction_uid=str(intent.get("paid_transaction_uid") or "") or None,
                mk_user_id=mk_user_id,
                mk_invoice_id=mk_invoice_id_str,
                mk_user_subscription_id=mk_sub_id_str or None,
                amount_minor=paid_amount_minor,
                currency=str(intent.get("paid_currency") or "BYN"),
                invoice_remaining_minor=invoice_remaining_minor,
                fingerprint=new_fingerprint,
            )
            log.info(
                "MoyKlass payment post started intent=%s invoice=%s amount_minor=%s",
                public_id, mk_invoice_id_str, paid_amount_minor,
            )

            # 13. POST to MoyKlass
            mk_result = self.moyklass.create_payment(
                user_id=mk_user_id,
                date=paid_date,
                summa=summa_byn,
                payment_type_id=payment_type_id,
                optype="income",
                filial_id=mk_filial_id,
                user_subscription_id=mk_sub_id_int,
                comment=comment,
            )

        except Exception as exc:
            reason = f"exception_before_mk_post:{str(exc)[:200]}"
            self.storage.payment_intent_mark_moyklass_ambiguous(public_id, reason)
            self.storage.log_moyklass_post_audit(
                "moyklass_post_ambiguous",
                intent_public_id=public_id,
                reason=reason,
            )
            log.exception("MoyKlass payment post: pre-POST exception intent=%s", public_id)
            return {"ok": False, "error": f"Ошибка до отправки: {str(exc)[:200]}"}

        # — Handle MoyKlass response —
        if mk_result.ok and isinstance(mk_result.data, dict):
            mk_payment_id = int(mk_result.data.get("id") or 0)
            if mk_payment_id <= 0:
                # Unexpected but positive response without id → treat as ambiguous
                reason = "mk_response_ok_but_no_id"
                self.storage.payment_intent_mark_moyklass_ambiguous(public_id, reason)
                self.storage.log_moyklass_post_audit(
                    "moyklass_post_ambiguous", intent_public_id=public_id, reason=reason
                )
                log.warning("MoyKlass payment post: ok but no id intent=%s data=%s",
                            public_id, str(mk_result.data)[:200])
                return {
                    "ok": False,
                    "error": "МойКласс принял запрос, но не вернул payment ID. "
                             "Проверьте вручную.",
                }
            from utils import now_iso
            posted_at = now_iso()
            invoice_snapshot_json = _json.dumps(invoice, ensure_ascii=False)
            self.storage.payment_intent_mark_posted_to_moyklass(
                public_id,
                mk_payment_id=mk_payment_id,
                posted_at=posted_at,
                fingerprint=new_fingerprint,
                invoice_snapshot_json=invoice_snapshot_json,
            )
            self.storage.log_moyklass_post_audit(
                "moyklass_post_succeeded",
                intent_public_id=public_id,
                payment_intent_id=int(intent.get("id") or 0) or None,
                transaction_uid=str(intent.get("paid_transaction_uid") or "") or None,
                mk_user_id=mk_user_id,
                mk_invoice_id=mk_invoice_id_str,
                mk_user_subscription_id=mk_sub_id_str or None,
                amount_minor=paid_amount_minor,
                currency=str(intent.get("paid_currency") or "BYN"),
                invoice_remaining_minor=invoice_remaining_minor,
                mk_payment_id=mk_payment_id,
                fingerprint=new_fingerprint,
                result="success",
            )
            log.info(
                "payment_event=posting_succeeded intent=%s mk_invoice_id=%s "
                "mk_payment_id=%s channel=%s transaction_uid=%s status=posted_to_moyklass result=success",
                public_id, mk_invoice_id_str, mk_payment_id,
                paid_channel, str(intent.get("paid_transaction_uid") or ""),
            )
            intent_after = self.storage.get_payment_intent(public_id) or {}
            return {
                "ok": True,
                "mk_payment_id": mk_payment_id,
                "posted_at": posted_at,
                "intent_status": "posted_to_moyklass",
                "intent": intent_after,
                "summary": {
                    "student_name": intent.get("student_name"),
                    "amount_byn": summa_byn,
                    "paid_at": str(intent.get("paid_at") or "")[:10],
                    "posted_at": posted_at[:10],
                    "mk_payment_id": mk_payment_id,
                    "mk_invoice_id": mk_invoice_id_str,
                    "transaction_uid": str(intent.get("paid_transaction_uid") or ""),
                },
            }

        # — Definite 4xx error —
        if 400 <= mk_result.status < 500:
            error_detail = str(mk_result.error or "")[:500]
            self.storage.payment_intent_release_moyklass_claim(
                public_id, error=f"mk_4xx:status={mk_result.status}:{error_detail[:200]}"
            )
            self.storage.log_moyklass_post_audit(
                "moyklass_post_failed",
                intent_public_id=public_id,
                reason=f"mk_http_{mk_result.status}",
                result=f"error:{error_detail[:100]}",
            )
            log.warning(
                "MoyKlass payment post: 4xx intent=%s status=%s error=%s",
                public_id, mk_result.status, error_detail[:200],
            )
            return {
                "ok": False,
                "error": f"МойКласс отклонил запрос (HTTP {mk_result.status}): {error_detail[:300]}",
                "error_code": f"mk_{mk_result.status}",
            }

        # — Ambiguous: 5xx, timeout, connection error —
        reason = f"mk_ambiguous:status={mk_result.status}:{str(mk_result.error or '')[:100]}"
        self.storage.payment_intent_mark_moyklass_ambiguous(public_id, reason)
        self.storage.log_moyklass_post_audit(
            "moyklass_post_ambiguous",
            intent_public_id=public_id,
            reason=reason,
        )
        log.error(
            "MoyKlass payment post: ambiguous intent=%s status=%s error=%s",
            public_id, mk_result.status, str(mk_result.error or "")[:200],
        )
        return {
            "ok": False,
            "error": "Не удалось определить, создалась ли оплата в МойКласс. "
                     "Повторная отправка заблокирована до проверки. "
                     "Используйте «Проверить в МойКласс».",
            "error_code": "ambiguous_requires_reconciliation",
        }

    def payment_intent_reconcile_moyklass(
        self, auth: dict[str, Any], public_id: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/reconcile-moyklass-payment

        Does NOT create a new payment. Only searches for an existing one.
        Used after ambiguous result to find if payment was actually created.
        Requires exact match by mk_payment_id saved before ambiguity, or
        by comment containing intent public_id + exact amount.
        """
        from decimal import Decimal, ROUND_HALF_UP

        denied = self._require_moyklass_manual_action_access(auth)
        if denied:
            return denied

        intent = self.storage.get_payment_intent(public_id)
        if not intent:
            return {"ok": False, "error": "Черновик не найден"}

        if intent.get("status") == "posted_to_moyklass":
            return {
                "ok": True,
                "already_posted": True,
                "mk_payment_id": intent.get("mk_payment_id"),
            }

        mk_user_id = int(intent.get("mk_user_id") or 0)
        paid_amount_minor = int(intent.get("paid_amount_minor") or 0)
        paid_at = str(intent.get("paid_at") or "")[:10]

        if not mk_user_id or not paid_amount_minor or not paid_at:
            return {"ok": False, "error": "Недостаточно данных для поиска (mk_user_id/paid_amount/paid_at)"}
        if not self.moyklass.is_configured:
            return {"ok": False, "error": "МойКласс API не настроен"}

        self.storage.log_moyklass_post_audit(
            "moyklass_post_reconcile_started",
            intent_public_id=public_id,
            mk_user_id=mk_user_id,
            amount_minor=paid_amount_minor,
        )

        # If we have a previously saved mk_payment_id (from ambiguous state), check it first
        saved_mk_payment_id = int(intent.get("mk_payment_id") or 0)
        if saved_mk_payment_id > 0:
            try:
                pay_result = self.moyklass.get_payment_by_id(saved_mk_payment_id)
                if pay_result.ok and isinstance(pay_result.data, dict):
                    found_pay = pay_result.data
                    found_user = int(found_pay.get("userId") or 0)
                    found_summa_minor = int(
                        (Decimal(str(found_pay.get("summa") or 0)) * 100).to_integral_value(rounding=ROUND_HALF_UP)
                    )
                    if found_user == mk_user_id and found_summa_minor == paid_amount_minor:
                        self._reconcile_mark_found(
                            public_id, intent, saved_mk_payment_id, found_pay, "by_saved_payment_id"
                        )
                        return {"ok": True, "reconciled": True, "mk_payment_id": saved_mk_payment_id,
                                "method": "by_saved_payment_id"}
            except Exception:
                pass

        # Search by userId + date window + exact amount
        try:
            # ±1 day window around paid_at
            from datetime import date as _date, timedelta as _timedelta
            paid_date_obj = _date.fromisoformat(paid_at)
            date_from = (paid_date_obj - _timedelta(days=1)).isoformat()
            date_to = (paid_date_obj + _timedelta(days=1)).isoformat()
            search_result = self.moyklass.search_payments_by_user_date(
                user_id=mk_user_id, date_from=date_from, date_to=date_to, limit=100
            )
            if search_result.ok:
                from moyklass_client import extract_items
                payments = [p for p in extract_items(search_result.data) if isinstance(p, dict)]
                summa_byn = float(Decimal(str(paid_amount_minor)) / Decimal("100"))
                matches = []
                for p in payments:
                    p_minor = int(
                        (Decimal(str(p.get("summa") or 0)) * 100).to_integral_value(rounding=ROUND_HALF_UP)
                    )
                    p_comment = str(p.get("comment") or "")
                    p_user = int(p.get("userId") or 0)
                    if p_user == mk_user_id and p_minor == paid_amount_minor and public_id in p_comment:
                        matches.append(p)
                if len(matches) == 1:
                    found_pay = matches[0]
                    found_id = int(found_pay.get("id") or 0)
                    self._reconcile_mark_found(
                        public_id, intent, found_id, found_pay, "by_comment_and_amount"
                    )
                    return {"ok": True, "reconciled": True, "mk_payment_id": found_id,
                            "method": "by_comment_and_amount"}
                if len(matches) > 1:
                    self.storage.log_moyklass_post_audit(
                        "moyklass_post_reconcile_not_found",
                        intent_public_id=public_id,
                        mk_user_id=mk_user_id,
                        reason="multiple_matches_ambiguous",
                    )
                    return {"ok": False,
                            "error": "Найдено несколько совпадающих платежей — проверьте вручную",
                            "match_count": len(matches)}
        except Exception as e:
            log.warning("MoyKlass reconcile search exception intent=%s: %s", public_id, str(e)[:200])

        self.storage.log_moyklass_post_audit(
            "moyklass_post_reconcile_not_found",
            intent_public_id=public_id,
            mk_user_id=mk_user_id,
            reason="no_matching_payment_found",
        )
        return {
            "ok": True,
            "reconciled": False,
            "message": "Оплата в МойКласс не найдена. Состояние остаётся requires_check.",
        }

    def _reconcile_mark_found(
        self, public_id: str, intent: dict, mk_payment_id: int, payment: dict, method: str
    ) -> None:
        """Mark intent as posted_to_moyklass after reconciliation found the payment."""
        from utils import now_iso
        import json as _json
        from decimal import Decimal, ROUND_HALF_UP
        paid_amount_minor = int(intent.get("paid_amount_minor") or 0)
        invoice_snap = str(intent.get("mk_posting_invoice_snapshot_json") or "")
        try:
            inv_dict = _json.loads(invoice_snap) if invoice_snap else {}
        except Exception:
            inv_dict = {}
        fingerprint = _compute_moyklass_post_fingerprint(intent, inv_dict)
        self.storage.payment_intent_mark_posted_to_moyklass(
            public_id,
            mk_payment_id=mk_payment_id,
            posted_at=now_iso(),
            fingerprint=fingerprint,
            invoice_snapshot_json=invoice_snap,
        )
        self.storage.log_moyklass_post_audit(
            "moyklass_post_reconciled",
            intent_public_id=public_id,
            mk_user_id=int(intent.get("mk_user_id") or 0) or None,
            mk_invoice_id=str(intent.get("mk_invoice_id") or "") or None,
            mk_payment_id=mk_payment_id,
            amount_minor=paid_amount_minor,
            result=method,
        )
        log.info("MoyKlass reconciled intent=%s mk_payment_id=%s method=%s",
                 public_id, mk_payment_id, method)

    # ── end v7.0.92 ──────────────────────────────────────────────────────────

    def payment_intent_create(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        # Validate required fields
        mk_user_id_raw = body.get("mk_user_id")
        if not mk_user_id_raw:
            return {"ok": False, "error": "mk_user_id обязателен"}
        try:
            mk_user_id = int(mk_user_id_raw)
        except (TypeError, ValueError):
            return {"ok": False, "error": "mk_user_id должен быть числом"}
        if mk_user_id <= 0:
            return {"ok": False, "error": "mk_user_id должен быть положительным числом"}

        amount_byn_raw = body.get("amount_byn")
        try:
            amount_byn = float(amount_byn_raw)
        except (TypeError, ValueError):
            return {"ok": False, "error": "amount_byn обязателен и должен быть числом"}
        if amount_byn <= 0:
            return {"ok": False, "error": "amount_byn должен быть больше нуля"}
        amount_minor = round(amount_byn * 100)

        purpose = str(body.get("purpose") or "other").strip()
        if purpose not in self._PI_VALID_PURPOSES:
            return {"ok": False, "error": f"purpose должен быть одним из: {', '.join(sorted(self._PI_VALID_PURPOSES))}"}

        period_month = str(body.get("period_month") or "").strip() or None
        if period_month:
            import re as _re
            if not _re.fullmatch(r"\d{4}-\d{2}", period_month):
                return {"ok": False, "error": "period_month должен быть в формате YYYY-MM"}

        payment_method = str(body.get("payment_method") or "erip").strip()
        if payment_method not in self._PI_VALID_METHODS:
            return {"ok": False, "error": f"payment_method должен быть одним из: {', '.join(sorted(self._PI_VALID_METHODS))}"}

        student_name_form = str(body.get("student_name") or "").strip() or None
        comment = str(body.get("comment") or "").strip() or None
        tg_id = int(auth.get("user_id") or 0) or None
        tg_name = str(auth.get("full_name") or auth.get("username") or "").strip() or None
        now = now_iso()

        # Always look up student name from MoyKlass (authoritative source)
        warnings: list[str] = []
        mk_fetched_name: str | None = None
        mk_name_warning: str | None = None
        try:
            _mk_user_result = self.moyklass.request("GET", f"/v1/company/users/{mk_user_id}")
            if _mk_user_result.ok and isinstance(_mk_user_result.data, dict):
                _u = _mk_user_result.data
                _fn = str(_u.get("name") or "").strip()
                if not _fn:
                    _fn = " ".join(filter(None, [
                        str(_u.get("clientName") or _u.get("lastName") or ""),
                        str(_u.get("firstName") or ""),
                    ])).strip()
                mk_fetched_name = _fn or None
            elif not _mk_user_result.ok:
                mk_name_warning = f"Ученик mk_user_id={mk_user_id} не найден в МойКласс (статус {_mk_user_result.status})"
        except Exception as _mk_exc:
            mk_name_warning = f"Не удалось получить данные ученика из МойКласс: {_mk_exc}"

        # Resolve final student_name; warn on mismatch
        student_name_mismatch: str | None = None
        if mk_fetched_name:
            if (student_name_form and
                    student_name_form.lower().strip() != mk_fetched_name.lower().strip()):
                student_name_mismatch = (
                    f"Имя в форме «{student_name_form}» отличается от МойКласс «{mk_fetched_name}». "
                    "Сохранено имя из МойКласс."
                )
            student_name = mk_fetched_name
        else:
            student_name = student_name_form
            if mk_name_warning:
                warnings.append(mk_name_warning)

        # Check for duplicates (soft warning, not hard block)
        duplicates = self.storage.find_duplicate_payment_intents(
            mk_user_id=mk_user_id,
            amount_minor=amount_minor,
            purpose=purpose,
            period_month=period_month,
        )
        duplicate_warning = None
        if duplicates:
            first = duplicates[0]
            duplicate_warning = (
                f"Уже существует похожий черновик #{first['public_id']} "
                f"(статус: {first['status']}, дата: {first['created_at'][:10]}). "
                "Черновик создан, но проверьте наличие дублей."
            )

        intent = self.storage.create_payment_intent({
            "mk_user_id": mk_user_id,
            "student_name": student_name,
            "amount_minor": amount_minor,
            "amount_byn": round(amount_byn, 2),
            "currency": "BYN",
            "purpose": purpose,
            "period_month": period_month,
            "payment_method": payment_method,
            "status": "draft",
            "comment": comment,
            "created_by_tg_id": tg_id,
            "created_by_name": tg_name,
            "created_at": now,
            "raw_context_json": json.dumps(body.get("raw_context") or {}, ensure_ascii=False) if body.get("raw_context") else None,
        })

        log.info(
            "payment_intent created public_id=%s mk_user_id=%s amount_byn=%s purpose=%s by=%s",
            intent.get("public_id"), mk_user_id, amount_byn, purpose, tg_id,
        )

        if student_name_mismatch:
            warnings.append(student_name_mismatch)

        return {
            "ok": True,
            "intent": intent,
            "duplicate_warning": duplicate_warning,
            "student_name_mismatch": student_name_mismatch,
            "warnings": warnings,
            "message": "Черновик платежа создан. На этом этапе платёж в bePaid и МойКласс не создавался.",
        }

    def payment_intent_cancel(self, auth: dict[str, Any], public_id: str, body: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied
        existing = self.storage.get_payment_intent(public_id)
        if not existing:
            return {"ok": False, "error": "Черновик не найден", "public_id": public_id}
        if existing["status"] not in self._PI_VALID_STATUSES_CANCEL:
            return {
                "ok": False,
                "error": f"Нельзя отменить черновик в статусе '{existing['status']}'. Отмена доступна только для статусов: draft, ready.",
            }
        reason = str(body.get("reason") or "Отменён пользователем").strip()
        now = now_iso()
        updated = self.storage.cancel_payment_intent(public_id, reason, now)
        if not updated:
            return {"ok": False, "error": "Не удалось обновить черновик"}
        log.info("payment_intent cancelled public_id=%s by=%s reason=%s", public_id, auth.get("user_id"), reason)
        return {"ok": True, "intent": updated, "message": "Черновик отменён."}

    def moyklass_invoices_list(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        status_filter = str(params.get("status") or "unpaid_partial").lower()
        mk_user_id_raw = params.get("userId") or params.get("user_id") or ""
        invoice_id_raw = str(params.get("invoiceId") or params.get("invoice_id") or "").strip()

        # result_limit caps how many filtered cards we return to the frontend.
        # It does NOT limit how many raw invoices we scan from MK.
        try:
            result_limit = min(int(params.get("limit") or 50), 200)
        except (TypeError, ValueError):
            result_limit = 50

        mk_user_id: "int | None" = None
        if mk_user_id_raw:
            try:
                mk_user_id = int(mk_user_id_raw)
            except (TypeError, ValueError):
                return {"ok": False, "error": "userId должен быть числом"}

        # Diagnostics visible to owner/admin/operations only
        user_role = self._role_for_user(int(auth["user_id"]))
        include_diagnostics = user_role in FULL_ADMIN_ROLES

        # Direct invoice lookup: fast path for any user with payment intent access
        if invoice_id_raw:
            direct = _mk_invoice_by_id(self.moyklass, invoice_id_raw)
            if direct is not None:
                price_d = float(direct.get("price") or 0)
                payed_d = float(direct.get("payed") or 0)
                remaining_d = max(0.0, price_d - payed_d)
                if remaining_d <= 0.01:
                    status_d = "paid"
                elif payed_d > 0:
                    status_d = "partial"
                else:
                    status_d = "unpaid"
                sub_d = direct.get("userSubscription") if isinstance(direct.get("userSubscription"), dict) else None
                inv_id_d = str(direct.get("id") or "")
                active_d = self.storage.find_active_intent_by_invoice(inv_id_d)
                inv_user_id_str = str(direct.get("userId") or "")
                direct_name_map: dict[str, str] = {}
                if inv_user_id_str:
                    try:
                        direct_name_map = self._mk_student_names_by_ids({inv_user_id_str})
                    except Exception:
                        log.debug("Name lookup failed for invoice direct path", exc_info=True)
                inv_card = {
                    "invoice_id": inv_id_d,
                    "mk_user_id": direct.get("userId"),
                    "student_name": direct_name_map.get(inv_user_id_str) or None,
                    "price": price_d,
                    "payed": payed_d,
                    "payed_bonuses": float(direct.get("payedBonuses") or 0),
                    "remaining": remaining_d,
                    "remaining_minor": round(remaining_d * 100),
                    "price_minor": round(price_d * 100),
                    "invoice_status": status_d,
                    "date": direct.get("date"),
                    "pay_until": direct.get("payUntil"),
                    "created_at": direct.get("createdAt"),
                    "comment": direct.get("comment"),
                    "user_subscription_id": direct.get("userSubscriptionId"),
                    "join_id": direct.get("joinId"),
                    "subscription": {
                        "id": sub_d.get("id"),
                        "subscription_id": sub_d.get("subscriptionId"),
                        "begin_date": sub_d.get("beginDate"),
                        "end_date": sub_d.get("endDate"),
                        "sell_date": sub_d.get("sellDate"),
                        "price": sub_d.get("price"),
                        "status_id": sub_d.get("statusId"),
                    } if sub_d else None,
                    "active_intent_id": active_d["public_id"] if active_d else None,
                    "active_intent_status": active_d["status"] if active_d else None,
                    "active_intent_period_month": active_d.get("period_month") if active_d else None,
                    "active_bepaid_uid": active_d.get("bepaid_uid") if active_d else None,
                    "active_bepaid_account": active_d.get("bepaid_account_number") if active_d else None,
                }
                resp: dict[str, Any] = {"ok": True, "invoices": [inv_card], "count": 1}
                if include_diagnostics:
                    resp["diagnostics"] = {
                        "lookup_mode": "direct_by_id",
                        "invoice_id": invoice_id_raw,
                        "target_invoice_found": True,
                        "raw_invoices_scanned": 1,
                        "returned_count": 1,
                        "filter": "direct",
                        "pages_loaded": 1,
                        "page_limit": 1,
                        "total_items_reported": 1,
                        "stopped_reason": "direct_lookup",
                        "cache_hit": False,
                        "cache_age_seconds": None,
                        "cache_ttl_seconds": _MK_INVOICES_CACHE_TTL,
                        "scan_duration_ms": 0,
                    }
                return resp
            # Direct lookup returned None — fall through to paginated scan

        # Base MK params; pagination adds limit + offset
        mk_base_params: dict[str, Any] = {"includeUserSubscriptions": "true"}
        if mk_user_id is not None:
            mk_base_params["userId"] = mk_user_id

        # Paginated scan: use 5-min cache for global (no userId) queries; bypass for userId-specific
        cache_hit = False
        cache_age = 0.0
        if mk_user_id is None:
            # Global scan — use in-memory cache (single-flight, 5-min TTL)
            try:
                raw_list, page_diag, cache_hit, cache_age = _mk_invoices_get_cached(
                    self.moyklass, mk_base_params
                )
            except Exception as exc:
                log.exception("moyklass_invoices_list global fetch error")
                return {"ok": False, "error": f"Ошибка запроса к МойКласс: {exc}"}
        else:
            # User-specific scan — always fresh, typically 1-2 pages
            t0_scan = time.monotonic()
            try:
                raw_list, page_diag = _mk_fetch_invoices_paginated(self.moyklass, mk_base_params)
            except Exception as exc:
                log.exception("moyklass_invoices_list user scan error")
                return {"ok": False, "error": f"Ошибка запроса к МойКласс: {exc}"}
            page_diag["scan_duration_ms"] = int((time.monotonic() - t0_scan) * 1000)

        if page_diag.get("stopped_reason") == "mk_error":
            return {"ok": False, "error": "МойКласс вернул ошибку при загрузке счетов"}

        # Normalise and filter
        filtered_paid_count = 0
        filtered_invalid_count = 0
        missing_price_count = 0
        missing_user_id_count = 0
        normalized: list[dict] = []

        for inv in raw_list:
            if not isinstance(inv, dict):
                filtered_invalid_count += 1
                continue
            if not inv.get("price") and inv.get("price") != 0:
                missing_price_count += 1
            if not inv.get("userId"):
                missing_user_id_count += 1

            price = float(inv.get("price") or 0)
            payed = float(inv.get("payed") or 0)
            remaining = max(0.0, price - payed)

            if remaining <= 0.01:
                inv_status = "paid"
            elif payed > 0:
                inv_status = "partial"
            else:
                inv_status = "unpaid"

            if status_filter not in ("all",):
                if status_filter == "unpaid" and inv_status != "unpaid":
                    if inv_status == "paid":
                        filtered_paid_count += 1
                    continue
                if status_filter == "partial" and inv_status != "partial":
                    if inv_status == "paid":
                        filtered_paid_count += 1
                    continue
                if status_filter == "unpaid_partial" and inv_status == "paid":
                    filtered_paid_count += 1
                    continue

            sub = inv.get("userSubscription") if isinstance(inv.get("userSubscription"), dict) else None
            invoice_id = str(inv.get("id") or "")
            active = self.storage.find_active_intent_by_invoice(invoice_id)

            normalized.append({
                "invoice_id": invoice_id,
                "mk_user_id": inv.get("userId"),
                "student_name": None,  # filled below after batch name lookup
                "price": price,
                "payed": payed,
                "payed_bonuses": float(inv.get("payedBonuses") or 0),
                "remaining": remaining,
                "remaining_minor": round(remaining * 100),
                "price_minor": round(price * 100),
                "invoice_status": inv_status,
                "date": inv.get("date"),
                "pay_until": inv.get("payUntil"),
                "created_at": inv.get("createdAt"),
                "comment": inv.get("comment"),
                "user_subscription_id": inv.get("userSubscriptionId"),
                "join_id": inv.get("joinId"),
                "subscription": {
                    "id": sub.get("id"),
                    "subscription_id": sub.get("subscriptionId"),
                    "begin_date": sub.get("beginDate"),
                    "end_date": sub.get("endDate"),
                    "sell_date": sub.get("sellDate"),
                    "price": sub.get("price"),
                    "status_id": sub.get("statusId"),
                } if sub else None,
                "active_intent_id": active["public_id"] if active else None,
                "active_intent_status": active["status"] if active else None,
                "active_intent_period_month": active.get("period_month") if active else None,
                "active_bepaid_uid": active.get("bepaid_uid") if active else None,
                "active_bepaid_account": active.get("bepaid_account_number") if active else None,
            })

        # Sort: newest date first, then payUntil desc, then invoice id desc
        def _sort_key(n: dict) -> tuple:
            date_str = str(n.get("date") or n.get("created_at") or "")
            pay_until = str(n.get("pay_until") or "")
            inv_id = int(n.get("invoice_id") or 0)
            return (date_str, pay_until, inv_id)

        normalized.sort(key=_sort_key, reverse=True)

        # Batch-resolve student names; result_limit applied after so names cover all returned cards
        all_user_ids = {str(n["mk_user_id"]) for n in normalized if n.get("mk_user_id")}
        names_resolved_count = 0
        names_missing_count = 0
        if all_user_ids:
            try:
                name_map = self._mk_student_names_by_ids(all_user_ids)
                for n in normalized:
                    uid_str = str(n.get("mk_user_id") or "")
                    n["student_name"] = name_map.get(uid_str) or None
                names_resolved_count = sum(1 for n in normalized if n.get("student_name"))
                names_missing_count = len(normalized) - names_resolved_count
            except Exception:
                log.debug("Batch student name resolution failed", exc_info=True)

        # Apply result_limit AFTER pagination (not before)
        result_invoices = normalized[:result_limit]
        returned_count = len(result_invoices)
        raw_scanned = page_diag["raw_invoices_scanned"]

        log.info(
            "MoyKlass invoices pages=%d total=%s scanned=%d unpaid=%d returned=%d filter=%s",
            page_diag["pages_loaded"],
            page_diag.get("total_items_reported", "?"),
            raw_scanned,
            len(normalized),
            returned_count,
            status_filter,
        )

        # Subscription debt check: if userId given and no invoices returned, check subscriptions
        subscription_debt_warning = None
        if mk_user_id is not None and returned_count == 0:
            subscription_debt_warning = self._check_subscription_debt(mk_user_id)

        # target_invoice tracking for diagnostics
        target_found: "bool | None" = None
        if invoice_id_raw:
            target_found = any(n["invoice_id"] == invoice_id_raw for n in normalized)

        response: dict[str, Any] = {"ok": True, "invoices": result_invoices, "count": returned_count}
        if subscription_debt_warning:
            response["subscription_debt_warning"] = subscription_debt_warning
        if include_diagnostics:
            diag_out: dict[str, Any] = {
                "pages_loaded": page_diag["pages_loaded"],
                "page_limit": page_diag["page_limit"],
                "total_items_reported": page_diag.get("total_items_reported"),
                "raw_invoices_scanned": raw_scanned,
                "normalised_count": raw_scanned - filtered_invalid_count,
                "returned_count": returned_count,
                "filter": status_filter,
                "filtered_paid_count": filtered_paid_count,
                "filtered_invalid_count": filtered_invalid_count,
                "missing_price_count": missing_price_count,
                "missing_user_id_count": missing_user_id_count,
                "stopped_reason": page_diag.get("stopped_reason"),
                "cache_hit": cache_hit,
                "cache_age_seconds": round(cache_age, 1) if cache_hit else None,
                "cache_ttl_seconds": _MK_INVOICES_CACHE_TTL,
                "scan_duration_ms": page_diag.get("scan_duration_ms"),
                "names_resolved_count": names_resolved_count,
                "names_missing_count": names_missing_count,
            }
            if target_found is not None:
                diag_out["target_invoice_found"] = target_found
            response["diagnostics"] = diag_out
        return response

    def _check_subscription_debt(self, mk_user_id: int) -> dict | None:
        """Check if a user has subscription debt without a corresponding invoice.

        Returns a dict with debt info if found, None otherwise.
        Does not raise — any error is silently ignored (non-critical diagnostic).
        """
        try:
            result = self.moyklass.request(
                "GET", "/v1/company/userSubscriptions",
                params={"userId": mk_user_id, "limit": 50},
            )
            if not result.ok or not result.data:
                return None
            from moyklass_client import extract_items
            subs = extract_items(result.data)
            total_debt_byn = 0.0
            debt_subs: list[dict] = []
            for sub in subs:
                if not isinstance(sub, dict):
                    continue
                price = float(sub.get("price") or 0)
                payed = float(sub.get("payed") or sub.get("paid") or 0)
                remaining = max(0.0, price - payed)
                if remaining > 0.01:
                    total_debt_byn += remaining
                    debt_subs.append({
                        "subscription_id": sub.get("id"),
                        "price": price,
                        "payed": payed,
                        "remaining": remaining,
                        "status_id": sub.get("statusId"),
                        "begin_date": sub.get("beginDate"),
                    })
            if not debt_subs:
                return None
            return {
                "warning": "subscription_debt_without_invoice",
                "total_debt_byn": round(total_debt_byn, 2),
                "subscriptions_with_debt": len(debt_subs),
                "subscriptions": debt_subs[:5],
            }
        except Exception:
            return None

    def payment_intent_from_mk_invoice(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        invoice_id = str(body.get("invoice_id") or "").strip()
        if not invoice_id:
            return {"ok": False, "error": "invoice_id обязателен"}

        mk_user_id_raw = body.get("mk_user_id")
        if not mk_user_id_raw:
            return {"ok": False, "error": "mk_user_id обязателен"}
        try:
            mk_user_id = int(mk_user_id_raw)
        except (TypeError, ValueError):
            return {"ok": False, "error": "mk_user_id должен быть числом"}
        if mk_user_id <= 0:
            return {"ok": False, "error": "mk_user_id должен быть положительным числом"}

        payment_method = str(body.get("payment_method") or "erip").strip()
        if payment_method not in self._PI_VALID_METHODS:
            return {"ok": False, "error": f"payment_method должен быть одним из: {', '.join(sorted(self._PI_VALID_METHODS))}"}

        # Guard: one active intent per invoice
        existing = self.storage.find_active_intent_by_invoice(invoice_id)
        if existing:
            return {
                "ok": False,
                "error": (
                    f"Для счёта МойКласс #{invoice_id} уже существует активный черновик "
                    f"#{existing['public_id']} (статус: {existing['status']}). "
                    "Отмените его перед созданием нового."
                ),
                "duplicate_id": existing["public_id"],
            }

        # Re-fetch invoice from MoyKlass — do not trust frontend amounts.
        # Try the direct endpoint first (fast, no pagination needed).
        invoice: "dict | None" = _mk_invoice_by_id(self.moyklass, invoice_id)

        if invoice is None:
            # Fall back to paginated user-scoped list (also includes userSubscription data)
            try:
                raw_list, _ = _mk_fetch_invoices_paginated(
                    self.moyklass,
                    {"userId": mk_user_id, "includeUserSubscriptions": "true"},
                )
            except Exception as exc:
                log.exception("payment_intent_from_mk_invoice: MK request error")
                return {"ok": False, "error": f"Ошибка запроса к МойКласс: {exc}"}
            invoice = next((inv for inv in raw_list if str(inv.get("id") or "") == invoice_id), None)

        if not invoice:
            return {"ok": False, "error": f"Счёт МойКласс #{invoice_id} не найден для пользователя {mk_user_id}"}

        price = float(invoice.get("price") or 0)
        payed = float(invoice.get("payed") or 0)
        remaining = max(0.0, price - payed)

        if remaining <= 0.01:
            return {"ok": False, "error": f"Счёт МойКласс #{invoice_id} уже полностью оплачен"}

        verified_user_id = int(invoice.get("userId") or mk_user_id)
        amount_minor = round(remaining * 100)
        amount_byn = round(remaining, 2)

        # Fetch student name
        student_name: str | None = None
        try:
            _user_result = self.moyklass.request("GET", f"/v1/company/users/{verified_user_id}")
            if _user_result.ok and isinstance(_user_result.data, dict):
                _u = _user_result.data
                _fn = str(_u.get("name") or "").strip()
                if not _fn:
                    _fn = " ".join(filter(None, [
                        str(_u.get("clientName") or _u.get("lastName") or ""),
                        str(_u.get("firstName") or ""),
                    ])).strip()
                student_name = _fn or None
        except Exception as _exc:
            log.warning("payment_intent_from_mk_invoice: could not fetch user name: %s", _exc)

        sub = invoice.get("userSubscription") if isinstance(invoice.get("userSubscription"), dict) else None
        user_sub_id = str(invoice.get("userSubscriptionId") or "").strip() or None

        # Derive period_month from subscription begin date or payUntil
        period_month: str | None = None
        if sub:
            begin = str(sub.get("beginDate") or "")[:7]
            if len(begin) == 7:
                period_month = begin
        if not period_month:
            pay_until = str(invoice.get("payUntil") or "")[:7]
            if len(pay_until) == 7:
                period_month = pay_until

        tg_id = int(auth.get("user_id") or 0) or None
        tg_name = str(auth.get("full_name") or auth.get("username") or "").strip() or None
        now = now_iso()

        intent = self.storage.create_payment_intent({
            "mk_user_id": verified_user_id,
            "student_name": student_name,
            "amount_minor": amount_minor,
            "amount_byn": amount_byn,
            "currency": "BYN",
            "purpose": "subscription",
            "period_month": period_month,
            "payment_method": payment_method,
            "status": "draft",
            "comment": str(invoice.get("comment") or "").strip() or None,
            "created_by_tg_id": tg_id,
            "created_by_name": tg_name,
            "created_at": now,
            "mk_invoice_id": invoice_id,
            "mk_user_subscription_id": user_sub_id,
            "source": "moyklass_invoice",
            "source_reference": f"mk_invoice_{invoice_id}",
            "invoice_amount_minor": round(price * 100),
            "invoice_remaining_minor": round(remaining * 100),
            "invoice_snapshot_json": json.dumps(invoice, ensure_ascii=False),
            "verified_mk_user_at": now,
            "verified_invoice_at": now,
        })

        # ── v7.0.99.0: persist deadline from payUntil ──────────────────────────
        _pay_until_raw = str(invoice.get("payUntil") or "").strip() or None
        _due_at, _due_at_source = normalize_due_at(
            _pay_until_raw, now,
            getattr(self.settings, "payment_default_due_days", 14),
        )
        if intent.get("public_id"):
            try:
                self.storage.set_intent_due_at(
                    intent["public_id"], _pay_until_raw, _due_at, _due_at_source, now,
                )
            except Exception:
                log.warning("payment_intent_from_mk_invoice: set_intent_due_at failed for %s", intent.get("public_id"))

        log.info(
            "payment_intent_from_mk_invoice created public_id=%s mk_user_id=%s invoice_id=%s amount_byn=%s by=%s due_at=%s src=%s",
            intent.get("public_id"), verified_user_id, invoice_id, amount_byn, tg_id, _due_at, _due_at_source,
        )

        return {
            "ok": True,
            "intent": intent,
            "message": "Черновик создан на основе счёта МойКласс. Сумма взята напрямую из МойКласс.",
        }

    def _preflight_mk_invoice(self, pi: dict) -> dict:
        """Re-verify a MoyKlass invoice before issuing a bePaid payment."""
        invoice_id = str(pi.get("mk_invoice_id") or "").strip()
        mk_user_id = int(pi.get("mk_user_id") or 0)

        # Try direct endpoint first — fast and does not require pagination
        invoice: "dict | None" = _mk_invoice_by_id(self.moyklass, invoice_id)

        if invoice is None:
            # Fall back to paginated user-scoped list (handles any MK config)
            log.info("_preflight_mk_invoice: direct lookup None for %s, falling back to list", invoice_id)
            try:
                raw_list, _ = _mk_fetch_invoices_paginated(
                    self.moyklass,
                    {"userId": mk_user_id, "includeUserSubscriptions": "false"},
                )
            except Exception as exc:
                log.warning("_preflight_mk_invoice MK request error: %s", exc)
                return {"ok": False, "error": f"Не удалось проверить счёт МойКласс перед выставлением: {exc}"}
            invoice = next((inv for inv in raw_list if str(inv.get("id") or "") == invoice_id), None)

        if not invoice:
            return {
                "ok": False,
                "error": (
                    f"Счёт МойКласс #{invoice_id} не найден. "
                    "Возможно, он был удалён или изменён. Проверьте в МойКласс."
                ),
            }

        price = float(invoice.get("price") or 0)
        payed = float(invoice.get("payed") or 0)
        remaining = max(0.0, price - payed)

        if remaining <= 0.01:
            return {
                "ok": False,
                "error": f"Счёт МойКласс #{invoice_id} уже полностью оплачен (остаток 0 BYN). Счёт bePaid не выставлен.",
            }

        remaining_minor = round(remaining * 100)
        intent_amount_minor = int(pi.get("amount_minor") or 0)
        if abs(remaining_minor - intent_amount_minor) > 1:
            return {
                "ok": False,
                "error": (
                    f"Сумма в МойКласс изменилась. "
                    f"Остаток сейчас: {remaining_minor / 100:.2f} BYN, "
                    f"в черновике: {intent_amount_minor / 100:.2f} BYN. "
                    "Отмените черновик и создайте новый на актуальную сумму."
                ),
            }

        # Ensure no other active intent for this invoice
        other = self.storage.find_active_intent_by_invoice(invoice_id)
        if other and str(other.get("public_id")) != str(pi.get("public_id")):
            return {
                "ok": False,
                "error": (
                    f"Для счёта МойКласс #{invoice_id} уже есть активный черновик "
                    f"#{other['public_id']} (статус: {other['status']})."
                ),
            }

        return {"ok": True}

    def payment_intent_create_bepaid(
        self, auth: dict[str, Any], public_id: str, body: dict[str, Any],
        *, _bypass_method_check: bool = False,
    ) -> dict[str, Any]:
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Черновик не найден", "public_id": public_id}

        if pi.get("client_visibility") == "withdrawn":
            return {
                "ok": False,
                "error": "Этот счёт отозван и больше не доступен для оплаты.",
                "withdrawn": True,
            }

        if not _bypass_method_check and pi.get("payment_method") != "erip":
            return {"ok": False, "error": "Выставление счёта bePaid доступно только для метода ERIP."}

        status = pi["status"]

        # Idempotency: already successfully created
        if status == "bepaid_created" and pi.get("bepaid_uid"):
            return {
                "ok": True,
                "already_exists": True,
                "intent": pi,
                "message": f"Счёт bePaid уже выставлен (UID: {pi['bepaid_uid']}).",
            }

        # Also handle bepaid_uid set on draft/ready (shouldn't happen, but guard it)
        if pi.get("bepaid_uid"):
            return {
                "ok": True,
                "already_exists": True,
                "intent": pi,
                "message": f"Счёт bePaid уже выставлен (UID: {pi['bepaid_uid']}).",
            }

        # Ambiguous state: requires manual operator review before any retry
        if status == "bepaid_requires_check":
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "Статус счёта неизвестен. Новый счёт не создавался повторно. "
                    "Требуется проверить операцию в bePaid вручную."
                ),
                "intent": pi,
            }

        # In-progress: another concurrent request holds the claim
        if status == "bepaid_creating":
            return {
                "ok": False,
                "error": "Счёт уже создаётся или требует проверки. Подождите и обновите страницу.",
            }

        if status not in ("draft", "ready"):
            return {
                "ok": False,
                "error": f"Нельзя выставить счёт bePaid для черновика в статусе '{status}'. "
                         "Доступно только для статусов: draft, ready.",
            }

        # ── Pre-flight config check (before claiming to avoid stuck state) ──────
        missing_cfg: list[str] = []
        if not self.settings.bepaid_erip_shop_id:
            missing_cfg.append("BEPAID_ERIP_SHOP_ID")
        if not self.settings.bepaid_erip_secret_key:
            missing_cfg.append("BEPAID_ERIP_SECRET_KEY")
        if not self.settings.bepaid_public_base_url:
            missing_cfg.append("BEPAID_PUBLIC_BASE_URL")
        if not self.settings.bepaid_webhook_path_secret:
            missing_cfg.append("BEPAID_WEBHOOK_PATH_SECRET")
        if missing_cfg:
            return {
                "ok": False,
                "error": (
                    f"Не настроены обязательные переменные: {', '.join(missing_cfg)}. "
                    "Счёт не выставлен, статус черновика не изменён."
                ),
            }

        # ── Preflight: re-verify MoyKlass invoice before claiming ─────────────────
        if is_moyklass_invoice_intent(pi) and pi.get("mk_invoice_id"):
            mk_check = self._preflight_mk_invoice(pi)
            if not mk_check["ok"]:
                return mk_check

        mk_user_id = int(pi["mk_user_id"])
        period_month = str(pi.get("period_month") or "")
        pi_row_id = int(pi["id"])
        original_status = status

        account_number = BePaidClient.erip_account_number(mk_user_id, period_month, pi_row_id)
        order_id = BePaidClient.erip_order_id(pi_row_id)
        tracking_id = str(pi["public_id"])

        # ── Atomic claim ──────────────────────────────────────────────────────────
        claimed = self.storage.payment_intent_claim_bepaid_creation(
            public_id,
            account_number=account_number,
            order_id=order_id,
            tracking_id=tracking_id,
        )
        if not claimed:
            return {
                "ok": False,
                "error": "Счёт уже создаётся или требует проверки. Подождите и обновите страницу.",
            }

        notification_url = (
            f"{self.settings.bepaid_public_base_url}"
            f"/api/integrations/bepaid/webhook/erip/{self.settings.bepaid_webhook_path_secret}"
        )
        description = build_erip_description(pi)
        # v7.0.99.0: explicit expired_at — never rely on bePaid's implicit default
        _erip_ttl = getattr(self.settings, "payment_provider_link_ttl_hours", 72)
        _erip_expired_at = due_at_for_bepaid(_erip_ttl)
        payload = BePaidClient.build_erip_payload(
            amount_minor=int(pi["amount_minor"]),
            currency=str(pi.get("currency") or "BYN"),
            description=description,
            account_number=account_number,
            tracking_id=tracking_id,
            order_id=order_id,
            notification_url=notification_url,
            expired_at=_erip_expired_at,
        )

        shop_id = self.settings.bepaid_erip_shop_id
        log.info(
            "bepaid create_erip public_id=%s account_number=%s order_id=%s "
            "shop_id_len=%d shop_id_last4=%s",
            public_id, account_number, order_id,
            len(shop_id), shop_id[-4:] if len(shop_id) >= 4 else "****",
        )

        client = BePaidClient(
            shop_id=shop_id,
            secret_key=self.settings.bepaid_erip_secret_key,
            timeout=self.settings.bepaid_request_timeout,
        )
        result = client.create_erip_payment(payload)

        # ── Ambiguous result: invoice may or may not exist ────────────────────────
        if result.requires_check:
            self.storage.payment_intent_mark_requires_check(
                public_id, result.error or "ambiguous_result"
            )
            log.warning(
                "bepaid ambiguous_result public_id=%s http=%s error=%s",
                public_id, result.http_status, result.error,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "Статус счёта неизвестен. Новый счёт не создавался повторно. "
                    "Требуется проверить операцию в bePaid."
                ),
            }

        # ── Definitive client-side error (4xx): invoice was NOT created ───────────
        if not result.ok:
            self.storage.payment_intent_release_claim(public_id, original_status, result.error)
            log.warning(
                "bepaid client_error public_id=%s http=%s error=%s",
                public_id, result.http_status, result.error,
            )
            return {
                "ok": False,
                "error": f"bePaid вернул ошибку (HTTP {result.http_status}): {result.error}",
            }

        # ── Validate success response fields ──────────────────────────────────────
        tx_uid = str(result.data.get("transaction_uid") or "").strip()

        if not tx_uid:
            self.storage.payment_intent_mark_requires_check(public_id, "missing_uid_in_response")
            log.error("bepaid http2xx_no_uid public_id=%s", public_id)
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "Статус счёта неизвестен. Новый счёт не создавался повторно. "
                    "bePaid вернул HTTP 200 без UID транзакции. Требуется проверка."
                ),
            }

        resp_amount = result.data.get("amount_minor")
        if resp_amount is not None and int(resp_amount) != int(pi["amount_minor"]):
            self.storage.payment_intent_mark_requires_check(
                public_id, f"amount_mismatch:{resp_amount}!={pi['amount_minor']}"
            )
            log.error(
                "bepaid amount_mismatch public_id=%s expected=%s got=%s",
                public_id, pi["amount_minor"], resp_amount,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": "Сумма в ответе bePaid не совпадает с суммой черновика. Требуется проверка.",
            }

        resp_currency = str(result.data.get("currency") or "").strip()
        if resp_currency and resp_currency != "BYN":
            self.storage.payment_intent_mark_requires_check(
                public_id, f"currency_mismatch:{resp_currency}"
            )
            log.error(
                "bepaid currency_mismatch public_id=%s expected=BYN got=%s",
                public_id, resp_currency,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": f"Валюта в ответе bePaid не BYN ({resp_currency}). Требуется проверка.",
            }

        resp_tracking = str(result.data.get("tracking_id") or "").strip()
        if resp_tracking and resp_tracking != tracking_id:
            self.storage.payment_intent_mark_requires_check(
                public_id, f"tracking_id_mismatch:{resp_tracking}"
            )
            log.error(
                "bepaid tracking_id_mismatch public_id=%s expected=%s got=%s",
                public_id, tracking_id, resp_tracking,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": "tracking_id в ответе bePaid не совпадает. Требуется проверка.",
            }

        resp_order_id = str(result.data.get("order_id") or "").strip()
        if resp_order_id and resp_order_id != order_id:
            self.storage.payment_intent_mark_requires_check(
                public_id, f"order_id_mismatch:{resp_order_id}"
            )
            log.error(
                "bepaid order_id_mismatch public_id=%s expected=%s got=%s",
                public_id, order_id, resp_order_id,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": "order_id в ответе bePaid не совпадает. Требуется проверка.",
            }

        # ── All checks passed — save success ──────────────────────────────────────
        bp_order_id = resp_order_id or order_id
        bp_account_number = str(result.data.get("erip_account_number") or account_number)
        bp_pay_url = str(result.data.get("pay_url") or "")
        bp_status = str(result.data.get("status") or "pending")
        bp_qr_code_raw = str(result.data.get("qr_code_raw") or "")

        updated = self.storage.payment_intent_save_bepaid_success(
            public_id,
            bepaid_uid=tx_uid,
            bepaid_order_id=bp_order_id,
            bepaid_account_number=bp_account_number,
            bepaid_payment_url=bp_pay_url,
            bepaid_status=bp_status,
            bepaid_qr_code_raw=bp_qr_code_raw,
        )

        # v7.0.99.0: upsert ERIP option row so expires_at and renewal_count are tracked
        _erip_opt_now = now_iso()
        try:
            _existing_erip_opt = self.storage.get_option_by_channel(public_id, "erip")
            if _existing_erip_opt:
                self.storage.update_option_expires_at(
                    _existing_erip_opt["id"], _erip_expired_at, _erip_opt_now
                )
            else:
                self.storage.create_payment_intent_option(
                    payment_intent_id=pi_row_id,
                    intent_public_id=public_id,
                    channel="erip",
                    shop_type="erip",
                    bepaid_order_id=bp_order_id,
                    bepaid_tracking_id=tracking_id,
                    bepaid_uid=tx_uid,
                    bepaid_account_number=bp_account_number,
                    payment_url=bp_pay_url,
                    qr_code_raw=bp_qr_code_raw,
                    expires_at=_erip_expired_at,
                )
            # Audit: record this as attempt 1 in checkout_attempts
            self.storage.create_checkout_attempt(
                intent_public_id=public_id,
                provider="bepaid_erip",
                channel="erip",
                attempt_number=1,
                expires_at=_erip_expired_at,
                now=_erip_opt_now,
                bepaid_uid=tx_uid,
                bepaid_order_id=bp_order_id,
                bepaid_account_number=bp_account_number,
            )
        except Exception:
            log.warning("bepaid_erip: could not upsert option/attempt for %s", public_id)

        log.info(
            "bepaid success public_id=%s bepaid_uid=%s account_number=%s expires_at=%s",
            public_id, tx_uid, bp_account_number, _erip_expired_at,
        )

        return {
            "ok": True,
            "intent": updated or pi,
            "bepaid_uid": tx_uid,
            "account_number": bp_account_number,
            "message": f"Счёт bePaid ERIP выставлен. Номер счёта: {bp_account_number}.",
        }

    def payment_intent_create_acquiring_option(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/create-acquiring — create or return hosted checkout.

        Idempotent: if acquiring option already exists with checkout_token, returns existing
        payment_url without creating a new checkout.
        """
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Черновик не найден", "public_id": public_id}

        if pi.get("client_visibility") == "withdrawn":
            return {
                "ok": False,
                "error": "Этот счёт отозван и больше не доступен для оплаты.",
                "withdrawn": True,
            }

        status = pi["status"]
        allowed_statuses = {"draft", "ready", "bepaid_created", "partial_ready", "awaiting_payment"}
        if status not in allowed_statuses:
            return {
                "ok": False,
                "error": (
                    f"Нельзя создать checkout для черновика в статусе '{status}'. "
                    f"Доступно для статусов: {', '.join(sorted(allowed_statuses))}."
                ),
            }

        # ── Pre-flight config check ───────────────────────────────────────────────
        cfg = self.settings
        missing_cfg: list[str] = []
        if not getattr(cfg, "bepaid_acq_shop_id", ""):
            missing_cfg.append("BEPAID_ACQ_SHOP_ID")
        if not getattr(cfg, "bepaid_acq_secret_key", ""):
            missing_cfg.append("BEPAID_ACQ_SECRET_KEY")
        if not getattr(cfg, "bepaid_public_base_url", ""):
            missing_cfg.append("BEPAID_PUBLIC_BASE_URL")
        if not getattr(cfg, "bepaid_webhook_path_secret", ""):
            missing_cfg.append("BEPAID_WEBHOOK_PATH_SECRET")
        if missing_cfg:
            return {
                "ok": False,
                "error": (
                    f"Не настроены обязательные переменные: {', '.join(missing_cfg)}. "
                    "Checkout не создан."
                ),
            }

        # ── Idempotency / self-healing: return existing active token or create new ──
        existing = self.storage.get_option_by_channel(public_id, "acquiring")
        _acq_ttl = getattr(cfg, "payment_provider_link_ttl_hours", 72)
        _acq_expired_at = due_at_for_bepaid(_acq_ttl)
        if existing and existing.get("checkout_token") and existing.get("payment_url"):
            # v7.0.99.0: check if existing token is still valid
            _opt_expires = str(existing.get("expires_at") or "").strip()
            _opt_status = str(existing.get("status") or "").strip()
            import datetime as _dt_acq
            _token_is_expired = (
                _opt_status == "expired"
                or (
                    _opt_expires
                    and _opt_expires < _dt_acq.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
                )
            )
            if not _token_is_expired:
                return {
                    "ok": True,
                    "already_exists": True,
                    "payment_url": existing["payment_url"],
                    "checkout_token": existing["checkout_token"],
                    "message": "Checkout уже создан.",
                }
            # Token expired — fall through to create a fresh checkout below

        # ── Build URLs ────────────────────────────────────────────────────────────
        base_url = cfg.bepaid_public_base_url.rstrip("/")
        path_secret = cfg.bepaid_webhook_path_secret
        notification_url = f"{base_url}/api/integrations/bepaid/webhook/acquiring/{path_secret}"
        return_url = f"{base_url}/payment-return"

        # ── Build tracking_id (stable per intent) ────────────────────────────────
        tracking_id = f"{public_id}_acq"

        # ── Description ──────────────────────────────────────────────────────────
        description = build_erip_description(pi)

        # ── Create option row before calling bePaid ───────────────────────────────
        pi_row_id = int(pi["id"])
        if existing:
            option = existing
        else:
            option = self.storage.create_payment_intent_option(
                payment_intent_id=pi_row_id,
                intent_public_id=public_id,
                channel="acquiring",
                shop_type="acquiring",
                bepaid_tracking_id=tracking_id,
            )

        option_id = int(option["id"])
        acq_shop_id = cfg.bepaid_acq_shop_id

        log.info(
            "bepaid create_acquiring_checkout public_id=%s tracking_id=%s "
            "shop_id_len=%d shop_id_last4=%s",
            public_id, tracking_id,
            len(acq_shop_id), acq_shop_id[-4:] if len(acq_shop_id) >= 4 else "****",
        )

        client = BePaidClient(
            shop_id=acq_shop_id,
            secret_key=cfg.bepaid_acq_secret_key,
            timeout=getattr(cfg, "bepaid_request_timeout", 30),
        )
        result = client.create_acquiring_checkout(
            amount_minor=int(pi["amount_minor"]),
            currency=str(pi.get("currency") or "BYN"),
            description=description,
            tracking_id=tracking_id,
            notification_url=notification_url,
            return_url=return_url,
            expired_at=_acq_expired_at,
        )

        # ── Ambiguous: checkout may or may not have been created ──────────────────
        if result.requires_check:
            log.warning(
                "bepaid acquiring ambiguous_result public_id=%s http=%s error=%s",
                public_id, result.http_status, result.error,
            )
            return {
                "ok": False,
                "requires_check": True,
                "error": (
                    "Статус checkout неизвестен (таймаут или ошибка сети). "
                    "Проверьте вручную в личном кабинете bePaid."
                ),
            }

        # ── Definitive error ──────────────────────────────────────────────────────
        if not result.ok:
            log.warning(
                "bepaid acquiring client_error public_id=%s http=%s error=%s",
                public_id, result.http_status, result.error,
            )
            return {
                "ok": False,
                "error": f"bePaid вернул ошибку (HTTP {result.http_status}): {result.error}",
            }

        # ── Success: save token and payment_url ──────────────────────────────────
        checkout_token = str(result.data["checkout_token"])
        payment_url = str(result.data["payment_url"])

        self.storage.update_option_checkout(
            option_id,
            checkout_token=checkout_token,
            payment_url=payment_url,
        )

        # v7.0.99.0: store expires_at and create audit attempt record
        try:
            self.storage.update_option_expires_at(option_id, _acq_expired_at, now_iso())
            _prev_attempt = self.storage.get_current_renewal_count(public_id, "acquiring")
            _acq_attempt_num = _prev_attempt + (1 if existing and existing.get("checkout_token") else 0)
            _acq_attempt_num = max(1, _acq_attempt_num)
            self.storage.create_checkout_attempt(
                intent_public_id=public_id,
                provider="bepaid_acq",
                channel="acquiring",
                attempt_number=_acq_attempt_num,
                expires_at=_acq_expired_at,
                now=now_iso(),
                checkout_token=checkout_token,
                payment_url=payment_url,
            )
        except Exception:
            log.warning("acquiring: could not save checkout_attempt for %s", public_id)

        # ── Update parent intent status ───────────────────────────────────────────
        if status == "bepaid_created":
            new_status = "awaiting_payment"
        elif status not in ("partial_ready", "awaiting_payment"):
            new_status = "partial_ready"
        else:
            new_status = status

        if new_status != status:
            self.storage.payment_intent_update_status(public_id, new_status)

        log.info(
            "bepaid acquiring success public_id=%s token_prefix=%s new_status=%s",
            public_id, checkout_token[:8] if len(checkout_token) >= 8 else "***", new_status,
        )

        return {
            "ok": True,
            "payment_url": payment_url,
            "checkout_token": checkout_token,
            "message": "Checkout создан. Страница оплаты картой готова.",
        }

    def payment_intent_prepare_options(
        self, auth: dict[str, Any], public_id: str
    ) -> dict[str, Any]:
        """POST /api/payments/intents/{id}/prepare-options — create or ensure both ERIP and acquiring options.

        Creates ERIP (bePaid ERIP invoice) and acquiring (hosted checkout) payment options
        for a single parent intent. Idempotent: repeat calls return existing options without
        new bePaid API calls. Either channel failing does NOT remove the other.

        Status transitions:
          draft/ready + both succeed → awaiting_payment
          draft/ready + only ERIP    → bepaid_created (standard ERIP flow)
          bepaid_created + ACQ       → awaiting_payment
          draft/ready + only ACQ     → partial_ready
        """
        denied = self._require_payment_intent_access(auth)
        if denied:
            return denied

        pi = self.storage.get_payment_intent(public_id)
        if not pi:
            return {"ok": False, "error": "Черновик не найден", "public_id": public_id}

        status = pi["status"]
        blocked_statuses = {"cancelled", "paid", "posted_to_moyklass"}
        if status in blocked_statuses:
            return {
                "ok": False,
                "error": f"Нельзя подготовить способы оплаты для статуса '{status}'.",
            }

        # Preflight: verify MK invoice still exists before creating any options
        if is_moyklass_invoice_intent(pi) and pi.get("mk_invoice_id"):
            mk_check = self._preflight_mk_invoice(pi)
            if not mk_check["ok"]:
                return mk_check

        # ── ERIP option ───────────────────────────────────────────────────────────
        erip_result: dict[str, Any]
        cfg = self.settings

        erip_already_created = (status in ("bepaid_created", "awaiting_payment") and pi.get("bepaid_uid"))
        if erip_already_created:
            erip_result = {
                "ok": True,
                "already_exists": True,
                "channel": "erip",
                "account_number": pi.get("bepaid_account_number"),
                "uid": pi.get("bepaid_uid"),
            }
        elif status in ("bepaid_requires_check", "bepaid_creating"):
            erip_result = {
                "ok": False,
                "skipped": True,
                "error": f"ERIP creation blocked by current status: {status}",
            }
        elif not (getattr(cfg, "bepaid_erip_shop_id", "") and getattr(cfg, "bepaid_erip_secret_key", "")
                  and getattr(cfg, "bepaid_public_base_url", "") and getattr(cfg, "bepaid_webhook_path_secret", "")):
            erip_result = {"ok": False, "skipped": True, "error": "BEPAID_ERIP_SHOP_ID or other ERIP config missing"}
        else:
            # Call existing ERIP creation, bypassing payment_method restriction
            _erip_r = self.payment_intent_create_bepaid(
                auth, public_id, {}, _bypass_method_check=True
            )
            erip_result = {
                "ok": bool(_erip_r.get("ok")),
                "channel": "erip",
                "already_exists": bool(_erip_r.get("already_exists")),
                "account_number": None,
                "uid": None,
                "error": _erip_r.get("error") if not _erip_r.get("ok") else None,
                "requires_check": bool(_erip_r.get("requires_check")),
            }

        # Refresh pi after ERIP changes (status may have transitioned)
        pi = self.storage.get_payment_intent(public_id) or pi

        # ── Acquiring option ──────────────────────────────────────────────────────
        acq_result: dict[str, Any]
        if not (getattr(cfg, "bepaid_acq_shop_id", "") and getattr(cfg, "bepaid_acq_secret_key", "")
                and getattr(cfg, "bepaid_public_base_url", "") and getattr(cfg, "bepaid_webhook_path_secret", "")):
            acq_result = {"ok": False, "skipped": True, "error": "BEPAID_ACQ_SHOP_ID or other ACQ config missing"}
        else:
            try:
                _acq_r = self.payment_intent_create_acquiring_option(auth, public_id)
                acq_result = {
                    "ok": bool(_acq_r.get("ok")),
                    "channel": "acquiring",
                    "already_exists": bool(_acq_r.get("already_exists")),
                    "payment_url": _acq_r.get("payment_url"),
                    "error": _acq_r.get("error") if not _acq_r.get("ok") else None,
                    "requires_check": bool(_acq_r.get("requires_check")),
                }
            except Exception as _acq_exc:
                log.warning(
                    "bepaid prepare_options acquiring_exception public_id=%s type=%s",
                    public_id, type(_acq_exc).__name__,
                )
                acq_result = {
                    "ok": False,
                    "channel": "acquiring",
                    "error": f"unexpected_error:{type(_acq_exc).__name__}",
                    "requires_check": True,
                }

        # Refresh pi one more time
        pi = self.storage.get_payment_intent(public_id) or pi

        erip_ok = bool(erip_result.get("ok"))
        acq_ok = bool(acq_result.get("ok"))

        # Enrich erip_result with live pi data
        if erip_ok:
            erip_result["account_number"] = pi.get("bepaid_account_number")
            erip_result["uid"] = pi.get("bepaid_uid")

        log.info(
            "bepaid prepare_options public_id=%s erip_ok=%s acq_ok=%s new_status=%s",
            public_id, erip_ok, acq_ok, pi.get("status"),
        )

        options_out = []
        if not erip_result.get("skipped"):
            options_out.append({
                "channel": "erip",
                "status": "ready" if erip_ok else ("requires_check" if erip_result.get("requires_check") else "error"),
                "account_number": erip_result.get("account_number"),
                "uid": erip_result.get("uid"),
                "already_exists": bool(erip_result.get("already_exists")),
                "error": erip_result.get("error"),
            })
        if not acq_result.get("skipped"):
            options_out.append({
                "channel": "acquiring",
                "status": "ready" if acq_ok else ("requires_check" if acq_result.get("requires_check") else "error"),
                "payment_url": acq_result.get("payment_url"),
                "already_exists": bool(acq_result.get("already_exists")),
                "error": acq_result.get("error"),
            })

        overall_ok = erip_ok or acq_ok
        if erip_ok and acq_ok:
            msg = "Оба способа оплаты готовы."
        elif erip_ok:
            msg = "ЕРИП готов. Эквайринг не создан."
        elif acq_ok:
            msg = "Страница оплаты картой готова. ЕРИП не создан."
        else:
            msg = "Не удалось создать ни один способ оплаты."

        return {
            "ok": overall_ok,
            "intent": self._normalize_payment_intent(dict(pi)),
            "options": options_out,
            "message": msg,
        }

    # ── v7.0.94.1 — Invoice Automation API handlers ──────────────────────────
    # Role is always resolved server-side via _role_for_user(); the role field
    # in the auth payload is ignored so stale/spoofed values cannot grant access.

    def _automation_effective_role(self, auth: dict[str, Any]) -> str:
        """Return the canonical effective role for automation access checks.

        Uses _role_for_user() which honours test-role mode, same as all other
        handlers in this codebase.  Never trusts auth["role"] from the frontend.
        """
        try:
            return self._role_for_user(int(auth["user_id"]))
        except (KeyError, TypeError, ValueError):
            return "other"

    def _automation_deny(self, action: str, uid: Any, role: str, required: str) -> dict[str, Any]:
        log.warning("invoice automation access denied: uid=%s role=%s action=%s required=%s",
                    uid, role, action, required)
        return {"ok": False, "error": "Нет доступа"}

    def _fetch_mk_student_name(self, mk_user_id: int) -> Optional[str]:
        """Fetch student full name from MoyKlass /v1/company/users/{id}. Returns None on failure."""
        try:
            result = self.moyklass.request("GET", f"/v1/company/users/{mk_user_id}")
            if result.ok and isinstance(result.data, dict):
                u = result.data
                name = str(u.get("name") or "").strip()
                if not name:
                    name = " ".join(filter(None, [
                        str(u.get("clientName") or u.get("lastName") or ""),
                        str(u.get("firstName") or ""),
                        str(u.get("middleName") or u.get("patronymic") or ""),
                    ])).strip()
                if name and not name.startswith("userId="):
                    return name
        except Exception:
            log.warning("_fetch_mk_student_name: failed for mk_user_id=%s", mk_user_id)
        return None

    # ── v7.1.5 — Payments Workspace ──────────────────────────────────────────

    def _require_workspace_access(self, auth: dict[str, Any]) -> Optional[dict[str, Any]]:
        if auth.get("_internal") is True:
            return None
        role = self._role_for_user(int(auth["user_id"]))
        if role not in WORKSPACE_VIEW_ROLES:
            return {"ok": False, "error": "Нет доступа к рабочему пространству платежей."}
        return None

    # ── v7.1.16.1 — Payments Workspace period filtering ──────────────────────
    # Same "app timezone" convention as _communications_minsk_to_utc (v7.1.14):
    # zoneinfo.ZoneInfo("Europe/Minsk"), DST-safe, imported locally per the
    # established pattern in this file. period_start/period_end_exclusive are
    # plain 'YYYY-MM-DD' calendar-date strings — never a datetime/UTC
    # instant — so there is no cross-timezone ambiguity when they're compared
    # against the canonical period_start expression in storage.py.
    _PAYMENTS_PERIOD_MONTHS_NOMINATIVE = [
        "январь", "февраль", "март", "апрель", "май", "июнь",
        "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь",
    ]
    _PAYMENTS_PERIOD_MONTHS_GENITIVE = [
        "января", "февраля", "марта", "апреля", "мая", "июня",
        "июля", "августа", "сентября", "октября", "ноября", "декабря",
    ]

    def _payments_period_fmt_date(self, d) -> str:
        return f"{d.day} {self._PAYMENTS_PERIOD_MONTHS_GENITIVE[d.month - 1]} {d.year}"

    def _parse_payments_period(self, params: dict[str, str]) -> dict[str, Any]:
        """Normalizes period_mode/period_start/period_end query params into
        {"ok": True, "mode", "start", "end_exclusive", "label"} — start/
        end_exclusive are None for mode="all" (no filter). Defaults to the
        current billing month in Europe/Minsk when mode="month" and no
        period_start is given. Never trusts client-computed "today"."""
        import zoneinfo
        mode = str(params.get("period_mode") or "month").strip()
        if mode not in ("month", "custom", "all"):
            return {"ok": False, "error": "Некорректный режим периода."}
        if mode == "all":
            return {"ok": True, "mode": "all", "start": None, "end_exclusive": None, "label": "Всё время"}

        today_minsk = datetime.now(zoneinfo.ZoneInfo("Europe/Minsk")).date()

        if mode == "month":
            raw_month = str(params.get("period_start") or "").strip()
            if re.match(r"^\d{4}-\d{2}$", raw_month):
                year, mon = int(raw_month[:4]), int(raw_month[5:7])
            else:
                year, mon = today_minsk.year, today_minsk.month
            try:
                start = date(year, mon, 1)
            except ValueError:
                return {"ok": False, "error": "Некорректный месяц."}
            end_exclusive = date(year + 1, 1, 1) if mon == 12 else date(year, mon + 1, 1)
            label = f"Расчётный период: {self._PAYMENTS_PERIOD_MONTHS_NOMINATIVE[mon - 1]} {year}"
            return {"ok": True, "mode": "month", "start": start.isoformat(), "end_exclusive": end_exclusive.isoformat(), "label": label}

        # mode == "custom"
        raw_start = str(params.get("period_start") or "").strip()
        raw_end = str(params.get("period_end") or "").strip()
        try:
            start = date.fromisoformat(raw_start)
            end_inclusive = date.fromisoformat(raw_end)
        except ValueError:
            return {"ok": False, "error": "Укажите обе даты в формате ГГГГ-ММ-ДД."}
        if end_inclusive < start:
            return {"ok": False, "error": "Дата окончания не может быть раньше даты начала."}
        end_exclusive = end_inclusive + timedelta(days=1)
        label = f"Период: {self._payments_period_fmt_date(start)} – {self._payments_period_fmt_date(end_inclusive)}"
        return {"ok": True, "mode": "custom", "start": start.isoformat(), "end_exclusive": end_exclusive.isoformat(), "label": label}

    def payments_workspace_stats(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_workspace_access(auth)
        if denied:
            return denied
        period = self._parse_payments_period(params)
        if not period.get("ok"):
            return period
        stats = self.storage.get_payments_workspace_stats(period.get("start"), period.get("end_exclusive"))
        stats["period"] = {"mode": period["mode"], "start": period.get("start"), "endExclusive": period.get("end_exclusive"), "label": period["label"]}
        stats["attentionOutsidePeriodCount"] = self.storage.get_payments_attention_outside_period_count(period.get("start"), period.get("end_exclusive"))
        return stats

    def payments_workspace_attention(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_workspace_access(auth)
        if denied:
            return denied
        period = self._parse_payments_period(params)
        if not period.get("ok"):
            return period
        limit = max(1, min(int(params.get("limit", 50)), 200))
        items = self.storage.get_payments_attention_queue(limit=limit, period_start=period.get("start"), period_end_exclusive=period.get("end_exclusive"))
        return {"ok": True, "items": items, "count": len(items), "period": {"mode": period["mode"], "label": period["label"]}}

    def payments_workspace_list(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        """GET /api/payments/workspace/list — server-side period-filtered
        "Все платежи", distinct from the pre-existing /api/payments/intents
        (which stays exact-month/unfiltered-by-default for its other
        callers, untouched). Paginated (limit/offset) instead of the old
        client-side-filtered ≤200-row cap."""
        denied = self._require_workspace_access(auth)
        if denied:
            return denied
        period = self._parse_payments_period(params)
        if not period.get("ok"):
            return period
        raw_status = str(params.get("status") or "all").strip()
        status = raw_status if raw_status in self._PI_VALID_STATUS_VALUES else "all"
        try:
            limit = max(1, min(int(params.get("limit") or 50), 200))
        except (TypeError, ValueError):
            limit = 50
        try:
            offset = max(0, int(params.get("offset") or 0))
        except (TypeError, ValueError):
            offset = 0
        intents, total = self.storage.list_payment_intents_by_period(
            period_start=period.get("start"),
            period_end_exclusive=period.get("end_exclusive"),
            status=status if status != "all" else None,
            exclude_cancelled=(status == "all"),
            limit=limit,
            offset=offset,
        )
        intents = [self._normalize_payment_intent(pi) for pi in intents]
        for pi in intents:
            opts = self.storage.get_options_for_intent(pi["public_id"])
            pi["payment_options"] = [
                {
                    "channel": o.get("channel"),
                    "status": o.get("status"),
                    "account_number": o.get("bepaid_account_number"),
                    "uid": o.get("bepaid_uid"),
                    "payment_url": o.get("payment_url"),
                    "has_checkout": bool(o.get("checkout_token")),
                }
                for o in opts
            ]
        withdrawn_ids = [pi["public_id"] for pi in intents if pi.get("client_visibility") == "withdrawn"]
        if withdrawn_ids:
            withdrawals = self.storage.get_withdrawals_for_intents(withdrawn_ids)
            for pi in intents:
                if pi.get("client_visibility") == "withdrawn":
                    wr = withdrawals.get(pi["public_id"])
                    if wr:
                        pi["withdrawal"] = {
                            "status": wr.get("status"),
                            "reason": wr.get("reason"),
                            "requested_at": wr.get("requested_at"),
                            "completed_at": wr.get("completed_at"),
                        }
        return {
            "ok": True,
            "intents": intents,
            "total": total,
            "limit": limit,
            "offset": offset,
            "status_filter": status,
            "period": {"mode": period["mode"], "start": period.get("start"), "endExclusive": period.get("end_exclusive"), "label": period["label"]},
        }

    # ── v7.1.9 — Payment Automation Guardian diagnostics ─────────────────────

    _GUARDIAN_HEARTBEAT_STALE_KEY = "scheduler_heartbeat_missing"
    _GUARDIAN_HEARTBEAT_GRACE_SECONDS = 120  # on top of 2 x quick-cycle interval

    def _require_diagnostics_view_access(self, auth: dict[str, Any]) -> Optional[dict[str, Any]]:
        if auth.get("_internal") is True:
            return None
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_DIAGNOSTICS_VIEW_ROLES:
            return {"ok": False, "error": "Нет доступа к диагностике платёжной автоматизации."}
        return None

    def _require_diagnostics_manage_access(self, auth: dict[str, Any]) -> Optional[dict[str, Any]]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PAYMENT_DIAGNOSTICS_MANAGE_ROLES:
            return {"ok": False, "error": "Действие доступно только owner/admin/operations."}
        return None

    def _check_guardian_heartbeat(self, now: str) -> bool:
        """Best-effort staleness check — safe to call from any live component
        (Diagnostics API, InvoiceAutomationScheduler's own cycle, process
        startup) so a dead Guardian thread can be detected by something
        OTHER than the dead thread itself. Pure DB read + conditional
        incident upsert/resolve — no MoyKlass calls. Returns True if stale.
        """
        try:
            last_ok = self.storage.get_last_successful_health_run("quick_cycle")
        except Exception:
            return False
        threshold = (
            2 * PaymentAutomationGuardian.QUICK_CYCLE_INTERVAL_SECONDS
            + self._GUARDIAN_HEARTBEAT_GRACE_SECONDS
        )
        if last_ok is None:
            # Never run yet — not "stale", just "no data" (handled separately
            # in the diagnostics summary); nothing to flag here.
            return False
        try:
            from datetime import datetime
            last_dt = datetime.fromisoformat(str(last_ok.get("heartbeat_at") or last_ok.get("started_at")))
            now_dt = datetime.fromisoformat(now)
            stale = (now_dt - last_dt).total_seconds() > threshold
        except Exception:
            return False
        if stale:
            self.storage.upsert_incident(
                self._GUARDIAN_HEARTBEAT_STALE_KEY, component=par.COMPONENT_SCHEDULER,
                scope_type=par.SCOPE_SYSTEM, scope_id="", reason_code="scheduler_heartbeat_missing",
                severity=par.SEVERITY_CRITICAL, now=now,
                payload={"last_successful_run_at": str(last_ok.get("started_at") or "")},
            )
        else:
            self.storage.resolve_incident(self._GUARDIAN_HEARTBEAT_STALE_KEY, now)
        return stale

    def _diagnostics_incident_view(self, inc: dict[str, Any]) -> dict[str, Any]:
        """Sanitized incident shape for API responses — never includes raw
        payload_json, provider codes, or exceptions; only the already-
        curated reason-registry text."""
        info = par.get_reason_info(inc.get("reason_code"))
        return {
            "id": inc.get("id"),
            "component": inc.get("component"),
            "scope_type": inc.get("scope_type"),
            "reason_code": inc.get("reason_code"),
            "severity": inc.get("severity"),
            "status": inc.get("status"),
            "title": par.reason_user_title(inc.get("reason_code")),
            "message": par.reason_user_message(inc.get("reason_code")),
            "recovery_condition": info.recovery_condition if info else "",
            "first_seen_at": inc.get("first_seen_at"),
            "last_seen_at": inc.get("last_seen_at"),
            "occurrence_count": inc.get("occurrence_count"),
            "repair_status": inc.get("repair_status"),
            "repair_attempt_count": inc.get("repair_attempt_count"),
            "automation_item_id": (
                inc.get("scope_id") if inc.get("scope_type") == "automation_item" else None
            ),
            "intent_public_id": (
                inc.get("scope_id") if inc.get("scope_type") == "payment_intent" else None
            ),
        }

    # v7.1.10 — informational-only "what happens next" note for a recovered
    # training incident, by pilot mode. Never itself triggers any action —
    # purely describes what the ordinary scheduler pipeline will do.
    _PILOT_MODE_RESUME_NOTE = {
        "auto": "Следующий цикл автоматизации может создать и отправить оплату автоматически.",
        "review": "Черновик будет ждать проверки клиент-менеджера, как обычно.",
        "observe": "Автоматизация продолжит только наблюдение, без создания платежей.",
        "disabled": "Автоматизация для этого клиента отключена — новые платежи не создаются.",
        "not_in_pilot": "Клиент не подключён к пилоту — новые платежи не создаются.",
    }

    def _diagnostics_recovered_incident_view(self, inc: dict[str, Any]) -> dict[str, Any]:
        """Sanitized 'recently recovered' incident shape — same safety rules
        as _diagnostics_incident_view. Training-state recoveries (automatic
        resume) get the specific v7.1.10 recovery narrative and a pilot-
        mode-aware "what happens next" note; other components keep their
        existing curated title/message, just framed as resolved."""
        component = inc.get("component")
        scope_type = inc.get("scope_type")
        scope_id = inc.get("scope_id")
        pilot_mode: Optional[str] = None
        if component == par.COMPONENT_TRAINING_STATE and scope_type == "automation_item":
            title = "Обучение возобновлено"
            message = "Agent автоматически снял блокировку после подтверждения статуса «Учится» в МойКласс."
            try:
                item = self.storage.get_automation_item_by_id(int(scope_id))
                if item:
                    pilot = self.storage.get_pilot_client(str(item.get("mk_user_id") or ""))
                    pilot_mode = (pilot or {}).get("mode", "not_in_pilot")
            except (TypeError, ValueError):
                pilot_mode = None
        else:
            title = par.reason_user_title(inc.get("reason_code"))
            message = par.reason_user_message(inc.get("reason_code"))
        return {
            "id": inc.get("id"),
            "component": component,
            "scope_type": scope_type,
            "reason_code": inc.get("reason_code"),
            "severity": inc.get("severity"),
            "title": title,
            "message": message,
            "resolved_at": inc.get("resolved_at"),
            "occurrence_count": inc.get("occurrence_count"),
            "pilot_mode": pilot_mode,
            "pilot_mode_note": self._PILOT_MODE_RESUME_NOTE.get(pilot_mode, "") if pilot_mode else "",
            "automation_item_id": (
                inc.get("scope_id") if inc.get("scope_type") == "automation_item" else None
            ),
            "intent_public_id": (
                inc.get("scope_id") if inc.get("scope_type") == "payment_intent" else None
            ),
        }

    def payments_diagnostics(self, auth: dict[str, Any]) -> dict[str, Any]:
        """GET /api/payments/diagnostics — read-only Guardian/health summary.

        client_manager gets the same incident visibility as the rest of
        Payments Workspace (there is no "clients assigned to a specific
        client_manager" concept anywhere in this codebase — WORKSPACE_VIEW_ROLES
        already gives client_manager full read access to Attention/Overview/
        All-Payments) — but never the manage/repair actions
        (canManagePaymentDiagnostics gates those client-side and server-side).
        Never trusts anything from the request for scope resolution.
        """
        denied = self._require_diagnostics_view_access(auth)
        if denied:
            return denied
        now = now_iso()
        self._check_guardian_heartbeat(now)

        last_run = self.storage.get_last_health_run("quick_cycle")
        last_ok = self.storage.get_last_successful_health_run("quick_cycle")
        open_incidents = self.storage.list_open_incidents(limit=200)

        critical = [i for i in open_incidents if i.get("severity") == "critical"]
        warning = [i for i in open_incidents if i.get("severity") == "warning"]
        info_level = [i for i in open_incidents if i.get("severity") == "info"]
        def _is_retryable(inc: dict[str, Any]) -> bool:
            info = par.get_reason_info(inc.get("reason_code"))
            return bool(info.retryable) if info is not None else False
        retryable = [i for i in open_incidents if _is_retryable(i)]
        stale = [i for i in open_incidents if i.get("reason_code") == "stale_automation_item"]

        from datetime import datetime, timedelta
        today_start = datetime.now().strftime("%Y-%m-%dT00:00:00")
        resolved_today = self.storage.count_incidents_resolved_since(today_start)
        safe_repairs_today = int((last_run or {}).get("safe_repairs_performed") or 0)

        if last_run is None:
            guardian_status = "no_data"
        elif last_run.get("status") == "failed" or critical:
            guardian_status = "critical"
        elif last_run.get("status") == "degraded" or warning:
            guardian_status = "warning"
        else:
            guardian_status = "healthy"

        next_expected_at = None
        if last_run and last_run.get("started_at"):
            try:
                next_expected_at = (
                    datetime.fromisoformat(str(last_run["started_at"]))
                    + timedelta(seconds=PaymentAutomationGuardian.QUICK_CYCLE_INTERVAL_SECONDS)
                ).isoformat()
            except Exception:
                next_expected_at = None

        return {
            "ok": True,
            "guardian": {
                "status": guardian_status,
                "last_run_at": (last_run or {}).get("started_at"),
                "last_run_status": (last_run or {}).get("status"),
                "last_run_duration_ms": (last_run or {}).get("duration_ms"),
                "last_successful_run_at": (last_ok or {}).get("started_at"),
                "next_expected_run_at": next_expected_at,
                "checked_items": (last_run or {}).get("checked_items"),
                "checked_clients": (last_run or {}).get("checked_clients"),
                "quick_cycle_interval_seconds": PaymentAutomationGuardian.QUICK_CYCLE_INTERVAL_SECONDS,
            },
            "counts": {
                "open_critical": len(critical),
                "open_warning": len(warning),
                "open_info": len(info_level),
                "resolved_today": resolved_today,
                "safe_repairs_today": safe_repairs_today,
                "retryable_count": len(retryable),
                "stale_count": len(stale),
            },
            "incidents": [self._diagnostics_incident_view(i) for i in open_incidents],
            "recovered_incidents": [
                self._diagnostics_recovered_incident_view(i)
                for i in self.storage.list_recently_resolved_incidents(today_start, limit=20)
            ],
            "can_manage": bool(self._require_diagnostics_manage_access(auth) is None),
        }

    def payments_diagnostics_run(self, auth: dict[str, Any]) -> dict[str, Any]:
        """POST /api/payments/diagnostics/run — request an unscheduled
        Guardian cycle. Never creates financial side effects (same
        _run_quick_cycle() the background thread calls itself)."""
        denied = self._require_diagnostics_manage_access(auth)
        if denied:
            return denied
        now = now_iso()
        self.storage.create_automation_audit_event({
            "created_at": now, "event_type": "diagnostics_manual_run_requested",
            "initiator": str(auth.get("user_id") or ""),
        })
        guardian = PaymentAutomationGuardian(self)
        try:
            guardian._run_quick_cycle()
        except Exception as exc:
            log.exception("payments_diagnostics_run: cycle error")
            return {"ok": False, "error": f"Ошибка запуска диагностики: {exc}"}
        overlap = self.storage.get_incident(PaymentAutomationGuardian.OVERLAP_DEDUP_KEY)
        if overlap and overlap.get("status") == "open":
            return {"ok": False, "error": "already_running", "conflict": True}
        last_run = self.storage.get_last_health_run("quick_cycle")
        return {"ok": True, "run": last_run}

    def payments_diagnostics_incident_recheck(
        self, auth: dict[str, Any], incident_id: str,
    ) -> dict[str, Any]:
        """POST /api/payments/diagnostics/incidents/{id}/recheck — safe,
        read-only-effect recheck. For a training-state incident, delegates to
        the exact same forced-fresh helper the manual training-check button
        uses. Never accepts reason_code/mk_user_id/severity/subscription id
        from the request — always resolved server-side from the incident row."""
        denied = self._require_diagnostics_manage_access(auth)
        if denied:
            return denied
        try:
            iid = int(incident_id)
        except (TypeError, ValueError):
            return {"ok": False, "error": "invalid incident id"}
        inc = self.storage.get_incident_by_id(iid)
        if not inc:
            return {"ok": False, "error": "Инцидент не найден."}

        now = now_iso()
        actor = str(auth.get("user_id") or "")
        self.storage.create_automation_audit_event({
            "created_at": now, "event_type": "incident_manual_recheck",
            "initiator": actor, "details_json": __import__("json").dumps(
                {"incident_id": iid, "component": inc.get("component")}, ensure_ascii=False,
            ),
        })

        if inc.get("scope_type") == "automation_item" and inc.get("component") == par.COMPONENT_TRAINING_STATE:
            try:
                item_id = int(inc.get("scope_id") or 0)
            except (TypeError, ValueError):
                return {"ok": False, "error": "Некорректный элемент автоматизации."}
            item = self.storage.get_automation_item_by_id(item_id)
            if not item:
                return {"ok": False, "error": "Элемент автоматизации не найден."}
            mk_user_id, mk_user_subscription_id = self._resolve_training_context_for_item(item)
            if not mk_user_id:
                return {"ok": False, "error": "Не удалось определить клиента для этого элемента."}
            result = self._training_state_check_item(
                item, item_id, mk_user_id, mk_user_subscription_id, now, actor,
            )
            self.storage.create_repair_attempt(
                incident_id=iid, correlation_id=None, action_code="training_state_recheck",
                result="success" if result.get("ok") else "failed", now=now,
            )
            return result

        # System/other incidents — safe read-only recheck: re-evaluate
        # heartbeat staleness now; local integrity issues resolve themselves
        # via the next Guardian cycle's audit_payment_integrity() re-scan.
        if inc.get("reason_code") == "scheduler_heartbeat_missing":
            stale = self._check_guardian_heartbeat(now)
            self.storage.create_repair_attempt(
                incident_id=iid, correlation_id=None, action_code="heartbeat_recheck",
                result="success", now=now, detail={"stale": stale},
            )
            return {"ok": True, "stale": stale}

        self.storage.create_repair_attempt(
            incident_id=iid, correlation_id=None, action_code="generic_recheck",
            result="skipped", now=now,
        )
        return {"ok": True, "message": "Эта проверка обновляется автоматически со следующим циклом Guardian."}

    # ── v7.1.5 — Pilot client management ─────────────────────────────────────

    def pilot_list_clients(self, auth: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_workspace_access(auth)
        if denied:
            return denied
        clients = self.storage.list_pilot_clients()
        return {"ok": True, "clients": clients, "count": len(clients)}

    def pilot_upsert_client(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PILOT_MANAGE_ROLES:
            return {"ok": False, "error": "Управление клиентами пилота недоступно для данной роли."}
        mk_user_id = str(body.get("mk_user_id") or "").strip()
        if not mk_user_id:
            return {"ok": False, "error": "mk_user_id обязателен."}
        mode = str(body.get("mode") or "disabled").strip()
        if mode not in ("observe", "review", "auto", "disabled"):
            return {"ok": False, "error": "Допустимые режимы: observe, review, auto, disabled."}
        note = str(body.get("note") or "").strip() or None
        now = now_iso()
        existing = self.storage.get_pilot_client(mk_user_id)
        old_mode = existing.get("mode") if existing else None
        client = self.storage.upsert_pilot_client(
            mk_user_id=mk_user_id,
            mode=mode,
            note=note,
            added_by_tg_id=str(auth.get("user_id") or ""),
            added_by_name=str(auth.get("full_name") or ""),
            now=now,
        )
        actor_name = str(auth.get("full_name") or "").strip() or None
        self.storage.create_pilot_audit_event({
            "created_at": now,
            "event_type": "pilot_client_upserted",
            "mk_user_id": mk_user_id,
            "pilot_client_id": client.get("id"),
            "old_mode": old_mode,
            "new_mode": mode,
            "actor_tg_id": str(auth.get("user_id") or ""),
            "actor_name": actor_name,
            "note": note,
        })
        return {"ok": True, "client": client}

    def pilot_update_mode(self, auth: dict[str, Any], mk_user_id: str, body: dict[str, Any]) -> dict[str, Any]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PILOT_MANAGE_ROLES:
            return {"ok": False, "error": "Управление клиентами пилота недоступно для данной роли."}
        mk_user_id = str(mk_user_id).strip()
        existing = self.storage.get_pilot_client(mk_user_id)
        if not existing:
            return {"ok": False, "error": "Клиент не найден в пилоте."}
        new_mode = str(body.get("mode") or "").strip()
        if new_mode not in ("observe", "review", "auto", "disabled"):
            return {"ok": False, "error": "Допустимые режимы: observe, review, auto, disabled."}
        now = now_iso()
        old_mode = existing.get("mode")
        actor_name = str(auth.get("full_name") or "").strip() or None
        client = self.storage.update_pilot_mode(mk_user_id, new_mode, now=now)
        self.storage.create_pilot_audit_event({
            "created_at": now,
            "event_type": "pilot_mode_changed",
            "mk_user_id": mk_user_id,
            "pilot_client_id": existing.get("id"),
            "old_mode": old_mode,
            "new_mode": new_mode,
            "actor_tg_id": str(auth.get("user_id") or ""),
            "actor_name": actor_name,
        })
        return {"ok": True, "client": client}

    def pilot_remove_client(self, auth: dict[str, Any], mk_user_id: str) -> dict[str, Any]:
        role = self._role_for_user(int(auth["user_id"]))
        if role not in PILOT_MANAGE_ROLES:
            return {"ok": False, "error": "Управление клиентами пилота недоступно для данной роли."}
        mk_user_id = str(mk_user_id).strip()
        now = now_iso()
        existing = self.storage.get_pilot_client(mk_user_id)
        if not existing:
            return {"ok": False, "error": "Клиент не найден в пилоте."}
        pilot_client_id = existing.get("id")
        actor_name = str(auth.get("full_name") or "").strip() or None
        removed = self.storage.remove_pilot_client(mk_user_id)
        if removed:
            self.storage.create_pilot_audit_event({
                "created_at": now,
                "event_type": "pilot_client_removed",
                "mk_user_id": mk_user_id,
                "pilot_client_id": pilot_client_id,
                "old_mode": existing.get("mode"),
                "actor_tg_id": str(auth.get("user_id") or ""),
                "actor_name": actor_name,
            })
        return {"ok": removed, "removed": removed}

    # ═══════════════════════════════════════════════════════════════════
    # v7.1.17 — "Расписание" (continuing-students schedule foundation).
    # Every method starts with _require_schedule_module_access; mutating
    # methods additionally re-check their own feature flag server-side
    # (schedule_moyklass_sync_enabled / schedule_draft_mutations_enabled)
    # regardless of what the frontend currently shows.
    # ═══════════════════════════════════════════════════════════════════
    def _schedule_branch_hints(self) -> tuple[str, str]:
        return (
            str(getattr(self.settings, "food_location_yc1", "") or ""),
            str(getattr(self.settings, "food_location_yc2", "") or ""),
        )

    def _schedule_actor(self, auth: dict[str, Any]) -> tuple[Optional[int], str]:
        uid = int(auth.get("user_id") or 0) or None
        name = str(auth.get("full_name") or "").strip() or "Сотрудник"
        return uid, name

    def schedule_status(self, auth: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        return {
            "ok": True,
            "moyklassConfigured": bool(self.moyklass.is_configured),
            "syncEnabled": bool(getattr(self.settings, "schedule_moyklass_sync_enabled", False)),
            "mutationsEnabled": bool(getattr(self.settings, "schedule_draft_mutations_enabled", False)),
            "syncRunning": schedule_sync.is_sync_running(),
            "activeSnapshot": self.storage.get_active_schedule_snapshot(),
            "runningSnapshot": self.storage.get_running_schedule_snapshot(),
            "recentSnapshots": self.storage.list_schedule_snapshots(limit=5),
            "periodStart": SCHEDULE_SOURCE_PERIOD_START,
            "periodEnd": SCHEDULE_SOURCE_PERIOD_END,
        }

    def schedule_sync_start(self, auth: dict[str, Any], body: dict[str, Any]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        if not bool(getattr(self.settings, "schedule_moyklass_sync_enabled", False)):
            return {"ok": False, "error": "Синхронизация с МойКласс выключена.", "reason_code": "sync_disabled"}
        actor_id, actor_name = self._schedule_actor(auth)
        resume_raw = body.get("resume_snapshot_id")
        resume_id = _safe_int(resume_raw, 0) or None
        return schedule_sync.start_schedule_sync(self.storage, self.moyklass, actor_id, actor_name, resume_snapshot_id=resume_id)

    def schedule_sync_progress(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        snapshot_id = _safe_int(params.get("snapshot_id"), 0)
        snapshot = self.storage.get_schedule_snapshot(snapshot_id) if snapshot_id else self.storage.get_running_schedule_snapshot()
        if not snapshot:
            return {"ok": False, "error": "Snapshot не найден", "reason_code": "not_found"}
        errors = self.storage.list_schedule_sync_errors(snapshot["id"], limit=50) if snapshot.get("errors_count") else []
        return {
            "ok": True, "snapshot": snapshot,
            "stageLabel": schedule_sync.STAGE_LABELS_RU.get(snapshot.get("stage") or "", snapshot.get("stage") or ""),
            "errors": errors,
        }

    def schedule_stats(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        snapshot_id = _safe_int(params.get("snapshot_id"), 0) or None
        snapshot = self.storage.get_schedule_snapshot(snapshot_id) if snapshot_id else self.storage.get_active_schedule_snapshot()
        if not snapshot:
            return {"ok": True, "stats": None, "snapshot": None}
        yc1, yc2 = self._schedule_branch_hints()
        return {"ok": True, "stats": self.storage.get_schedule_overview_stats(snapshot["id"], yc1, yc2), "snapshot": snapshot}

    def schedule_groups_list(self, auth: dict[str, Any], params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        snapshot_id = _safe_int(params.get("snapshot_id"), 0) or None
        snapshot = self.storage.get_schedule_snapshot(snapshot_id) if snapshot_id else self.storage.get_active_schedule_snapshot()
        if not snapshot:
            return {"ok": True, "groups": [], "total": 0, "snapshot": None}
        limit = max(1, min(_safe_int(params.get("limit"), 50), 200))
        offset = max(0, _safe_int(params.get("offset"), 0))
        weekday = _safe_int(params.get("weekday"), 0) or None
        groups, total = self.storage.list_schedule_source_groups(
            snapshot["id"], branch=params.get("branch") or None, course=params.get("course") or None,
            teacher=params.get("teacher") or None, weekday=weekday, confidence=params.get("confidence") or None,
            search=params.get("search") or None, limit=limit, offset=offset,
        )
        return {"ok": True, "groups": groups, "total": total, "limit": limit, "offset": offset, "snapshot": snapshot}

    def schedule_group_detail(self, auth: dict[str, Any], group_id: str, params: dict[str, str]) -> dict[str, Any]:
        denied = self._require_schedule_module_access(auth)
        if denied:
            return denied
        gid = _safe_int(group_id, 0)
        group = self.storage.get_schedule_source_group(gid) if gid else None
        if not group:
            return {"ok": False, "error": "Группа не найдена", "reason_code": "not_found"}
        yc1, yc2 = self._schedule_branch_hints()
        group_branch_code = schedule_domain.branch_code_from_name(group.get("branch_name"), yc1, yc2)
        filter_continuation = params.get("continuation") or None
        filter_availability = params.get("availability") or None
        search = str(params.get("search") or "").strip().lower()
        # v7.1.17.1 pre-merge fix — bulk-resolved (chunk-bounded SQL), never
        # one resolve_schedule_student_status() call per student row.
        members = self.storage.list_schedule_source_group_students(gid)
        bulk_requests = [
            {
                "mk_user_id": s["mk_user_id"], "weekday": group.get("weekday"), "start_time": group.get("start_time"),
                "duration_minutes": group.get("duration_minutes"), "group_branch_code": group_branch_code,
            }
            for s in members
        ]
        statuses_by_user = {
            status["mk_user_id"]: status
            for status in self.storage.resolve_schedule_student_statuses_bulk(bulk_requests)
        }
        enriched = []
        for s in members:
            status = statuses_by_user.get(s["mk_user_id"], {})
            row = {**s, **status}
            if filter_continuation and row["continuation_status"] != filter_continuation:
                continue
            if filter_availability and row["availability_match"] != filter_availability:
                continue
            if search and search not in str(s.get("child_display_name") or "").lower():
                continue
            enriched.append(row)
        draft_rows, _dtotal = self.storage.list_schedule_drafts(source_snapshot_id=group["snapshot_id"], limit=200)
        linked_draft = next((d for d in draft_rows if d["source_group_id"] == gid), None)
        return {
            "ok": True, "group": group, "students": enriched, "studentsTotal": len(enriched),
            "lessons": self.storage.list_schedule_source_lessons_for_group(gid), "linkedDraft": linked_draft,
        }

